// Abstract Syntax Tree module for Metorex

pub mod node;

pub use node::{
    BinaryOp, ElsifBranch, Expression, InterpolationPart, MatchCase, MatchPattern, Parameter,
    RescueClause, Statement, UnaryOp,
};

// AST node definitions for Metorex

use crate::lexer::Position;
use std::fmt;

/// Binary operators in Metorex
#[derive(Debug, Clone, PartialEq)]
pub enum BinaryOp {
    // Arithmetic operators
    Add,      // +
    Subtract, // -
    Multiply, // *
    Divide,   // /
    Modulo,   // %

    // Comparison operators
    Equal,        // ==
    NotEqual,     // !=
    Less,         // <
    Greater,      // >
    LessEqual,    // <=
    GreaterEqual, // >=

    // Logical operators
    And, // &&
    Or,  // ||

    // Assignment operators
    Assign,         // =
    AddAssign,      // +=
    SubtractAssign, // -=
    MultiplyAssign, // *=
    DivideAssign,   // /=
}

/// Unary operators in Metorex
#[derive(Debug, Clone, PartialEq)]
pub enum UnaryOp {
    Plus,  // +
    Minus, // -
    Not,   // !
}

/// Expressions in Metorex - values that can be evaluated
#[derive(Debug, Clone, PartialEq)]
pub enum Expression {
    // Literals
    IntLiteral {
        value: i64,
        position: Position,
    },
    FloatLiteral {
        value: f64,
        position: Position,
    },
    StringLiteral {
        value: String,
        position: Position,
    },
    InterpolatedString {
        parts: Vec<InterpolationPart>,
        position: Position,
    },
    BoolLiteral {
        value: bool,
        position: Position,
    },
    NilLiteral {
        position: Position,
    },
    Symbol {
        value: String,
        position: Position,
    },

    // Identifiers and variables
    Identifier {
        name: String,
        position: Position,
    },
    InstanceVariable {
        name: String,
        position: Position,
    },
    ClassVariable {
        name: String,
        position: Position,
    },
    GlobalVariable {
        name: String,
        position: Position,
    },

    // Binary operations
    BinaryOp {
        op: BinaryOp,
        left: Box<Expression>,
        right: Box<Expression>,
        position: Position,
    },

    // Unary operations
    UnaryOp {
        op: UnaryOp,
        operand: Box<Expression>,
        position: Position,
    },

    // Function/method calls
    Call {
        callee: Box<Expression>,
        arguments: Vec<Expression>,
        /// Optional trailing block (e.g., `foo(x) do |y| ... end`)
        trailing_block: Option<Box<Expression>>,
        position: Position,
    },

    // Method calls with dot notation
    MethodCall {
        receiver: Box<Expression>,
        method: String,
        arguments: Vec<Expression>,
        /// Optional trailing block (e.g., `foo.bar(x) do |y| ... end`)
        trailing_block: Option<Box<Expression>>,
        position: Position,
    },

    // Array literals
    Array {
        elements: Vec<Expression>,
        position: Position,
    },

    // Array indexing
    Index {
        array: Box<Expression>,
        index: Box<Expression>,
        position: Position,
    },

    // Dictionary/hash literals
    Dictionary {
        entries: Vec<(Expression, Expression)>,
        position: Position,
    },

    // Lambda/block expressions
    Lambda {
        parameters: Vec<String>,
        body: Vec<Statement>,
        captured_vars: Option<Vec<String>>, // Variables captured from outer scope
        position: Position,
    },

    // Parenthesized expressions
    Grouped {
        expression: Box<Expression>,
        position: Position,
    },

    // Self reference (implicit receiver)
    SelfExpr {
        position: Position,
    },

    // Super call - calls parent class method
    Super {
        arguments: Vec<Expression>,
        position: Position,
    },

    // Range literals
    Range {
        start: Box<Expression>,
        end: Box<Expression>,
        exclusive: bool, // true for ..., false for ..
        position: Position,
    },

    // Case expression (pattern matching in expression context)
    // Unlike Statement::Match which is used for statement context,
    // Expression::Case can be used anywhere an expression is expected
    // (e.g., assignments, method arguments, return values)
    Case {
        expression: Box<Expression>,        // Value to match against
        cases: Vec<ExprMatchCase>,          // When branches
        else_case: Option<Box<Expression>>, // Optional else branch
        position: Position,
    },

    // If expression (if...end in expression context)
    // Evaluates to the last expression in the matching branch, or nil.
    If {
        condition: Box<Expression>,
        then_branch: Vec<Statement>,
        elsif_branches: Vec<ElsifBranch>,
        else_branch: Option<Vec<Statement>>,
        position: Position,
    },

    // Unless expression (unless...end in expression context)
    // Evaluates to the last expression in the matching branch, or nil.
    Unless {
        condition: Box<Expression>,
        then_branch: Vec<Statement>,
        else_branch: Option<Vec<Statement>>,
        position: Position,
    },

    // Scope resolution (e.g., Math::PI, Foo::Bar)
    ScopeResolution {
        namespace: Box<Expression>,
        name: String,
        position: Position,
    },
}

/// Parts of an interpolated string
#[derive(Debug, Clone, PartialEq)]
pub enum InterpolationPart {
    Text(String),
    Expression(Box<Expression>),
}

/// Pattern for match statement cases
#[derive(Debug, Clone, PartialEq)]
pub enum MatchPattern {
    // Literal patterns
    IntLiteral(i64),
    FloatLiteral(f64),
    StringLiteral(String),
    BoolLiteral(bool),
    NilLiteral,

    // Variable binding pattern
    Identifier(String),

    // Wildcard pattern (matches anything)
    Wildcard,

    // Array pattern with optional rest
    Array(Vec<MatchPattern>),

    // Array rest pattern (e.g., [first, ...rest])
    Rest(String), // Variable name to bind remaining elements

    // Object/Dictionary pattern for destructuring
    Object(Vec<(String, MatchPattern)>), // key-pattern pairs

    // Type pattern (for future use)
    Type(String),

    // Multiple patterns (OR matching) - matches if any pattern matches
    // Used for: when 1, 2, 3 then "small"
    Multiple(Vec<MatchPattern>),

    // Bind pattern: matches inner pattern and binds the whole value to a name
    // Used in case/in: `in Integer => n`
    Bind {
        pattern: Box<MatchPattern>,
        name: String,
    },

    // Range pattern: matches if value falls within start..end or start...end
    // Used in case/when: `when 1..10 then`
    Range {
        start: Box<MatchPattern>,
        end: Box<MatchPattern>,
        exclusive: bool, // true for ..., false for ..
    },
}

/// A single case in a match statement
#[derive(Debug, Clone, PartialEq)]
pub struct MatchCase {
    pub pattern: MatchPattern,
    pub guard: Option<Expression>, // Optional guard condition (if ...)
    pub body: Vec<Statement>,
    pub position: Position,
}

/// A single case in a case expression (expression context)
/// Unlike MatchCase which uses Vec<Statement> for body,
/// ExprMatchCase uses a single Expression for the body.
#[derive(Debug, Clone, PartialEq)]
pub struct ExprMatchCase {
    pub pattern: MatchPattern,
    pub guard: Option<Expression>, // Optional guard condition (if ...)
    pub body: Expression,          // Single expression (NOT Vec<Statement>)
    pub position: Position,
}

/// A rescue clause in a begin/rescue/ensure block
#[derive(Debug, Clone, PartialEq)]
pub struct RescueClause {
    pub exception_types: Vec<String>, // Exception types to catch (empty means catch all)
    pub variable_name: Option<String>, // Variable to bind the exception to (e.g., "=> e")
    pub body: Vec<Statement>,
    pub position: Position,
}

/// An elsif branch in an if statement
#[derive(Debug, Clone, PartialEq)]
pub struct ElsifBranch {
    pub condition: Expression,
    pub body: Vec<Statement>,
    pub position: Position,
}

/// Function parameter definition
#[derive(Debug, Clone, PartialEq)]
pub struct Parameter {
    pub name: String,
    pub default_value: Option<Expression>, // Default value for the parameter
    pub is_variadic: bool,                 // True if this is a *args parameter
    pub is_keyword: bool,                  // True if this is a **kwargs parameter
    pub is_named_keyword: bool,            // True if this is a name: style keyword parameter
    pub is_block: bool,                    // True if this is a &block parameter
    pub position: Position,
}

impl Parameter {
    /// Create a new simple parameter (no default, not variadic/keyword/block)
    pub fn simple(name: String, position: Position) -> Self {
        Parameter {
            name,
            default_value: None,
            is_variadic: false,
            is_keyword: false,
            is_named_keyword: false,
            is_block: false,
            position,
        }
    }

    /// Create a new parameter with a default value
    pub fn with_default(name: String, default_value: Expression, position: Position) -> Self {
        Parameter {
            name,
            default_value: Some(default_value),
            is_variadic: false,
            is_keyword: false,
            is_named_keyword: false,
            is_block: false,
            position,
        }
    }

    /// Create a new variadic parameter (*args)
    pub fn variadic(name: String, position: Position) -> Self {
        Parameter {
            name,
            default_value: None,
            is_variadic: true,
            is_keyword: false,
            is_named_keyword: false,
            is_block: false,
            position,
        }
    }

    /// Create a new keyword parameter (**kwargs)
    pub fn keyword(name: String, position: Position) -> Self {
        Parameter {
            name,
            default_value: None,
            is_variadic: false,
            is_keyword: true,
            is_named_keyword: false,
            is_block: false,
            position,
        }
    }

    /// Create a new named keyword parameter (`name:` or `name: default`)
    pub fn named_keyword(
        name: String,
        default_value: Option<Expression>,
        position: Position,
    ) -> Self {
        Parameter {
            name,
            default_value,
            is_variadic: false,
            is_keyword: false,
            is_named_keyword: true,
            is_block: false,
            position,
        }
    }

    /// Create a new block parameter (&block)
    pub fn block(name: String, position: Position) -> Self {
        Parameter {
            name,
            default_value: None,
            is_variadic: false,
            is_keyword: false,
            is_named_keyword: false,
            is_block: true,
            position,
        }
    }

    /// Check if this is a simple parameter (no default, not variadic/keyword/block)
    pub fn is_simple(&self) -> bool {
        self.default_value.is_none()
            && !self.is_variadic
            && !self.is_keyword
            && !self.is_named_keyword
            && !self.is_block
    }

    /// Check if this parameter has a default value
    pub fn has_default(&self) -> bool {
        self.default_value.is_some()
    }
}

/// Statements in Metorex - instructions that can be executed
#[derive(Debug, Clone, PartialEq)]
pub enum Statement {
    // Expression statement (an expression used as a statement)
    Expression {
        expression: Expression,
        position: Position,
    },

    // Variable assignment
    Assignment {
        target: Expression,
        value: Expression,
        position: Position,
    },

    // Function definition (standalone function)
    FunctionDef {
        name: String,
        parameters: Vec<Parameter>,
        body: Vec<Statement>,
        position: Position,
    },

    // Method definition (function within a class)
    MethodDef {
        name: String,
        parameters: Vec<Parameter>,
        body: Vec<Statement>,
        position: Position,
    },

    // Class definition
    ClassDef {
        name: String,
        superclass: Option<String>,
        body: Vec<Statement>,
        position: Position,
    },

    ModuleDef {
        name: String,
        body: Vec<Statement>,
        position: Position,
    },

    Include {
        module_name: String,
        position: Position,
    },

    Extend {
        module_name: String,
        position: Position,
    },

    // Conditional statements
    If {
        condition: Expression,
        then_branch: Vec<Statement>,
        elsif_branches: Vec<ElsifBranch>,
        else_branch: Option<Vec<Statement>>,
        position: Position,
    },

    // Unless statement (inverted if)
    Unless {
        condition: Expression,
        then_branch: Vec<Statement>,
        else_branch: Option<Vec<Statement>>,
        position: Position,
    },

    // While loop
    While {
        condition: Expression,
        body: Vec<Statement>,
        position: Position,
    },

    // For loop (iteration over collections)
    For {
        variable: String,
        iterable: Expression,
        body: Vec<Statement>,
        position: Position,
    },

    // Match statement (case/when pattern matching)
    Match {
        expression: Expression,
        cases: Vec<MatchCase>,
        position: Position,
    },

    // CaseIn statement (Ruby 2.7+ case/in pattern matching)
    // Raises NoMatchingPatternError if no arm matches and no else is present.
    CaseIn {
        expression: Expression,
        cases: Vec<MatchCase>,
        position: Position,
    },

    // Return statement
    Return {
        value: Option<Expression>,
        position: Position,
    },

    // Break statement (exit from loop)
    Break {
        position: Position,
    },

    // Continue statement (skip to next iteration)
    Continue {
        position: Position,
    },

    // Block statement
    Block {
        statements: Vec<Statement>,
        position: Position,
    },

    // Exception handling: begin/rescue/else/ensure/end
    Begin {
        body: Vec<Statement>,
        rescue_clauses: Vec<RescueClause>,
        else_clause: Option<Vec<Statement>>, // Runs if no exception occurred
        ensure_block: Option<Vec<Statement>>, // Always runs (like finally)
        position: Position,
    },

    // Raise statement (throw exception)
    Raise {
        exception: Option<Expression>, // None means re-raise current exception
        position: Position,
    },

    // attr_reader - creates getter methods for instance variables
    AttrReader {
        attributes: Vec<String>, // List of attribute names (without @)
        position: Position,
    },

    // attr_writer - creates setter methods for instance variables
    AttrWriter {
        attributes: Vec<String>, // List of attribute names (without @)
        position: Position,
    },

    // attr_accessor - creates both getter and setter methods for instance variables
    AttrAccessor {
        attributes: Vec<String>, // List of attribute names (without @)
        position: Position,
    },
}

// Implement Display for BinaryOp
impl fmt::Display for BinaryOp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BinaryOp::Add => write!(f, "+"),
            BinaryOp::Subtract => write!(f, "-"),
            BinaryOp::Multiply => write!(f, "*"),
            BinaryOp::Divide => write!(f, "/"),
            BinaryOp::Modulo => write!(f, "%"),
            BinaryOp::Equal => write!(f, "=="),
            BinaryOp::NotEqual => write!(f, "!="),
            BinaryOp::Less => write!(f, "<"),
            BinaryOp::Greater => write!(f, ">"),
            BinaryOp::LessEqual => write!(f, "<="),
            BinaryOp::GreaterEqual => write!(f, ">="),
            BinaryOp::Assign => write!(f, "="),
            BinaryOp::AddAssign => write!(f, "+="),
            BinaryOp::SubtractAssign => write!(f, "-="),
            BinaryOp::MultiplyAssign => write!(f, "*="),
            BinaryOp::DivideAssign => write!(f, "/="),
            BinaryOp::And => write!(f, "&&"),
            BinaryOp::Or => write!(f, "||"),
        }
    }
}

// Implement Display for UnaryOp
impl fmt::Display for UnaryOp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UnaryOp::Plus => write!(f, "+"),
            UnaryOp::Minus => write!(f, "-"),
            UnaryOp::Not => write!(f, "!"),
        }
    }
}

// Implement helper methods for Expression
impl Expression {
    /// Get the position of this expression
    pub fn position(&self) -> Position {
        match self {
            Expression::IntLiteral { position, .. }
            | Expression::FloatLiteral { position, .. }
            | Expression::StringLiteral { position, .. }
            | Expression::Symbol { position, .. }
            | Expression::InterpolatedString { position, .. }
            | Expression::BoolLiteral { position, .. }
            | Expression::NilLiteral { position, .. }
            | Expression::Identifier { position, .. }
            | Expression::InstanceVariable { position, .. }
            | Expression::ClassVariable { position, .. }
            | Expression::GlobalVariable { position, .. }
            | Expression::BinaryOp { position, .. }
            | Expression::UnaryOp { position, .. }
            | Expression::Call { position, .. }
            | Expression::MethodCall { position, .. }
            | Expression::Array { position, .. }
            | Expression::Index { position, .. }
            | Expression::Dictionary { position, .. }
            | Expression::Lambda { position, .. }
            | Expression::Grouped { position, .. }
            | Expression::SelfExpr { position, .. }
            | Expression::Super { position, .. }
            | Expression::Range { position, .. }
            | Expression::Case { position, .. }
            | Expression::ScopeResolution { position, .. }
            | Expression::If { position, .. }
            | Expression::Unless { position, .. } => *position,
        }
    }

    /// Check if this expression is a literal
    pub fn is_literal(&self) -> bool {
        matches!(
            self,
            Expression::IntLiteral { .. }
                | Expression::FloatLiteral { .. }
                | Expression::StringLiteral { .. }
                | Expression::InterpolatedString { .. }
                | Expression::BoolLiteral { .. }
                | Expression::NilLiteral { .. }
        )
    }

    /// Check if this expression is an identifier or variable
    pub fn is_identifier(&self) -> bool {
        matches!(
            self,
            Expression::Identifier { .. }
                | Expression::InstanceVariable { .. }
                | Expression::ClassVariable { .. }
        )
    }
}

// Implement helper methods for Statement
impl Statement {
    /// Get the position of this statement
    pub fn position(&self) -> Position {
        match self {
            Statement::Expression { position, .. }
            | Statement::Assignment { position, .. }
            | Statement::FunctionDef { position, .. }
            | Statement::MethodDef { position, .. }
            | Statement::ClassDef { position, .. }
            | Statement::If { position, .. }
            | Statement::Unless { position, .. }
            | Statement::While { position, .. }
            | Statement::For { position, .. }
            | Statement::Match { position, .. }
            | Statement::CaseIn { position, .. }
            | Statement::Return { position, .. }
            | Statement::Break { position, .. }
            | Statement::Continue { position, .. }
            | Statement::Block { position, .. }
            | Statement::Begin { position, .. }
            | Statement::Raise { position, .. }
            | Statement::AttrReader { position, .. }
            | Statement::AttrWriter { position, .. }
            | Statement::AttrAccessor { position, .. }
            | Statement::ModuleDef { position, .. }
            | Statement::Include { position, .. }
            | Statement::Extend { position, .. } => *position,
        }
    }

    /// Check if this statement is a definition (function, method, class, or module)
    pub fn is_definition(&self) -> bool {
        matches!(
            self,
            Statement::FunctionDef { .. }
                | Statement::MethodDef { .. }
                | Statement::ClassDef { .. }
                | Statement::ModuleDef { .. }
        )
    }

    /// Check if this statement is a control flow statement
    pub fn is_control_flow(&self) -> bool {
        matches!(
            self,
            Statement::If { .. }
                | Statement::While { .. }
                | Statement::For { .. }
                | Statement::Match { .. }
                | Statement::CaseIn { .. }
                | Statement::Return { .. }
                | Statement::Break { .. }
                | Statement::Continue { .. }
                | Statement::Begin { .. }
                | Statement::Raise { .. }
        )
    }
}

// Built-in base classes for Metorex runtime
// Defines the hierarchy and methods for core classes like Object, String, Integer, etc.

use crate::class::Class;
use crate::object::{Method, Object};
use std::collections::HashMap;
use std::rc::Rc;

/// Registry for built-in classes
pub struct BuiltinClasses {
    /// Base Object class (all classes inherit from this)
    pub object_class: Rc<Class>,
    /// String class
    pub string_class: Rc<Class>,
    /// Integer class
    pub integer_class: Rc<Class>,
    /// Float class
    pub float_class: Rc<Class>,
    /// Array class
    pub array_class: Rc<Class>,
    /// Hash/Dictionary class
    pub hash_class: Rc<Class>,
    /// Set class
    pub set_class: Rc<Class>,
    /// Range class
    pub range_class: Rc<Class>,
    /// Base Exception class
    pub exception_class: Rc<Class>,
    /// StandardError class (inherits from Exception)
    pub standard_error_class: Rc<Class>,
    /// RuntimeError class (inherits from StandardError)
    pub runtime_error_class: Rc<Class>,
    /// TypeError class (inherits from StandardError)
    pub type_error_class: Rc<Class>,
    /// ValueError class (inherits from StandardError)
    pub value_error_class: Rc<Class>,
    /// File class for file I/O operations
    pub file_class: Rc<Class>,
}

impl BuiltinClasses {
    /// Create and initialize all built-in classes
    pub fn new() -> Self {
        // Create the base Object class
        let object_class = Rc::new(Class::new("Object", None));

        // Create primitive type classes
        let string_class = Rc::new(Class::new("String", Some(Rc::clone(&object_class))));
        let integer_class = Rc::new(Class::new("Integer", Some(Rc::clone(&object_class))));
        let float_class = Rc::new(Class::new("Float", Some(Rc::clone(&object_class))));

        // Create collection classes
        let array_class = Rc::new(Class::new("Array", Some(Rc::clone(&object_class))));
        let hash_class = Rc::new(Class::new("Hash", Some(Rc::clone(&object_class))));
        let set_class = Rc::new(Class::new("Set", Some(Rc::clone(&object_class))));
        let range_class = Rc::new(Class::new("Range", Some(Rc::clone(&object_class))));

        // Create utility classes
        let file_class = Rc::new(Class::new("File", Some(Rc::clone(&object_class))));

        // Create exception hierarchy
        let exception_class = Rc::new(Class::new("Exception", Some(Rc::clone(&object_class))));
        let standard_error_class = Rc::new(Class::new(
            "StandardError",
            Some(Rc::clone(&exception_class)),
        ));
        let runtime_error_class = Rc::new(Class::new(
            "RuntimeError",
            Some(Rc::clone(&standard_error_class)),
        ));
        let type_error_class = Rc::new(Class::new(
            "TypeError",
            Some(Rc::clone(&standard_error_class)),
        ));
        let value_error_class = Rc::new(Class::new(
            "ValueError",
            Some(Rc::clone(&standard_error_class)),
        ));

        Self {
            object_class,
            string_class,
            integer_class,
            float_class,
            array_class,
            hash_class,
            set_class,
            range_class,
            exception_class,
            standard_error_class,
            runtime_error_class,
            type_error_class,
            value_error_class,
            file_class,
        }
    }

    /// Get the class for a given object
    pub fn class_of(&self, obj: &Object) -> Rc<Class> {
        match obj {
            Object::Nil => Rc::clone(&self.object_class),
            Object::Bool(_) => Rc::clone(&self.object_class),
            Object::Int(_) => Rc::clone(&self.integer_class),
            Object::Float(_) => Rc::clone(&self.float_class),
            Object::String(_) => Rc::clone(&self.string_class),
            Object::Symbol(_) => Rc::clone(&self.string_class), // Symbols are like strings
            Object::Array(_) => Rc::clone(&self.array_class),
            Object::Dict(_) => Rc::clone(&self.hash_class),
            Object::Set(_) => Rc::clone(&self.set_class),
            Object::Instance(inst) => Rc::clone(&inst.borrow().class),
            Object::Class(_) | Object::Module(_) => Rc::clone(&self.object_class),
            Object::Method(_) => Rc::clone(&self.object_class),
            Object::Block(_) => Rc::clone(&self.object_class),
            Object::Binding(_) => Rc::clone(&self.object_class),
            Object::Exception(_) => Rc::clone(&self.exception_class),
            Object::Result(_) => Rc::clone(&self.object_class),
            Object::NativeFunction(_) => Rc::clone(&self.object_class),
            Object::Range { .. } => Rc::clone(&self.range_class),
        }
    }

    /// Check if an object is an instance of a class (or its subclasses)
    pub fn is_instance_of(&self, obj: &Object, class: &Class) -> bool {
        let obj_class = self.class_of(obj);
        self.is_subclass_of(&obj_class, class)
    }

    /// Check if class_a is a subclass of class_b
    pub fn is_subclass_of(&self, class_a: &Class, class_b: &Class) -> bool {
        Self::is_subclass_of_static(class_a, class_b)
    }

    /// Static helper for is_subclass_of
    fn is_subclass_of_static(class_a: &Class, class_b: &Class) -> bool {
        if class_a.name() == class_b.name() {
            return true;
        }

        if let Some(superclass) = class_a.superclass() {
            return Self::is_subclass_of_static(&superclass, class_b);
        }

        false
    }

    /// Get all built-in classes as a map
    pub fn all_classes(&self) -> HashMap<String, Rc<Class>> {
        let mut classes = HashMap::new();
        classes.insert("Object".to_string(), Rc::clone(&self.object_class));
        classes.insert("String".to_string(), Rc::clone(&self.string_class));
        classes.insert("Integer".to_string(), Rc::clone(&self.integer_class));
        classes.insert("Float".to_string(), Rc::clone(&self.float_class));
        classes.insert("Array".to_string(), Rc::clone(&self.array_class));
        classes.insert("Hash".to_string(), Rc::clone(&self.hash_class));
        classes.insert("Set".to_string(), Rc::clone(&self.set_class));
        classes.insert("Exception".to_string(), Rc::clone(&self.exception_class));
        classes.insert(
            "StandardError".to_string(),
            Rc::clone(&self.standard_error_class),
        );
        classes.insert(
            "RuntimeError".to_string(),
            Rc::clone(&self.runtime_error_class),
        );
        classes.insert("TypeError".to_string(), Rc::clone(&self.type_error_class));
        classes.insert("ValueError".to_string(), Rc::clone(&self.value_error_class));
        classes.insert("File".to_string(), Rc::clone(&self.file_class));
        classes
    }
}

impl Default for BuiltinClasses {
    fn default() -> Self {
        Self::new()
    }
}

