//! Runtime class representation for Metorex
//! Handles method tables, inheritance, and instance variable declarations.

use crate::object::{Method, Object};
use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::rc::Rc;

/// Runtime class definition with method table and inheritance.
#[derive(Debug)]
pub struct Class {
    name: String,
    superclass: Option<Rc<Class>>,
    methods: RefCell<HashMap<String, Rc<Method>>>,
    instance_variables: RefCell<HashSet<String>>,
    class_variables: RefCell<HashMap<String, crate::object::Object>>,
}

impl Class {
    /// Create a new class with an optional superclass.
    pub fn new(name: impl Into<String>, superclass: Option<Rc<Class>>) -> Self {
        Self {
            name: name.into(),
            superclass,
            methods: RefCell::new(HashMap::new()),
            instance_variables: RefCell::new(HashSet::new()),
            class_variables: RefCell::new(HashMap::new()),
        }
    }

    /// Return the class name.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Return the superclass if present.
    pub fn superclass(&self) -> Option<Rc<Class>> {
        self.superclass.as_ref().map(Rc::clone)
    }

    /// Declare a new instance variable on this class.
    pub fn declare_instance_var(&self, name: impl Into<String>) {
        self.instance_variables.borrow_mut().insert(name.into());
    }

    /// Check if this class (or a superclass) declares the given instance variable.
    pub fn has_instance_var(&self, name: &str) -> bool {
        if self.instance_variables.borrow().contains(name) {
            return true;
        }

        self.superclass
            .as_ref()
            .is_some_and(|superclass| superclass.has_instance_var(name))
    }

    /// Return the list of instance variable names defined directly on this class.
    pub fn instance_variables(&self) -> Vec<String> {
        let mut vars = self
            .instance_variables
            .borrow()
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        vars.sort();
        vars
    }

    /// Define or replace a method on this class.
    pub fn define_method(&self, name: impl Into<String>, method: Rc<Method>) {
        self.methods.borrow_mut().insert(name.into(), method);
    }

    /// Determine whether this class defines a method (without checking superclasses).
    pub fn has_own_method(&self, name: &str) -> bool {
        self.methods.borrow().contains_key(name)
    }

    /// Look up a method by walking the inheritance chain.
    pub fn find_method(&self, name: &str) -> Option<Rc<Method>> {
        if let Some(method) = self.methods.borrow().get(name) {
            return Some(Rc::clone(method));
        }

        self.superclass
            .as_ref()
            .and_then(|superclass| superclass.find_method(name))
    }

    /// Return a list of method names defined directly on this class.
    pub fn method_names(&self) -> Vec<String> {
        let mut names = self.methods.borrow().keys().cloned().collect::<Vec<_>>();
        names.sort();
        names
    }

    /// Set a class variable on this class.
    pub fn set_class_var(&self, name: impl Into<String>, value: Object) {
        self.class_variables.borrow_mut().insert(name.into(), value);
    }

    /// Retrieve a class variable from this class.
    pub fn get_class_var(&self, name: &str) -> Option<Object> {
        self.class_variables.borrow().get(name).cloned()
    }
}

impl Clone for Class {
    fn clone(&self) -> Self {
        Self {
            name: self.name.clone(),
            superclass: self.superclass.clone(),
            methods: RefCell::new(self.methods.borrow().clone()),
            instance_variables: RefCell::new(self.instance_variables.borrow().clone()),
            class_variables: RefCell::new(self.class_variables.borrow().clone()),
        }
    }
}

impl PartialEq for Class {
    fn eq(&self, other: &Self) -> bool {
        if self.name != other.name {
            return false;
        }

        let self_super = self.superclass.as_ref().map(Rc::as_ptr);
        let other_super = other.superclass.as_ref().map(Rc::as_ptr);
        if self_super != other_super {
            return false;
        }

        {
            let vars = self.instance_variables.borrow();
            let other_vars = other.instance_variables.borrow();
            if *vars != *other_vars {
                return false;
            }
        }

        let self_methods = self.methods.borrow();
        let other_methods = other.methods.borrow();
        if self_methods.len() != other_methods.len() {
            return false;
        }
        if self.class_variables.borrow().len() != other.class_variables.borrow().len() {
            return false;
        }

        self_methods.iter().all(|(name, method)| {
            other_methods.get(name).is_some_and(|other_method| {
                Rc::ptr_eq(method, other_method) || method == other_method
            })
        }) && {
            let class_vars = self.class_variables.borrow();
            let other_class_vars = other.class_variables.borrow();
            class_vars
                .iter()
                .all(|(name, value)| other_class_vars.get(name) == Some(value))
        }
    }
}

impl Eq for Class {}

// Environment stack for managing lexical scopes in Metorex
// This module implements a stack-based scope management system

use crate::object::Object;
use crate::scope::Scope;
use std::cell::RefCell;
use std::rc::Rc;

/// Represents the environment with a stack of scopes
/// The environment manages the scope chain and tracks the current depth
#[derive(Debug)]
pub struct Environment {
    /// Stack of scopes, with the top being the current scope
    scopes: Vec<Rc<RefCell<Scope>>>,

    /// Current depth in the scope stack (0 = global scope)
    depth: usize,
}

impl Environment {
    /// Creates a new environment with a global scope
    pub fn new() -> Self {
        let global_scope = Rc::new(RefCell::new(Scope::new()));
        Environment {
            scopes: vec![global_scope],
            depth: 0,
        }
    }

    /// Pushes a new scope onto the stack
    /// The new scope's parent will be the current top scope
    pub fn push_scope(&mut self) {
        let parent = self.scopes.last().unwrap().clone();
        let new_scope = Rc::new(RefCell::new(Scope::with_parent(parent)));
        self.scopes.push(new_scope);
        self.depth += 1;
    }

    /// Pops the current scope from the stack
    /// Returns the popped scope, or None if we're at the global scope
    /// Note: The global scope can never be popped
    pub fn pop_scope(&mut self) -> Option<Rc<RefCell<Scope>>> {
        if self.scopes.len() <= 1 {
            // Cannot pop the global scope
            return None;
        }

        self.depth -= 1;
        self.scopes.pop()
    }

    /// Returns a reference to the current (top) scope
    pub fn current_scope(&self) -> Rc<RefCell<Scope>> {
        self.scopes.last().unwrap().clone()
    }

    /// Returns the current scope depth
    /// 0 = global scope, 1 = first nested scope, etc.
    pub fn current_depth(&self) -> usize {
        self.depth
    }

    /// Returns a reference to the global scope
    pub fn global_scope(&self) -> Rc<RefCell<Scope>> {
        self.scopes[0].clone()
    }

    /// Defines a variable in the current scope
    pub fn define(&mut self, name: String, value: Object) {
        self.current_scope().borrow_mut().define(name, value);
    }

    /// Gets a variable value by traversing the scope chain from the current scope
    pub fn get(&self, name: &str) -> Option<Object> {
        self.current_scope().borrow().get(name)
    }

    /// Sets a variable value by traversing the scope chain from the current scope
    /// Returns true if the variable was found and updated, false otherwise
    pub fn set(&mut self, name: &str, value: Object) -> bool {
        self.current_scope().borrow_mut().set(name, value)
    }

    /// Gets a variable at a specific depth relative to the current scope
    pub fn get_at(&self, depth: usize, name: &str) -> Option<Object> {
        self.current_scope().borrow().get_at(depth, name)
    }

    /// Sets a variable at a specific depth relative to the current scope
    pub fn set_at(&mut self, depth: usize, name: &str, value: Object) -> bool {
        self.current_scope().borrow_mut().set_at(depth, name, value)
    }

    /// Collects all variables from the current scope chain
    /// This is used for lambda closure capture
    pub fn current_scope_vars(&self) -> std::collections::HashMap<String, Object> {
        self.current_scope().borrow().collect_all_vars()
    }

    /// Collects all variable references from the current scope chain
    /// This is used for lambda closure capture with mutable closures
    pub fn current_scope_var_refs(
        &self,
    ) -> std::collections::HashMap<String, std::rc::Rc<std::cell::RefCell<Object>>> {
        self.current_scope().borrow().collect_all_var_refs()
    }

    /// Defines a variable in the current scope with a shared reference
    /// Used when a closure defines a captured variable
    pub fn define_shared(&mut self, name: String, value: std::rc::Rc<std::cell::RefCell<Object>>) {
        self.current_scope().borrow_mut().define_shared(name, value);
    }

    /// Gets a shared reference to a variable
    pub fn get_ref(&self, name: &str) -> Option<std::rc::Rc<std::cell::RefCell<Object>>> {
        self.current_scope().borrow().get_ref(name)
    }
}

impl Default for Environment {
    fn default() -> Self {
        Self::new()
    }
}

// Metorex Error Handling Foundation
//
// This module defines the comprehensive error type system for the Metorex language.
// It provides structured error reporting with source location information and
// formatting utilities for beautiful error messages.

use std::fmt;
use thiserror::Error;

/// Source location information for error reporting
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceLocation {
    /// Line number (1-indexed)
    pub line: usize,
    /// Column number (1-indexed)
    pub column: usize,
    /// Byte offset in the source file
    pub offset: usize,
    /// Optional filename
    pub filename: Option<String>,
}

impl SourceLocation {
    /// Create a new source location
    pub fn new(line: usize, column: usize, offset: usize) -> Self {
        Self {
            line,
            column,
            offset,
            filename: None,
        }
    }

    /// Create a source location with a filename
    pub fn with_filename(line: usize, column: usize, offset: usize, filename: String) -> Self {
        Self {
            line,
            column,
            offset,
            filename: Some(filename),
        }
    }
}

impl fmt::Display for SourceLocation {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(filename) = &self.filename {
            write!(f, "{}:{}:{}", filename, self.line, self.column)
        } else {
            write!(f, "{}:{}", self.line, self.column)
        }
    }
}

/// Stack frame information for runtime error traces
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StackFrame {
    /// Function or method name
    pub function_name: String,
    /// Source location where the call occurred
    pub location: SourceLocation,
}

impl StackFrame {
    /// Create a new stack frame
    pub fn new(function_name: String, location: SourceLocation) -> Self {
        Self {
            function_name,
            location,
        }
    }
}

impl fmt::Display for StackFrame {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "  at {} ({})", self.function_name, self.location)
    }
}

/// Main error type for Metorex
#[derive(Error, Debug, Clone)]
pub enum MetorexError {
    /// Syntax errors encountered during parsing
    #[error("Syntax error at {location}: {message}")]
    SyntaxError {
        message: String,
        location: SourceLocation,
    },

    /// Runtime errors encountered during execution
    #[error("Runtime error at {location}: {message}")]
    RuntimeError {
        message: String,
        location: SourceLocation,
        stack_trace: Vec<StackFrame>,
    },

    /// Type mismatch or type-related errors
    #[error("Type error at {location}: {message}")]
    TypeError {
        message: String,
        location: SourceLocation,
        expected: Option<String>,
        found: Option<String>,
    },

    /// IO errors (file operations, etc.)
    #[error("IO error: {0}")]
    IoError(String),

    /// Generic internal errors
    #[error("Internal error: {0}")]
    InternalError(String),

    /// Uncaught exception that needs to be propagated as ControlFlow
    #[error("Runtime error at {location}: Uncaught exception: {message}")]
    UncaughtException {
        exception: crate::object::Object,
        location: SourceLocation,
        message: String,
    },
}

// Custom From implementation for std::io::Error
impl From<std::io::Error> for MetorexError {
    fn from(err: std::io::Error) -> Self {
        MetorexError::IoError(err.to_string())
    }
}

impl MetorexError {
    /// Create a new syntax error
    pub fn syntax_error(message: impl Into<String>, location: SourceLocation) -> Self {
        Self::SyntaxError {
            message: message.into(),
            location,
        }
    }

    /// Create a new runtime error with an empty stack trace
    pub fn runtime_error(message: impl Into<String>, location: SourceLocation) -> Self {
        Self::RuntimeError {
            message: message.into(),
            location,
            stack_trace: Vec::new(),
        }
    }

    /// Create a new runtime error with a stack trace
    pub fn runtime_error_with_trace(
        message: impl Into<String>,
        location: SourceLocation,
        stack_trace: Vec<StackFrame>,
    ) -> Self {
        Self::RuntimeError {
            message: message.into(),
            location,
            stack_trace,
        }
    }

    /// Create a new type error
    pub fn type_error(message: impl Into<String>, location: SourceLocation) -> Self {
        Self::TypeError {
            message: message.into(),
            location,
            expected: None,
            found: None,
        }
    }

    /// Create a new type error with expected and found types
    pub fn type_error_with_types(
        message: impl Into<String>,
        location: SourceLocation,
        expected: impl Into<String>,
        found: impl Into<String>,
    ) -> Self {
        Self::TypeError {
            message: message.into(),
            location,
            expected: Some(expected.into()),
            found: Some(found.into()),
        }
    }

    /// Create a new internal error
    pub fn internal_error(message: impl Into<String>) -> Self {
        Self::InternalError(message.into())
    }

    /// Add a stack frame to a runtime error
    pub fn with_stack_frame(self, frame: StackFrame) -> Self {
        match self {
            Self::RuntimeError {
                message,
                location,
                mut stack_trace,
            } => {
                stack_trace.push(frame);
                Self::RuntimeError {
                    message,
                    location,
                    stack_trace,
                }
            }
            other => other,
        }
    }

    /// Get the source location associated with this error, if any
    pub fn location(&self) -> Option<&SourceLocation> {
        match self {
            Self::SyntaxError { location, .. }
            | Self::RuntimeError { location, .. }
            | Self::TypeError { location, .. } => Some(location),
            _ => None,
        }
    }
}

/// Result type alias for Metorex operations
pub type Result<T> = std::result::Result<T, MetorexError>;

/// Error reporting utilities
pub mod reporting {
    use super::*;

    /// Format an error with source code context
    pub fn format_error_with_source(error: &MetorexError, source: &str) -> String {
        let mut output = String::new();

        // Add the main error message
        output.push_str(&format!("Error: {}\n", error));

        // Add source code snippet if location is available
        if let Some(location) = error.location()
            && let Some(snippet) = extract_source_snippet(source, location)
        {
            output.push('\n');
            output.push_str(&snippet);
        }

        // Add stack trace for runtime errors
        if let MetorexError::RuntimeError { stack_trace, .. } = error
            && !stack_trace.is_empty()
        {
            output.push_str("\n\nStack trace:\n");
            for frame in stack_trace {
                output.push_str(&format!("{}\n", frame));
            }
        }

        output
    }

    /// Extract a snippet of source code around the error location
    fn extract_source_snippet(source: &str, location: &SourceLocation) -> Option<String> {
        let lines: Vec<&str> = source.lines().collect();

        if location.line == 0 || location.line > lines.len() {
            return None;
        }

        let line_idx = location.line - 1;
        let line = lines[line_idx];

        let mut snippet = String::new();

        // Line number width for alignment
        let line_num_width = location.line.to_string().len();

        // Show the line with the error
        snippet.push_str(&format!(
            "{:width$} | {}\n",
            location.line,
            line,
            width = line_num_width
        ));

        // Show the error indicator (^)
        snippet.push_str(&format!(
            "{:width$} | {}^\n",
            "",
            " ".repeat(location.column.saturating_sub(1)),
            width = line_num_width
        ));

        Some(snippet)
    }

    /// Format an error for display in REPL or CLI
    pub fn format_error_compact(error: &MetorexError) -> String {
        format!("{}", error)
    }
}

// File Loading Infrastructure for require_relative
//
// This module provides utilities for loading, parsing, and resolving file paths
// in the Metorex language. It supports Ruby's file loading conventions including
// automatic file extension detection (.rb, .rb, or no extension).

use crate::ast::Statement;
use crate::error::{MetorexError, SourceLocation};
use crate::lexer::Lexer;
use crate::parser::Parser;
use std::fs;
use std::path::{Path, PathBuf};

/// Finds the actual file path with extension auto-detection.
///
/// This function supports Ruby's file loading conventions:
/// - If the path has an extension (.rb, .rb, etc.), it tries that path first
/// - If no extension or file not found, it tries adding .rb
/// - If still not found, it tries adding .rb
/// - Returns the path of the first file that exists
///
/// # Arguments
/// * `path` - The file path to find (may or may not include extension)
///
/// # Returns
/// * `Ok(PathBuf)` - The actual file path that exists
/// * `Err(MetorexError)` - If the file doesn't exist with any extension
pub fn find_file_path(path: &Path) -> Result<PathBuf, MetorexError> {
    // Try the path as given first
    if path.exists() {
        return Ok(path.to_path_buf());
    }

    // If the path has an extension, don't try alternatives
    if path.extension().is_some() {
        return Err(MetorexError::runtime_error(
            format!("File not found: '{}'", path.display()),
            SourceLocation::new(0, 0, 0),
        ));
    }

    // Try with .rb extension
    let rb_path = path.with_extension("rb");
    if rb_path.exists() {
        return Ok(rb_path);
    }

    // Try with .rb extension
    let mx_path = path.with_extension("mx");
    if mx_path.exists() {
        return Ok(mx_path);
    }

    // File not found with any extension
    Err(MetorexError::runtime_error(
        format!(
            "File not found: '{}' (tried {}, {}.rb, {}.rb)",
            path.display(),
            path.display(),
            path.display(),
            path.display()
        ),
        SourceLocation::new(0, 0, 0),
    ))
}

/// Loads the source code from a file, with automatic file extension detection.
///
/// This function supports Ruby's file loading conventions:
/// - If the path has an extension (.rb, .rb, etc.), it tries that path first
/// - If no extension or file not found, it tries adding .rb
/// - If still not found, it tries adding .rb
/// - Returns an error if the file doesn't exist with any extension
///
/// # Arguments
/// * `path` - The file path to load (may or may not include extension)
///
/// # Returns
/// * `Ok(String)` - The file contents as a string
/// * `Err(MetorexError)` - If the file cannot be found or read
pub fn load_file_source(path: &Path) -> Result<String, MetorexError> {
    let actual_path = find_file_path(path)?;
    fs::read_to_string(&actual_path).map_err(|e| {
        MetorexError::runtime_error(
            format!("Failed to read file '{}': {}", actual_path.display(), e),
            SourceLocation::new(0, 0, 0),
        )
    })
}

/// Resolves a relative path based on the location of a base file.
///
/// This function implements Ruby's `require_relative` path resolution logic:
/// - Gets the parent directory of the base file
/// - Joins the relative path to that directory
/// - Canonicalizes the result to resolve `..`, `.`, and symlinks
///
/// # Arguments
/// * `base_file` - The file from which the relative path is resolved
/// * `relative_path` - The relative path to resolve
///
/// # Returns
/// * `Ok(PathBuf)` - The absolute, canonicalized path
/// * `Err(MetorexError)` - If path resolution fails
///
/// # Examples
/// ```
/// // If base_file is "/home/user/project/lib/helper.rb"
/// // and relative_path is "../config/settings"
/// // Result will be "/home/user/project/config/settings"
/// ```
pub fn resolve_relative_path(
    base_file: &Path,
    relative_path: &str,
) -> Result<PathBuf, MetorexError> {
    // Get the parent directory of the base file
    let base_dir = base_file.parent().ok_or_else(|| {
        MetorexError::runtime_error(
            format!(
                "Cannot determine parent directory of '{}'",
                base_file.display()
            ),
            SourceLocation::new(0, 0, 0),
        )
    })?;

    // Join the relative path to the base directory
    // Note: We don't canonicalize here because the file may not exist yet (extension auto-detection)
    // Canonicalization will happen in execute_file after load_file_source finds the actual file
    let target_path = base_dir.join(relative_path);

    Ok(target_path)
}

/// Parses source code into an Abstract Syntax Tree (AST).
///
/// This function takes source code as a string and converts it into a vector of
/// Statement nodes that can be executed by the VM. It handles the lexing and parsing
/// process, converting any parse errors into MetorexError.
///
/// # Arguments
/// * `source` - The source code to parse
/// * `filename` - The name of the file being parsed (used in error messages)
///
/// # Returns
/// * `Ok(Vec<Statement>)` - The parsed AST
/// * `Err(MetorexError)` - If there are syntax errors in the source code
pub fn parse_file(source: &str, filename: &str) -> Result<Vec<Statement>, MetorexError> {
    // Create lexer from source
    let lexer = Lexer::new(source);

    // Tokenize source code
    let tokens = lexer.tokenize();

    // Create parser from tokens
    let mut parser = Parser::new(tokens);

    // Parse and return AST, converting parse errors to MetorexError
    parser.parse().map_err(|errors| {
        // If there are multiple parse errors, we'll return the first one
        // In the future, we might want to collect all errors
        if let Some(first_error) = errors.first() {
            // Create a new error with the filename context
            MetorexError::runtime_error(
                format!("Parse error in '{}': {}", filename, first_error),
                SourceLocation::new(0, 0, 0),
            )
        } else {
            // Shouldn't happen, but handle gracefully
            MetorexError::runtime_error(
                format!("Unknown parse error in '{}'", filename),
                SourceLocation::new(0, 0, 0),
            )
        }
    })
}

// Lexer module for tokenizing Metorex source code

pub mod token;

pub use token::{InterpolationPart, Position, Token, TokenKind};

use std::iter::Peekable;
use std::str::Chars;

/// The lexer converts source code into a stream of tokens
pub struct Lexer<'a> {
    /// Peekable iterator over the characters
    chars: Peekable<Chars<'a>>,
    /// Current position in the source
    line: usize,
    column: usize,
    offset: usize,
}

impl<'a> Lexer<'a> {
    /// Create a new lexer for the given source code
    pub fn new(source: &'a str) -> Self {
        Self {
            chars: source.chars().peekable(),
            line: 1,
            column: 1,
            offset: 0,
        }
    }

    /// Get the current position
    fn current_position(&self) -> Position {
        Position::new(self.line, self.column, self.offset)
    }

    /// Advance to the next character and return it
    fn advance(&mut self) -> Option<char> {
        if let Some(ch) = self.chars.next() {
            self.offset += ch.len_utf8();
            if ch == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            Some(ch)
        } else {
            None
        }
    }

    /// Peek at the next character without consuming it
    fn peek(&mut self) -> Option<char> {
        self.chars.peek().copied()
    }

    /// Skip whitespace characters (spaces and tabs, but not newlines)
    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.peek() {
            if ch == ' ' || ch == '\t' || ch == '\r' {
                self.advance();
            } else {
                break;
            }
        }
    }

    /// Read a comment from # to end of line
    fn read_comment(&mut self) -> String {
        let mut comment = String::new();
        // Skip the # character
        self.advance();

        while let Some(ch) = self.peek() {
            if ch == '\n' {
                break;
            }
            comment.push(ch);
            self.advance();
        }

        comment.trim().to_string()
    }

    /// Read a number (integer or float)
    fn read_number(&mut self) -> TokenKind {
        let mut number = String::new();
        let mut is_float = false;

        // Read digits before decimal point
        while let Some(ch) = self.peek() {
            if ch.is_ascii_digit() {
                number.push(ch);
                self.advance();
            } else if ch == '.' {
                // Need to peek ahead to see if this is a float or a range/method call
                // Save current state to peek ahead
                let saved_chars = self.chars.clone();
                let saved_line = self.line;
                let saved_column = self.column;
                let saved_offset = self.offset;

                self.advance(); // consume the dot
                let next_ch = self.peek();

                // Restore state
                self.chars = saved_chars;
                self.line = saved_line;
                self.column = saved_column;
                self.offset = saved_offset;

                // Check if next character is a digit (float) or not (method/range)
                if let Some(next_ch) = next_ch {
                    if next_ch.is_ascii_digit() {
                        // It's a float literal
                        self.advance(); // consume the dot for real
                        is_float = true;
                        number.push('.');
                        // Read digits after decimal point
                        while let Some(digit_ch) = self.peek() {
                            if digit_ch.is_ascii_digit() {
                                number.push(digit_ch);
                                self.advance();
                            } else {
                                break;
                            }
                        }
                        break;
                    } else {
                        // Not a float - dot will be lexed separately
                        break;
                    }
                }
                break;
            } else {
                break;
            }
        }

        if is_float {
            TokenKind::Float(number.parse().unwrap_or(0.0))
        } else {
            TokenKind::Int(number.parse().unwrap_or(0))
        }
    }

    /// Check if a character can start an identifier (letter or underscore)
    fn is_identifier_start(ch: char) -> bool {
        ch.is_ascii_alphabetic() || ch == '_'
    }

    /// Check if a character can continue an identifier (letter, digit, or underscore)
    fn is_identifier_continue(ch: char) -> bool {
        ch.is_ascii_alphanumeric() || ch == '_'
    }

    /// Read an identifier or keyword
    fn read_identifier(&mut self) -> TokenKind {
        let mut ident = String::new();

        // Read identifier characters
        while let Some(ch) = self.peek() {
            if Self::is_identifier_continue(ch) {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        // Check for trailing ? or ! (Ruby-style method names)
        if let Some(ch) = self.peek()
            && (ch == '?' || ch == '!')
        {
            ident.push(ch);
            self.advance();
        }

        // Check if it's a keyword
        self.keyword_or_identifier(ident)
    }

    /// Read an instance or class variable (@var or @@var)
    fn read_variable(&mut self) -> TokenKind {
        // Skip the first @
        self.advance();

        // Check if it's a class variable (@@)
        if self.peek() == Some('@') {
            self.advance();
            // Read the identifier part
            let mut ident = String::new();
            while let Some(ch) = self.peek() {
                if Self::is_identifier_continue(ch) {
                    ident.push(ch);
                    self.advance();
                } else {
                    break;
                }
            }
            TokenKind::ClassVar(ident)
        } else {
            // Instance variable (@)
            let mut ident = String::new();
            while let Some(ch) = self.peek() {
                if Self::is_identifier_continue(ch) {
                    ident.push(ch);
                    self.advance();
                } else {
                    break;
                }
            }
            TokenKind::InstanceVar(ident)
        }
    }

    /// Read a global variable ($var)
    fn read_global_variable(&mut self) -> TokenKind {
        // Skip the $
        self.advance();
        let mut ident = String::new();
        while let Some(ch) = self.peek() {
            if Self::is_identifier_continue(ch) {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        TokenKind::GlobalVar(ident)
    }

    /// Convert a string to a keyword token or identifier
    fn keyword_or_identifier(&self, ident: String) -> TokenKind {
        match ident.as_str() {
            "def" => TokenKind::Def,
            "class" => TokenKind::Class,
            "if" => TokenKind::If,
            "elsif" => TokenKind::Elsif,
            "else" => TokenKind::Else,
            "unless" => TokenKind::Unless,
            "while" => TokenKind::While,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "end" => TokenKind::End,
            "do" => TokenKind::Do,
            "begin" => TokenKind::Begin,
            "rescue" => TokenKind::Rescue,
            "ensure" => TokenKind::Ensure,
            "raise" => TokenKind::Raise,
            "break" => TokenKind::Break,
            "continue" => TokenKind::Continue,
            "return" => TokenKind::Return,
            "lambda" => TokenKind::Lambda,
            "super" => TokenKind::Super,
            "case" => TokenKind::Case,
            "when" => TokenKind::When,
            "then" => TokenKind::Then,
            "attr_reader" => TokenKind::AttrReader,
            "attr_writer" => TokenKind::AttrWriter,
            "attr_accessor" => TokenKind::AttrAccessor,
            "module" => TokenKind::Module,
            "include" => TokenKind::Include,
            "extend" => TokenKind::Extend,
            "true" => TokenKind::True,
            "false" => TokenKind::False,
            "nil" => TokenKind::Nil,
            _ => TokenKind::Ident(ident),
        }
    }

    /// Read a string literal (single or double quoted)
    fn read_string(&mut self, quote: char) -> Result<TokenKind, String> {
        let mut parts = Vec::new();
        let mut current_text = String::new();
        let has_interpolation = quote == '"'; // Only double-quoted strings support interpolation

        // Skip the opening quote
        self.advance();

        loop {
            match self.peek() {
                None => {
                    return Err(format!(
                        "Unterminated string starting at line {}",
                        self.line
                    ));
                }
                Some('\n') => {
                    return Err(format!(
                        "Unterminated string starting at line {}",
                        self.line
                    ));
                }
                Some(ch) if ch == quote => {
                    // Found closing quote
                    self.advance();

                    // If we have interpolation parts, return an interpolated string
                    if has_interpolation && !parts.is_empty() {
                        if !current_text.is_empty() {
                            parts.push(InterpolationPart::Text(current_text));
                        }
                        return Ok(TokenKind::InterpolatedString(parts));
                    } else {
                        return Ok(TokenKind::String(current_text));
                    }
                }
                Some('\\') => {
                    // Handle escape sequences
                    self.advance();
                    match self.peek() {
                        Some('n') => {
                            current_text.push('\n');
                            self.advance();
                        }
                        Some('t') => {
                            current_text.push('\t');
                            self.advance();
                        }
                        Some('r') => {
                            current_text.push('\r');
                            self.advance();
                        }
                        Some('\\') => {
                            current_text.push('\\');
                            self.advance();
                        }
                        Some('"') => {
                            current_text.push('"');
                            self.advance();
                        }
                        Some('\'') => {
                            current_text.push('\'');
                            self.advance();
                        }
                        Some('#') => {
                            // Escaped hash - allows literal #{
                            current_text.push('#');
                            self.advance();
                        }
                        Some(ch) => {
                            // For unrecognized escape sequences, include the backslash
                            current_text.push('\\');
                            current_text.push(ch);
                            self.advance();
                        }
                        None => {
                            return Err(format!(
                                "Unterminated string starting at line {}",
                                self.line
                            ));
                        }
                    }
                }
                Some('#') if has_interpolation => {
                    // Check if this is the start of interpolation (#{)
                    self.advance();
                    if self.peek() == Some('{') {
                        // Start of interpolation
                        self.advance();

                        // Save current text as a part
                        if !current_text.is_empty() {
                            parts.push(InterpolationPart::Text(current_text.clone()));
                            current_text.clear();
                        }

                        // Read the expression until we find }
                        let mut expr = String::new();
                        let mut depth = 1; // Track nested braces

                        loop {
                            match self.peek() {
                                None => {
                                    return Err(format!(
                                        "Unterminated interpolation starting at line {}",
                                        self.line
                                    ));
                                }
                                Some('\n') => {
                                    return Err(format!(
                                        "Unterminated interpolation starting at line {}",
                                        self.line
                                    ));
                                }
                                Some('{') => {
                                    depth += 1;
                                    expr.push('{');
                                    self.advance();
                                }
                                Some('}') => {
                                    depth -= 1;
                                    if depth == 0 {
                                        self.advance();
                                        parts.push(InterpolationPart::Expression(expr));
                                        break;
                                    } else {
                                        expr.push('}');
                                        self.advance();
                                    }
                                }
                                Some(ch) => {
                                    expr.push(ch);
                                    self.advance();
                                }
                            }
                        }
                    } else {
                        // Not interpolation, just a # character
                        current_text.push('#');
                    }
                }
                Some(ch) => {
                    current_text.push(ch);
                    self.advance();
                }
            }
        }
    }

    /// Peek at the next token without consuming it
    pub fn peek_token(&mut self) -> Token {
        // Save current state
        let saved_chars = self.chars.clone();
        let saved_line = self.line;
        let saved_column = self.column;
        let saved_offset = self.offset;

        // Get the next token
        let token = self.next_token();

        // Restore state
        self.chars = saved_chars;
        self.line = saved_line;
        self.column = saved_column;
        self.offset = saved_offset;

        token
    }

    /// Collect all tokens from the lexer
    pub fn tokenize(mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let token = self.next_token();
            if token.kind == TokenKind::EOF {
                tokens.push(token);
                break;
            }
            tokens.push(token);
        }
        tokens
    }

    /// Get the next token from the source code
    pub fn next_token(&mut self) -> Token {
        // Skip whitespace (but not newlines)
        self.skip_whitespace();

        let position = self.current_position();

        // Check for end of input
        if let Some(ch) = self.peek() {
            match ch {
                '\n' => {
                    self.advance();
                    Token::new(TokenKind::Newline, position)
                }
                '#' => {
                    let comment = self.read_comment();
                    Token::new(TokenKind::Comment(comment), position)
                }
                '0'..='9' => {
                    let kind = self.read_number();
                    Token::new(kind, position)
                }
                '"' | '\'' => match self.read_string(ch) {
                    Ok(kind) => Token::new(kind, position),
                    Err(_err) => {
                        // For now, return EOF on error
                        // TODO: Proper error handling will be added later
                        Token::new(TokenKind::EOF, position)
                    }
                },
                '@' => {
                    let kind = self.read_variable();
                    Token::new(kind, position)
                }
                '$' => {
                    let kind = self.read_global_variable();
                    Token::new(kind, position)
                }
                ch if Self::is_identifier_start(ch) => {
                    let kind = self.read_identifier();
                    Token::new(kind, position)
                }
                // Single-character operators and compound operators
                '+' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::PlusEqual, position)
                    } else {
                        Token::new(TokenKind::Plus, position)
                    }
                }
                '-' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::MinusEqual, position)
                    } else if self.peek() == Some('>') {
                        self.advance();
                        Token::new(TokenKind::Arrow, position)
                    } else {
                        Token::new(TokenKind::Minus, position)
                    }
                }
                '*' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::StarEqual, position)
                    } else {
                        Token::new(TokenKind::Star, position)
                    }
                }
                '/' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::SlashEqual, position)
                    } else {
                        Token::new(TokenKind::Slash, position)
                    }
                }
                '%' => {
                    self.advance();
                    Token::new(TokenKind::Percent, position)
                }
                '=' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::EqualEqual, position)
                    } else if self.peek() == Some('>') {
                        self.advance();
                        Token::new(TokenKind::FatArrow, position)
                    } else {
                        Token::new(TokenKind::Equal, position)
                    }
                }
                '!' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::BangEqual, position)
                    } else {
                        Token::new(TokenKind::Bang, position)
                    }
                }
                '<' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::LessEqual, position)
                    } else {
                        Token::new(TokenKind::Less, position)
                    }
                }
                '>' => {
                    self.advance();
                    if self.peek() == Some('=') {
                        self.advance();
                        Token::new(TokenKind::GreaterEqual, position)
                    } else {
                        Token::new(TokenKind::Greater, position)
                    }
                }
                // Delimiters
                '(' => {
                    self.advance();
                    Token::new(TokenKind::LParen, position)
                }
                ')' => {
                    self.advance();
                    Token::new(TokenKind::RParen, position)
                }
                '{' => {
                    self.advance();
                    Token::new(TokenKind::LBrace, position)
                }
                '}' => {
                    self.advance();
                    Token::new(TokenKind::RBrace, position)
                }
                '[' => {
                    self.advance();
                    Token::new(TokenKind::LBracket, position)
                }
                ']' => {
                    self.advance();
                    Token::new(TokenKind::RBracket, position)
                }
                ',' => {
                    self.advance();
                    Token::new(TokenKind::Comma, position)
                }
                '.' => {
                    self.advance();
                    // Check for .. or ...
                    if self.peek() == Some('.') {
                        self.advance();
                        // Check for third dot
                        if self.peek() == Some('.') {
                            self.advance();
                            Token::new(TokenKind::DotDotDot, position)
                        } else {
                            Token::new(TokenKind::DotDot, position)
                        }
                    } else {
                        Token::new(TokenKind::Dot, position)
                    }
                }
                ':' => {
                    self.advance();
                    if self.peek() == Some(':') {
                        self.advance();
                        Token::new(TokenKind::ColonColon, position)
                    } else {
                        Token::new(TokenKind::Colon, position)
                    }
                }
                ';' => {
                    self.advance();
                    Token::new(TokenKind::Semicolon, position)
                }
                '|' => {
                    self.advance();
                    if self.peek() == Some('|') {
                        self.advance();
                        Token::new(TokenKind::LogicalOr, position)
                    } else {
                        Token::new(TokenKind::Pipe, position)
                    }
                }
                '&' => {
                    self.advance();
                    if self.peek() == Some('&') {
                        self.advance();
                        Token::new(TokenKind::LogicalAnd, position)
                    } else {
                        Token::new(TokenKind::Ampersand, position)
                    }
                }
                _ => {
                    // Unknown character, consume and return EOF
                    self.advance();
                    Token::new(TokenKind::EOF, position)
                }
            }
        } else {
            Token::new(TokenKind::EOF, position)
        }
    }
}

/// Iterator implementation for Lexer
/// This allows using the lexer in for loops and with iterator methods
impl<'a> Iterator for Lexer<'a> {
    type Item = Token;

    fn next(&mut self) -> Option<Self::Item> {
        let token = self.next_token();
        if token.kind == TokenKind::EOF {
            None
        } else {
            Some(token)
        }
    }
}

