// Object operations - comparison and boolean logic

use super::Object;

impl Object {
    /// Check if this object is truthy (for conditional evaluation)
    pub fn is_truthy(&self) -> bool {
        match self {
            Object::Nil => false,
            Object::Bool(b) => *b,
            // All other values are truthy
            _ => true,
        }
    }

    /// Check if this object is falsy
    pub fn is_falsy(&self) -> bool {
        !self.is_truthy()
    }

    /// Deep equality comparison between objects
    pub fn equals(&self, other: &Object) -> bool {
        match (self, other) {
            (Object::Nil, Object::Nil) => true,
            (Object::Bool(a), Object::Bool(b)) => a == b,
            (Object::Int(a), Object::Int(b)) => a == b,
            (Object::Float(a), Object::Float(b)) => {
                // Float comparison with epsilon for floating point precision
                (a - b).abs() < 1e-9
            }
            (Object::String(a), Object::String(b)) => a == b,
            (Object::Array(a), Object::Array(b)) => {
                let arr_a = a.borrow();
                let arr_b = b.borrow();
                if arr_a.len() != arr_b.len() {
                    return false;
                }
                arr_a.iter().zip(arr_b.iter()).all(|(x, y)| x.equals(y))
            }
            (Object::Dict(a), Object::Dict(b)) => {
                let dict_a = a.borrow();
                let dict_b = b.borrow();
                if dict_a.len() != dict_b.len() {
                    return false;
                }
                dict_a
                    .iter()
                    .all(|(key, val)| dict_b.get(key).is_some_and(|v| val.equals(v)))
            }
            (Object::Set(a), Object::Set(b)) => {
                let set_a = a.borrow();
                let set_b = b.borrow();
                if set_a.len() != set_b.len() {
                    return false;
                }
                set_a.iter().all(|item| set_b.contains(item))
            }
            (Object::Result(a), Object::Result(b)) => match (a, b) {
                (Ok(a_val), Ok(b_val)) => a_val.equals(b_val),
                (Err(a_err), Err(b_err)) => a_err.equals(b_err),
                _ => false,
            },
            // Instance, Class, Method, Block, Binding, and Exception comparisons by reference
            (Object::Instance(a), Object::Instance(b)) => Rc::ptr_eq(a, b),
            (Object::Class(a), Object::Class(b)) => Rc::ptr_eq(a, b),
            (Object::Module(a), Object::Module(b)) => Rc::ptr_eq(a, b),
            (Object::Method(a), Object::Method(b)) => Rc::ptr_eq(a, b),
            (Object::Block(a), Object::Block(b)) => Rc::ptr_eq(a, b),
            (Object::Binding(a), Object::Binding(b)) => Rc::ptr_eq(a, b),
            (Object::Exception(a), Object::Exception(b)) => Rc::ptr_eq(a, b),
            // Different types are not equal
            _ => false,
        }
    }

    /// Compute hash for hashable types (for use in dictionaries)
    pub fn hash(&self) -> Option<u64> {
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};

        match self {
            Object::Nil => {
                let mut hasher = DefaultHasher::new();
                "nil".hash(&mut hasher);
                Some(hasher.finish())
            }
            Object::Bool(b) => {
                let mut hasher = DefaultHasher::new();
                b.hash(&mut hasher);
                Some(hasher.finish())
            }
            Object::Int(i) => {
                let mut hasher = DefaultHasher::new();
                i.hash(&mut hasher);
                Some(hasher.finish())
            }
            Object::Float(f) => {
                let mut hasher = DefaultHasher::new();
                // Convert float to bits for consistent hashing
                f.to_bits().hash(&mut hasher);
                Some(hasher.finish())
            }
            Object::String(s) => {
                let mut hasher = DefaultHasher::new();
                s.as_str().hash(&mut hasher);
                Some(hasher.finish())
            }
            // Complex types are not hashable
            _ => None,
        }
    }
}

use std::rc::Rc;

// Core Object enum definition for runtime value representation

use crate::class::Class;
use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::rc::Rc;

use super::{Binding, BlockStatement, Exception, Instance, Method, ObjectHash};

/// Core object type representing all runtime values in Metorex
#[derive(Debug, Clone, PartialEq)]
pub enum Object {
    /// Nil/null value
    Nil,

    /// Boolean value (true or false)
    Bool(bool),

    /// 64-bit signed integer
    Int(i64),

    /// 64-bit floating point number
    Float(f64),

    /// String value (reference counted for efficient copying)
    String(Rc<String>),

    /// Symbol value (interned string identifier, like :name)
    Symbol(Rc<String>),

    /// Array/list of objects (mutable, reference counted)
    Array(Rc<RefCell<Vec<Object>>>),

    /// Dictionary/hash map (mutable, reference counted)
    Dict(Rc<RefCell<HashMap<String, Object>>>),

    /// Instance of a class
    Instance(Rc<RefCell<Instance>>),

    /// Class object (used for class definitions and instantiation)
    Class(Rc<Class>),

    /// Module object (used for mixins via include/extend)
    Module(Rc<Class>),

    /// Method object (bound or unbound)
    Method(Rc<Method>),

    /// Block/lambda/closure (critical for meta-programming)
    Block(Rc<BlockStatement>),

    /// Exception object
    Exception(Rc<RefCell<Exception>>),

    /// Set (unordered collection of unique objects)
    Set(Rc<RefCell<HashSet<ObjectHash>>>),

    /// Result type for explicit error handling
    Result(Result<Box<Object>, Box<Object>>),

    /// Native function (built-in function implemented in Rust)
    NativeFunction(String),

    /// Range object (start..end or start...end)
    Range {
        start: Box<Object>,
        end: Box<Object>,
        exclusive: bool,
    },

    /// Binding object (represents a namespace/scope with captured variables)
    Binding(Rc<Binding>),
}

impl Object {
    /// Get the type name of this object
    pub fn type_name(&self) -> &'static str {
        match self {
            Object::Nil => "Nil",
            Object::Bool(_) => "Bool",
            Object::Int(_) => "Int",
            Object::Float(_) => "Float",
            Object::String(_) => "String",
            Object::Symbol(_) => "Symbol",
            Object::Array(_) => "Array",
            Object::Dict(_) => "Dict",
            Object::Instance(_) => "Instance",
            Object::Class(_) => "Class",
            Object::Module(_) => "Module",
            Object::Method(_) => "Method",
            Object::Block(_) => "Block",
            Object::Exception(_) => "Exception",
            Object::Set(_) => "Set",
            Object::Result(_) => "Result",
            Object::NativeFunction(_) => "NativeFunction",
            Object::Range { .. } => "Range",
            Object::Binding(_) => "Binding",
        }
    }
}

// Error handling for the parser
// Manages error creation, reporting, and recovery

use crate::error::{MetorexError, SourceLocation};
use crate::lexer::{Position, Token};

/// Error handling state for the parser
pub struct ErrorHandler {
    /// Errors encountered during parsing
    errors: Vec<MetorexError>,
    /// Flag indicating if we're in panic mode (error recovery)
    panic_mode: bool,
}

impl ErrorHandler {
    /// Create a new error handler
    pub fn new() -> Self {
        Self {
            errors: Vec::new(),
            panic_mode: false,
        }
    }

    /// Get all collected errors
    pub fn errors(&self) -> &[MetorexError] {
        &self.errors
    }

    /// Check if any errors have been collected
    pub fn has_errors(&self) -> bool {
        !self.errors.is_empty()
    }

    /// Convert a Position to a SourceLocation
    pub fn position_to_location(&self, position: Position) -> SourceLocation {
        SourceLocation::new(position.line, position.column, position.offset)
    }

    /// Create an error at the current token
    pub fn error_at_current(&self, message: &str, current_token: &Token) -> MetorexError {
        let location = self.position_to_location(current_token.position);
        MetorexError::syntax_error(message, location)
    }

    /// Create an error at the previous token
    pub fn error_at_previous(&self, message: &str, previous_token: &Token) -> MetorexError {
        let location = self.position_to_location(previous_token.position);
        MetorexError::syntax_error(message, location)
    }

    /// Report an error and enter panic mode
    pub fn report_error(&mut self, error: MetorexError) {
        if !self.panic_mode {
            self.panic_mode = true;
            self.errors.push(error);
        }
    }

    /// Exit panic mode (called at the start of synchronization)
    pub fn start_synchronize(&mut self) {
        self.panic_mode = false;
    }
}

impl Default for ErrorHandler {
    fn default() -> Self {
        Self::new()
    }
}

// Binary operator parsing
// Handles parsing of binary operations with proper precedence

use crate::ast::{BinaryOp, Expression};
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse logical OR (||)
    pub(crate) fn parse_logical_or(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_logical_and()?;

        while self.check(&[TokenKind::LogicalOr]) {
            let op_token = self.advance();
            let right = self.parse_logical_and()?;
            expr = Expression::BinaryOp {
                op: BinaryOp::Or,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse logical AND (&&)
    pub(crate) fn parse_logical_and(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_equality()?;

        while self.check(&[TokenKind::LogicalAnd]) {
            let op_token = self.advance();
            let right = self.parse_equality()?;
            expr = Expression::BinaryOp {
                op: BinaryOp::And,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse equality operators (==, !=)
    pub(crate) fn parse_equality(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_comparison()?;

        while self.check(&[TokenKind::EqualEqual, TokenKind::BangEqual]) {
            let op_token = self.advance();
            let op = match op_token.kind {
                TokenKind::EqualEqual => BinaryOp::Equal,
                TokenKind::BangEqual => BinaryOp::NotEqual,
                _ => unreachable!(),
            };
            let right = self.parse_comparison()?;
            expr = Expression::BinaryOp {
                op,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse comparison operators (<, >, <=, >=)
    pub(crate) fn parse_comparison(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_range()?;

        while self.check(&[
            TokenKind::Less,
            TokenKind::Greater,
            TokenKind::LessEqual,
            TokenKind::GreaterEqual,
        ]) {
            let op_token = self.advance();
            let op = match op_token.kind {
                TokenKind::Less => BinaryOp::Less,
                TokenKind::Greater => BinaryOp::Greater,
                TokenKind::LessEqual => BinaryOp::LessEqual,
                TokenKind::GreaterEqual => BinaryOp::GreaterEqual,
                _ => unreachable!(),
            };
            let right = self.parse_range()?;
            expr = Expression::BinaryOp {
                op,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse range operators (.., ...)
    pub(crate) fn parse_range(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_term()?;

        if self.check(&[TokenKind::DotDot, TokenKind::DotDotDot]) {
            let op_token = self.advance();
            let exclusive = op_token.kind == TokenKind::DotDotDot;
            let end = self.parse_term()?;
            expr = Expression::Range {
                start: Box::new(expr),
                end: Box::new(end),
                exclusive,
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse addition and subtraction
    pub(crate) fn parse_term(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_factor()?;

        while self.check(&[TokenKind::Plus, TokenKind::Minus]) {
            let op_token = self.advance();
            let op = match op_token.kind {
                TokenKind::Plus => BinaryOp::Add,
                TokenKind::Minus => BinaryOp::Subtract,
                _ => unreachable!(),
            };
            let right = self.parse_factor()?;
            expr = Expression::BinaryOp {
                op,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }

    /// Parse multiplication, division, and modulo
    pub(crate) fn parse_factor(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_unary()?;

        while self.check(&[TokenKind::Star, TokenKind::Slash, TokenKind::Percent]) {
            let op_token = self.advance();
            let op = match op_token.kind {
                TokenKind::Star => BinaryOp::Multiply,
                TokenKind::Slash => BinaryOp::Divide,
                TokenKind::Percent => BinaryOp::Modulo,
                _ => unreachable!(),
            };
            let right = self.parse_unary()?;
            expr = Expression::BinaryOp {
                op,
                left: Box::new(expr),
                right: Box::new(right),
                position: op_token.position,
            };
        }

        Ok(expr)
    }
}

// Function and method call parsing
// Handles parsing of function calls, method calls, and array indexing

use crate::ast::Expression;
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse function calls and method calls
    pub(crate) fn parse_call(&mut self) -> Result<Expression, MetorexError> {
        let mut expr = self.parse_primary()?;

        loop {
            if self.match_token(&[TokenKind::LParen]) {
                // Function call with parentheses
                expr = self.finish_call(expr)?;
            } else if self.match_token(&[TokenKind::Dot]) {
                // Method call
                let method_name = match self.advance().kind {
                    TokenKind::Ident(name) => name,
                    // Allow keywords as method names (e.g., obj.class, obj.if, etc.)
                    TokenKind::Class => "class".to_string(),
                    TokenKind::If => "if".to_string(),
                    TokenKind::Def => "def".to_string(),
                    TokenKind::End => "end".to_string(),
                    TokenKind::Do => "do".to_string(),
                    TokenKind::Else => "else".to_string(),
                    TokenKind::Elsif => "elsif".to_string(),
                    TokenKind::Unless => "unless".to_string(),
                    TokenKind::While => "while".to_string(),
                    TokenKind::For => "for".to_string(),
                    TokenKind::In => "in".to_string(),
                    TokenKind::Begin => "begin".to_string(),
                    TokenKind::Rescue => "rescue".to_string(),
                    TokenKind::Ensure => "ensure".to_string(),
                    TokenKind::Raise => "raise".to_string(),
                    TokenKind::Break => "break".to_string(),
                    TokenKind::Continue => "continue".to_string(),
                    TokenKind::Return => "return".to_string(),
                    TokenKind::Lambda => "lambda".to_string(),
                    TokenKind::Super => "super".to_string(),
                    TokenKind::Case => "case".to_string(),
                    TokenKind::When => "when".to_string(),
                    _ => return Err(self.error_at_previous("Expected method name after '.'")),
                };

                // Check if there are arguments
                let arguments = if self.match_token(&[TokenKind::LParen]) {
                    self.parse_arguments()?
                } else {
                    Vec::new()
                };

                // Check for trailing block (both do...end and {...} syntax)
                let trailing_block = if self.check(&[TokenKind::Do]) {
                    Some(Box::new(self.parse_block()?))
                } else if self.check(&[TokenKind::LBrace]) {
                    Some(Box::new(self.parse_brace_block()?))
                } else {
                    None
                };

                let position = expr.position();
                expr = Expression::MethodCall {
                    receiver: Box::new(expr),
                    method: method_name,
                    arguments,
                    trailing_block,
                    position,
                };
            } else if self.match_token(&[TokenKind::LBracket]) {
                // Array indexing
                let index = self.parse_expression()?;
                self.expect(TokenKind::RBracket, "Expected ']' after array index")?;
                let position = expr.position();
                expr = Expression::Index {
                    array: Box::new(expr),
                    index: Box::new(index),
                    position,
                };
            } else if self.match_token(&[TokenKind::ColonColon]) {
                // Scope resolution (e.g., Math::PI, Foo::Bar)
                let position = expr.position();
                let name_token = self.advance();
                let name = match name_token.kind {
                    TokenKind::Ident(name) => name,
                    _ => return Err(self.error_at_previous("Expected constant name after '::'")),
                };
                expr = Expression::ScopeResolution {
                    namespace: Box::new(expr),
                    name,
                    position,
                };
            } else if self.can_start_argument_for_call(&expr) {
                // Ruby-style function call without parentheses
                // Only parse this if we have an identifier as the callee
                if matches!(expr, Expression::Identifier { .. }) {
                    expr = self.finish_call_without_parens(expr)?;
                } else {
                    break;
                }
            } else if matches!(expr, Expression::Identifier { .. })
                && !matches!(self.peek().kind, TokenKind::Newline | TokenKind::Comment(_))
            {
                // Check for trailing-block-only call: foo { block } or foo do block end
                // (no arguments, but a trailing block on the same line)
                self.skip_whitespace();
                if self.check(&[TokenKind::LBrace]) || self.check(&[TokenKind::Do]) {
                    let position = expr.position();
                    let trailing_block = if self.check(&[TokenKind::Do]) {
                        Some(Box::new(self.parse_block()?))
                    } else {
                        Some(Box::new(self.parse_brace_block()?))
                    };
                    expr = Expression::Call {
                        callee: Box::new(expr),
                        arguments: vec![],
                        trailing_block,
                        position,
                    };
                } else {
                    break;
                }
            } else {
                break;
            }
        }

        Ok(expr)
    }

    /// Finish parsing a function call
    pub(crate) fn finish_call(&mut self, callee: Expression) -> Result<Expression, MetorexError> {
        let arguments = self.parse_arguments()?;

        // Check for trailing block (both do...end and {...} syntax)
        let trailing_block = if self.check(&[TokenKind::Do]) {
            Some(Box::new(self.parse_block()?))
        } else if self.check(&[TokenKind::LBrace]) {
            Some(Box::new(self.parse_brace_block()?))
        } else {
            None
        };

        let position = callee.position();

        Ok(Expression::Call {
            callee: Box::new(callee),
            arguments,
            trailing_block,
            position,
        })
    }

    /// Parse function/method arguments (with parentheses)
    pub(crate) fn parse_arguments(&mut self) -> Result<Vec<Expression>, MetorexError> {
        let mut arguments = Vec::new();
        self.skip_whitespace();

        if self.check(&[TokenKind::RParen]) {
            self.advance();
            return Ok(arguments);
        }

        // Collect any keyword args (ident: value) to build a hash at the end
        let mut keyword_pairs: Vec<(String, Expression)> = Vec::new();

        loop {
            self.skip_whitespace();

            // Detect keyword argument: Ident followed by Colon
            if matches!(self.peek().kind, TokenKind::Ident(_))
                && matches!(self.peek_ahead(1).kind, TokenKind::Colon)
            {
                let name = match self.advance().kind {
                    TokenKind::Ident(n) => n,
                    _ => unreachable!(),
                };
                self.advance(); // consume ':'
                self.skip_whitespace();
                let value = self.parse_expression()?;
                keyword_pairs.push((name, value));
            } else {
                arguments.push(self.parse_expression()?);
            }

            self.skip_whitespace();

            if !self.match_token(&[TokenKind::Comma]) {
                break;
            }
        }

        // If there were keyword args, append them as a Dict at the end of arguments
        if !keyword_pairs.is_empty() {
            let position = self.peek().position;
            arguments.push(Expression::Dictionary {
                entries: keyword_pairs
                    .into_iter()
                    .map(|(k, v)| {
                        (
                            Expression::StringLiteral {
                                value: format!(":{}", k),
                                position,
                            },
                            v,
                        )
                    })
                    .collect(),
                position,
            });
        }

        self.skip_whitespace();
        self.expect(TokenKind::RParen, "Expected ')' after arguments")?;

        Ok(arguments)
    }

    /// Check if the next token can start an argument in a parentheses-less call
    /// Also checks if this looks like a dictionary context (value followed by colon)
    fn can_start_argument_for_call(&mut self, _callee: &Expression) -> bool {
        // Don't skip whitespace yet - we need to check if there's a newline first
        // Parentheses-less calls should be on the same line
        if matches!(self.peek().kind, TokenKind::Newline | TokenKind::Comment(_)) {
            return false;
        }

        self.skip_whitespace();

        // Don't parse as function call if we see operators or punctuation that
        // indicate we're in a different context (like dictionary key: value)
        // Also check for binary operators that shouldn't start an argument
        if matches!(
            self.peek().kind,
            TokenKind::Colon
                | TokenKind::RBrace
                | TokenKind::Comma
                | TokenKind::Plus
                | TokenKind::Minus
                | TokenKind::Star
                | TokenKind::Slash
                | TokenKind::Percent
                | TokenKind::Equal
                | TokenKind::EqualEqual
                | TokenKind::BangEqual
                | TokenKind::Less
                | TokenKind::Greater
                | TokenKind::LessEqual
                | TokenKind::GreaterEqual
        ) {
            return false;
        }

        // Check if next token can be an argument
        let can_be_arg = matches!(
            self.peek().kind,
            TokenKind::Ident(_)
                | TokenKind::Int(_)
                | TokenKind::Float(_)
                | TokenKind::String(_)
                | TokenKind::InterpolatedString(_)
                | TokenKind::True
                | TokenKind::False
                | TokenKind::Nil
                | TokenKind::LBracket
                | TokenKind::InstanceVar(_)
                | TokenKind::ClassVar(_)
                | TokenKind::GlobalVar(_)
                | TokenKind::Bang
        );

        if !can_be_arg {
            return false;
        }

        // Pattern 1: <ident> ':' is a keyword argument (name: value), allow it
        // but only for Ident — not Int/Float/String followed by colon (those are dict-like)
        if matches!(self.peek_ahead(1).kind, TokenKind::Colon)
            && !matches!(self.peek().kind, TokenKind::Ident(_))
        {
            return false;
        }

        // Pattern 2: <arg> ',' - suggests dict with missing colon like {x 1, y: 2}
        // In valid code, function arguments are separated by commas, but they're inside
        // parentheses. At statement level, we don't expect immediate comma after arg.
        if matches!(self.peek_ahead(1).kind, TokenKind::Comma) {
            return false;
        }

        // Pattern 3: <arg> '}' - suggests dict with missing colon like {x 1}
        if matches!(self.peek_ahead(1).kind, TokenKind::RBrace) {
            return false;
        }

        true
    }

    /// Finish parsing a function call without parentheses (Ruby-style)
    fn finish_call_without_parens(
        &mut self,
        callee: Expression,
    ) -> Result<Expression, MetorexError> {
        let mut arguments = Vec::new();
        let mut keyword_pairs: Vec<(String, Expression)> = Vec::new();
        let position = callee.position();

        self.skip_whitespace();

        // Parse first argument — detect keyword arg pattern (Ident :)
        if matches!(self.peek().kind, TokenKind::Ident(_))
            && matches!(self.peek_ahead(1).kind, TokenKind::Colon)
        {
            let name = match self.advance().kind {
                TokenKind::Ident(n) => n,
                _ => unreachable!(),
            };
            self.advance(); // consume ':'
            self.skip_whitespace();
            let value = self.parse_expression()?;
            keyword_pairs.push((name, value));
        } else {
            arguments.push(self.parse_expression()?);

            // After parsing the first positional argument, check if we see a colon
            // (which would indicate dict syntax, not a function call).
            // Do NOT call skip_whitespace() here — consuming a newline would make the
            // next line's '[' look like array indexing on this call expression.
            if self.check(&[TokenKind::Colon]) {
                return Err(self
                    .error_at_current("Expected function call but found dictionary-like syntax"));
            }
        }

        // Parse remaining arguments if there are commas
        while self.match_token(&[TokenKind::Comma]) {
            self.skip_whitespace();

            // Stop if we hit a statement terminator or keyword
            if self.check(&[
                TokenKind::Newline,
                TokenKind::Semicolon,
                TokenKind::End,
                TokenKind::Else,
                TokenKind::Rescue,
                TokenKind::Ensure,
                TokenKind::Do,
            ]) || self.is_at_end()
            {
                break;
            }

            // Detect keyword argument
            if matches!(self.peek().kind, TokenKind::Ident(_))
                && matches!(self.peek_ahead(1).kind, TokenKind::Colon)
            {
                let name = match self.advance().kind {
                    TokenKind::Ident(n) => n,
                    _ => unreachable!(),
                };
                self.advance(); // consume ':'
                self.skip_whitespace();
                let value = self.parse_expression()?;
                keyword_pairs.push((name, value));
            } else {
                arguments.push(self.parse_expression()?);
            }
            self.skip_whitespace();
        }

        // If there were keyword args, append them as a Dict
        if !keyword_pairs.is_empty() {
            arguments.push(Expression::Dictionary {
                entries: keyword_pairs
                    .into_iter()
                    .map(|(k, v)| {
                        (
                            Expression::StringLiteral {
                                value: format!(":{}", k),
                                position,
                            },
                            v,
                        )
                    })
                    .collect(),
                position,
            });
        }

        // Check for trailing block (both do...end and {...} syntax)
        let trailing_block = if self.check(&[TokenKind::Do]) {
            Some(Box::new(self.parse_block()?))
        } else if self.check(&[TokenKind::LBrace]) {
            Some(Box::new(self.parse_brace_block()?))
        } else {
            None
        };

        Ok(Expression::Call {
            callee: Box::new(callee),
            arguments,
            trailing_block,
            position,
        })
    }
}

// Expression parsing module
// Handles parsing of all expression types

mod binary;
mod call;
mod primary;
mod unary;

use crate::ast::Expression;
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse an expression using operator precedence climbing
    pub(crate) fn parse_expression(&mut self) -> Result<Expression, MetorexError> {
        self.parse_assignment()
    }

    /// Parse expression with arrow lambda support (for top-level expressions only)
    pub(crate) fn parse_expression_with_lambda(&mut self) -> Result<Expression, MetorexError> {
        self.parse_arrow_lambda()
    }

    /// Parse arrow lambda syntax: x -> expr, (x, y) -> expr, or -> expr
    pub(crate) fn parse_arrow_lambda(&mut self) -> Result<Expression, MetorexError> {
        // Check for zero-param arrow lambda: -> expr
        if self.check(&[TokenKind::Arrow]) {
            let arrow_pos = self.advance().position;
            self.skip_whitespace();
            let expr = self.parse_assignment()?;

            // Convert expression to a statement
            let body = vec![crate::ast::Statement::Expression {
                expression: expr,
                position: arrow_pos,
            }];

            return Ok(Expression::Lambda {
                parameters: Vec::new(),
                body,
                captured_vars: Some(Vec::new()), // Empty vec signals automatic capture
                position: arrow_pos,
            });
        }

        // Special case: check for multi-param arrow lambda: (x, y) -> expr
        // Use lookahead to avoid consuming tokens unless it's definitely a lambda
        if self.check(&[TokenKind::LParen]) {
            let saved_position = self.stream().current_position();
            let start_pos = self.peek().position;

            self.advance(); // consume '('
            self.skip_whitespace();

            // Try to parse as comma-separated identifiers
            let mut params = Vec::new();
            let mut is_param_list = true;

            if !self.check(&[TokenKind::RParen]) {
                loop {
                    self.skip_whitespace();
                    if let TokenKind::Ident(name) = self.peek().kind.clone() {
                        params.push(name);
                        self.advance();
                    } else {
                        is_param_list = false;
                        break;
                    }

                    self.skip_whitespace();
                    if self.match_token(&[TokenKind::Comma]) {
                        continue;
                    } else {
                        break;
                    }
                }
            }

            self.skip_whitespace();

            // Check if this looks like a parameter list: ) followed by ->
            if is_param_list && self.check(&[TokenKind::RParen]) {
                self.advance(); // consume ')'
                self.skip_whitespace();

                if self.check(&[TokenKind::Arrow]) {
                    // It's a multi-param arrow lambda!
                    let arrow_pos = self.advance().position;
                    self.skip_whitespace();

                    let body_expr = self.parse_assignment()?;
                    let body = vec![crate::ast::Statement::Expression {
                        expression: body_expr,
                        position: arrow_pos,
                    }];

                    return Ok(Expression::Lambda {
                        parameters: params,
                        body,
                        captured_vars: Some(Vec::new()), // Empty vec signals automatic capture
                        position: start_pos,
                    });
                }
            }

            // Not a multi-param lambda, backtrack and parse normally
            let stream = &mut self.stream;
            stream.restore_position(saved_position);
        }

        // Try to parse as regular expression first
        let expr = self.parse_assignment()?;

        // Check if there's an arrow after the expression
        if self.check(&[TokenKind::Arrow]) {
            let arrow_pos = self.advance().position;
            self.skip_whitespace();

            // Extract parameters from the left side
            let parameters = match &expr {
                // Single parameter: x -> expr
                Expression::Identifier { name, .. } => {
                    vec![name.clone()]
                }
                // Multiple parameters: (x, y) -> expr
                Expression::Grouped { expression, .. } => {
                    // Check if it's a tuple of identifiers (we'll handle this as comma-separated for now)
                    // For now, we'll just support single grouped identifier
                    if let Expression::Identifier { name, .. } = expression.as_ref() {
                        vec![name.clone()]
                    } else {
                        return Err(
                            self.error_at_current("Arrow lambda parameters must be identifiers")
                        );
                    }
                }
                _ => {
                    return Err(self.error_at_current("Left side of arrow must be parameter(s)"));
                }
            };

            // Parse the lambda body
            let body_expr = self.parse_assignment()?;
            let body = vec![crate::ast::Statement::Expression {
                expression: body_expr,
                position: arrow_pos,
            }];

            return Ok(Expression::Lambda {
                parameters,
                body,
                captured_vars: Some(Vec::new()), // Empty vec signals automatic capture
                position: expr.position(),
            });
        }

        Ok(expr)
    }

    /// Parse assignment (lowest precedence)
    pub(crate) fn parse_assignment(&mut self) -> Result<Expression, MetorexError> {
        self.parse_logical_or()
    }

    /// Parse a block: `do |param1, param2| ... end`
    pub(crate) fn parse_block(&mut self) -> Result<Expression, MetorexError> {
        let start_pos = self.peek().position;

        // Expect 'do' keyword
        self.expect(TokenKind::Do, "Expected 'do' to start block")?;
        self.skip_whitespace();

        // Parse block parameters (e.g., |x, y| or || for empty params)
        let parameters = if self.match_token(&[TokenKind::LogicalOr]) {
            // Empty parameter list: ||
            Vec::new()
        } else if self.match_token(&[TokenKind::Pipe]) {
            let mut params = Vec::new();
            self.skip_whitespace();

            if !self.check(&[TokenKind::Pipe]) {
                loop {
                    self.skip_whitespace();
                    let param_token = self.advance();
                    match param_token.kind {
                        TokenKind::Ident(name) => params.push(name),
                        _ => return Err(self.error_at_previous("Expected parameter name")),
                    }
                    self.skip_whitespace();

                    if !self.match_token(&[TokenKind::Comma]) {
                        break;
                    }
                }
            }

            self.skip_whitespace();
            self.expect(TokenKind::Pipe, "Expected '|' after block parameters")?;
            params
        } else {
            Vec::new()
        };

        self.skip_whitespace();

        // Parse block body
        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.expect(TokenKind::End, "Expected 'end' to close block")?;

        Ok(Expression::Lambda {
            parameters,
            body,
            captured_vars: None, // Will be filled by semantic analysis
            position: start_pos,
        })
    }

    /// Parse a block with brace syntax: { |x| ... }
    pub(crate) fn parse_brace_block(&mut self) -> Result<Expression, MetorexError> {
        let start_pos = self.peek().position;

        // Expect '{' to start block
        self.expect(TokenKind::LBrace, "Expected '{' to start block")?;
        self.skip_whitespace();

        // Parse block parameters (e.g., |x, y| or || for empty params)
        let parameters = if self.match_token(&[TokenKind::LogicalOr]) {
            // Empty parameter list: ||
            Vec::new()
        } else if self.match_token(&[TokenKind::Pipe]) {
            let mut params = Vec::new();
            self.skip_whitespace();

            if !self.check(&[TokenKind::Pipe]) {
                loop {
                    self.skip_whitespace();
                    let param_token = self.advance();
                    match param_token.kind {
                        TokenKind::Ident(name) => params.push(name),
                        _ => return Err(self.error_at_previous("Expected parameter name")),
                    }
                    self.skip_whitespace();

                    if !self.match_token(&[TokenKind::Comma]) {
                        break;
                    }
                }
            }

            self.skip_whitespace();
            self.expect(TokenKind::Pipe, "Expected '|' after block parameters")?;
            params
        } else {
            Vec::new()
        };

        self.skip_whitespace();

        // Parse block body (single expression or statements)
        let mut body = Vec::new();
        while !self.check(&[TokenKind::RBrace]) && !self.is_at_end() {
            // For brace blocks, we typically expect a single expression
            // but we'll parse statements to be flexible
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.expect(TokenKind::RBrace, "Expected '}' to close block")?;

        Ok(Expression::Lambda {
            parameters,
            body,
            captured_vars: None, // Will be filled by semantic analysis
            position: start_pos,
        })
    }
}

// Primary expression parsing
// Handles parsing of literals, identifiers, and compound expressions

use crate::ast::Expression;
use crate::ast::node::{ElsifBranch, ExprMatchCase};
use crate::error::MetorexError;
use crate::lexer::{Position, TokenKind};
use crate::parser::Parser;

impl Parser {
    /// Parse primary expressions (literals, identifiers, groups)
    pub(crate) fn parse_primary(&mut self) -> Result<Expression, MetorexError> {
        let token = self.advance();

        match token.kind {
            // Literals
            TokenKind::Int(value) => Ok(Expression::IntLiteral {
                value,
                position: token.position,
            }),
            TokenKind::Float(value) => Ok(Expression::FloatLiteral {
                value,
                position: token.position,
            }),
            TokenKind::String(value) => Ok(Expression::StringLiteral {
                value,
                position: token.position,
            }),
            TokenKind::InterpolatedString(parts) => {
                // Convert token interpolation parts to AST interpolation parts
                let mut ast_parts = Vec::new();
                for part in parts {
                    match part {
                        crate::lexer::InterpolationPart::Text(text) => {
                            ast_parts.push(crate::ast::node::InterpolationPart::Text(text));
                        }
                        crate::lexer::InterpolationPart::Expression(expr_str) => {
                            // Parse the expression string
                            // For now, we'll create a simple parser for the embedded expression
                            let expr_lexer = crate::lexer::Lexer::new(&expr_str);
                            let expr_tokens = expr_lexer.tokenize();
                            let mut expr_parser = Parser::new(expr_tokens);
                            let expr = expr_parser.parse_expression()?;
                            ast_parts.push(crate::ast::node::InterpolationPart::Expression(
                                Box::new(expr),
                            ));
                        }
                    }
                }
                Ok(Expression::InterpolatedString {
                    parts: ast_parts,
                    position: token.position,
                })
            }
            TokenKind::True => Ok(Expression::BoolLiteral {
                value: true,
                position: token.position,
            }),
            TokenKind::False => Ok(Expression::BoolLiteral {
                value: false,
                position: token.position,
            }),
            TokenKind::Nil => Ok(Expression::NilLiteral {
                position: token.position,
            }),

            // Identifiers and variables
            TokenKind::Ident(name) => Ok(Expression::Identifier {
                name,
                position: token.position,
            }),
            TokenKind::InstanceVar(name) => Ok(Expression::InstanceVariable {
                name,
                position: token.position,
            }),
            TokenKind::ClassVar(name) => Ok(Expression::ClassVariable {
                name,
                position: token.position,
            }),
            TokenKind::GlobalVar(name) => Ok(Expression::GlobalVariable {
                name,
                position: token.position,
            }),

            // Symbol literal (:name)
            TokenKind::Colon => {
                let symbol_position = token.position;
                match self.advance().kind {
                    TokenKind::Ident(name) => Ok(Expression::Symbol {
                        value: name,
                        position: symbol_position,
                    }),
                    _ => Err(self.error_at_previous("Expected identifier after ':' for symbol")),
                }
            }

            // Grouped expression
            TokenKind::LParen => {
                let expr = self.parse_expression()?;
                self.expect(TokenKind::RParen, "Expected ')' after expression")?;
                Ok(Expression::Grouped {
                    expression: Box::new(expr),
                    position: token.position,
                })
            }

            // Array literal
            TokenKind::LBracket => {
                let mut elements = Vec::new();
                self.skip_whitespace();

                if !self.check(&[TokenKind::RBracket]) {
                    loop {
                        self.skip_whitespace();
                        elements.push(self.parse_expression()?);
                        self.skip_whitespace();

                        if !self.match_token(&[TokenKind::Comma]) {
                            break;
                        }
                    }
                }

                self.skip_whitespace();
                self.expect(TokenKind::RBracket, "Expected ']' after array elements")?;

                Ok(Expression::Array {
                    elements,
                    position: token.position,
                })
            }

            // Dictionary literal
            TokenKind::LBrace => {
                let mut entries = Vec::new();
                self.skip_whitespace();

                if !self.check(&[TokenKind::RBrace]) {
                    loop {
                        self.skip_whitespace();
                        let key = self.parse_expression()?;
                        self.skip_whitespace();

                        // Support both `:` and `=>` for hash syntax
                        if self.check(&[TokenKind::FatArrow]) {
                            self.advance(); // consume =>
                        } else {
                            self.expect(
                                TokenKind::Colon,
                                "Expected ':' or '=>' after dictionary key",
                            )?;
                        }

                        self.skip_whitespace();
                        let value = self.parse_expression()?;
                        entries.push((key, value));
                        self.skip_whitespace();

                        if !self.match_token(&[TokenKind::Comma]) {
                            break;
                        }
                    }
                }

                self.skip_whitespace();
                self.expect(TokenKind::RBrace, "Expected '}' after dictionary entries")?;

                Ok(Expression::Dictionary {
                    entries,
                    position: token.position,
                })
            }

            // Lambda literal: lambda do |params| ... end or lambda |params| ... end
            TokenKind::Lambda => {
                self.skip_whitespace();

                // Check for 'do' keyword (optional for compact syntax)
                let _has_do = self.match_token(&[TokenKind::Do]);
                self.skip_whitespace();

                // Parse parameters: |param1, param2, ...| or || for empty params
                let parameters = if self.match_token(&[TokenKind::LogicalOr]) {
                    // Empty parameter list: ||
                    Vec::new()
                } else if self.match_token(&[TokenKind::Pipe]) {
                    let mut params = Vec::new();
                    self.skip_whitespace();

                    if !self.check(&[TokenKind::Pipe]) {
                        loop {
                            self.skip_whitespace();
                            if let TokenKind::Ident(name) = self.peek().kind.clone() {
                                params.push(name);
                                self.advance();
                            } else {
                                return Err(self.error_at_current("Expected parameter name"));
                            }

                            self.skip_whitespace();
                            if !self.match_token(&[TokenKind::Comma]) {
                                break;
                            }
                        }
                    }

                    self.skip_whitespace();
                    self.expect(TokenKind::Pipe, "Expected '|' after lambda parameters")?;
                    params
                } else {
                    Vec::new()
                };

                // Parse body statements
                self.skip_whitespace();
                let mut body = Vec::new();

                while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                    self.skip_whitespace();
                    if self.check(&[TokenKind::End]) {
                        break;
                    }
                    body.push(self.parse_statement()?);
                    self.skip_whitespace();
                }

                self.expect(TokenKind::End, "Expected 'end' after lambda body")?;

                Ok(Expression::Lambda {
                    parameters,
                    body,
                    captured_vars: Some(Vec::new()), // Empty vec signals automatic capture
                    position: token.position,
                })
            }

            // Standalone block: do ... end
            TokenKind::Do => {
                self.skip_whitespace();

                // Parse optional parameters: |param1, param2, ...|
                let parameters = if self.match_token(&[TokenKind::Pipe]) {
                    let mut params = Vec::new();
                    self.skip_whitespace();

                    if !self.check(&[TokenKind::Pipe]) {
                        loop {
                            self.skip_whitespace();
                            if let TokenKind::Ident(name) = self.peek().kind.clone() {
                                params.push(name);
                                self.advance();
                            } else {
                                return Err(self.error_at_current("Expected parameter name"));
                            }

                            self.skip_whitespace();
                            if !self.match_token(&[TokenKind::Comma]) {
                                break;
                            }
                        }
                    }

                    self.skip_whitespace();
                    self.expect(TokenKind::Pipe, "Expected '|' after block parameters")?;
                    params
                } else {
                    Vec::new()
                };

                // Parse body statements
                self.skip_whitespace();
                let mut body = Vec::new();

                while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                    self.skip_whitespace();
                    if self.check(&[TokenKind::End]) {
                        break;
                    }
                    body.push(self.parse_statement()?);
                    self.skip_whitespace();
                }

                self.expect(TokenKind::End, "Expected 'end' after block body")?;

                // A standalone block is essentially a lambda with no parameters
                // that gets evaluated immediately (in this parser representation)
                Ok(Expression::Lambda {
                    parameters,
                    body,
                    captured_vars: Some(Vec::new()), // Empty vec signals automatic capture
                    position: token.position,
                })
            }

            // Super call: super() or super(args)
            TokenKind::Super => {
                self.skip_whitespace();
                let position = token.position;

                // Parse optional arguments
                let arguments = if self.check(&[TokenKind::LParen]) {
                    self.advance(); // consume (
                    let mut args = Vec::new();
                    self.skip_whitespace();

                    if !self.check(&[TokenKind::RParen]) {
                        loop {
                            self.skip_whitespace();
                            args.push(self.parse_expression()?);
                            self.skip_whitespace();

                            if !self.match_token(&[TokenKind::Comma]) {
                                break;
                            }
                        }
                    }

                    self.skip_whitespace();
                    self.expect(TokenKind::RParen, "Expected ')' after super arguments")?;
                    args
                } else {
                    // super without parentheses - no arguments
                    Vec::new()
                };

                Ok(Expression::Super {
                    arguments,
                    position,
                })
            }

            // Case expression: case value when pattern then expr ... end
            TokenKind::Case => self.parse_case_expression(token.position),

            // If expression: if cond then ... else ... end
            TokenKind::If => self.parse_if_expression(token.position),

            // Unless expression: unless cond then ... else ... end
            TokenKind::Unless => self.parse_unless_expression(token.position),

            _ => Err(self.error_at_previous(&format!("Unexpected token: {:?}", token.kind))),
        }
    }

    /// Parse a case expression (pattern matching in expression context)
    ///
    /// Supports two syntaxes:
    ///
    /// # Block syntax
    /// ```text
    /// case expression
    /// when pattern
    ///   expr
    /// when pattern
    ///   expr
    /// else
    ///   expr
    /// end
    /// ```
    ///
    /// # Inline syntax
    /// ```text
    /// case expression when pattern then expr when pattern then expr else expr end
    /// ```
    ///
    /// # Guard clauses
    /// ```text
    /// when pattern if guard_expr then expr
    /// ```
    pub(crate) fn parse_case_expression(
        &mut self,
        start_pos: crate::lexer::Position,
    ) -> Result<Expression, MetorexError> {
        self.skip_whitespace();

        // Parse the expression to match against
        let expression = Box::new(self.parse_expression()?);
        self.skip_whitespace();

        // Parse when clauses
        let mut cases = Vec::new();
        loop {
            self.skip_whitespace();
            if !self.match_token(&[TokenKind::When]) {
                break;
            }
            let when_pos = self.previous().position;
            self.skip_whitespace();

            // Parse the pattern using the shared pattern parser (may include comma-separated alternatives)
            let pattern = self.parse_case_pattern_with_alternatives()?;
            self.skip_whitespace();

            // Parse optional guard clause (if ...)
            let guard = if self.match_token(&[TokenKind::If]) {
                self.skip_whitespace();
                Some(self.parse_expression()?)
            } else {
                None
            };
            self.skip_whitespace();

            // Parse the body expression
            // Two syntaxes supported:
            // 1. Inline: when pattern then expression
            // 2. Block: when pattern newline expression(s)
            let body = if self.match_token(&[TokenKind::Then]) {
                // Inline syntax: parse expression after 'then'
                self.skip_whitespace();
                self.parse_expression()?
            } else {
                // Block syntax: parse expression after whitespace
                self.skip_whitespace();
                self.parse_expression()?
            };

            cases.push(ExprMatchCase {
                pattern,
                guard,
                body,
                position: when_pos,
            });

            self.skip_whitespace();
        }

        // Parse optional else clause
        let else_case = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            Some(Box::new(self.parse_expression()?))
        } else {
            None
        };

        self.skip_whitespace();
        self.expect(TokenKind::End, "Expected 'end' after case expression")?;

        Ok(Expression::Case {
            expression,
            cases,
            else_case,
            position: start_pos,
        })
    }

    /// Parse an if expression: `if cond [then] body [elsif cond body]* [else body] end`
    pub(crate) fn parse_if_expression(
        &mut self,
        start_pos: Position,
    ) -> Result<Expression, MetorexError> {
        self.skip_whitespace();
        let condition = Box::new(self.parse_expression()?);
        self.skip_whitespace();
        self.match_token(&[TokenKind::Then]); // optional `then`
        self.skip_whitespace();

        let mut then_branch = Vec::new();
        while !self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) && !self.is_at_end()
        {
            self.skip_whitespace();
            if self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) {
                break;
            }
            then_branch.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        let mut elsif_branches = Vec::new();
        while self.match_token(&[TokenKind::Elsif]) {
            let elsif_pos = self.previous().position;
            self.skip_whitespace();
            let elsif_cond = self.parse_expression()?;
            self.skip_whitespace();
            self.match_token(&[TokenKind::Then]);
            self.skip_whitespace();
            let mut elsif_body = Vec::new();
            while !self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End])
                && !self.is_at_end()
            {
                self.skip_whitespace();
                if self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) {
                    break;
                }
                elsif_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            elsif_branches.push(ElsifBranch {
                condition: elsif_cond,
                body: elsif_body,
                position: elsif_pos,
            });
        }

        let else_branch = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            let mut else_stmts = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_stmts.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(else_stmts)
        } else {
            None
        };

        self.skip_whitespace();
        self.expect(TokenKind::End, "Expected 'end' after if expression")?;

        Ok(Expression::If {
            condition,
            then_branch,
            elsif_branches,
            else_branch,
            position: start_pos,
        })
    }

    /// Parse an unless expression: `unless cond [then] body [else body] end`
    pub(crate) fn parse_unless_expression(
        &mut self,
        start_pos: Position,
    ) -> Result<Expression, MetorexError> {
        self.skip_whitespace();
        let condition = Box::new(self.parse_expression()?);
        self.skip_whitespace();
        self.match_token(&[TokenKind::Then]);
        self.skip_whitespace();

        let mut then_branch = Vec::new();
        while !self.check(&[TokenKind::Else, TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::Else, TokenKind::End]) {
                break;
            }
            then_branch.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        let else_branch = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            let mut else_stmts = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_stmts.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(else_stmts)
        } else {
            None
        };

        self.skip_whitespace();
        self.expect(TokenKind::End, "Expected 'end' after unless expression")?;

        Ok(Expression::Unless {
            condition,
            then_branch,
            else_branch,
            position: start_pos,
        })
    }
}

// Unary operator parsing
// Handles parsing of unary operations (+ and -)

use crate::ast::{Expression, UnaryOp};
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse unary operators (+, -, !)
    pub(crate) fn parse_unary(&mut self) -> Result<Expression, MetorexError> {
        if self.check(&[TokenKind::Plus, TokenKind::Minus, TokenKind::Bang]) {
            let op_token = self.advance();
            let op = match op_token.kind {
                TokenKind::Plus => UnaryOp::Plus,
                TokenKind::Minus => UnaryOp::Minus,
                TokenKind::Bang => UnaryOp::Not,
                _ => unreachable!(),
            };
            let operand = self.parse_unary()?;
            Ok(Expression::UnaryOp {
                op,
                operand: Box::new(operand),
                position: op_token.position,
            })
        } else {
            self.parse_call()
        }
    }
}

// Parser module for Metorex
// Converts a stream of tokens into an Abstract Syntax Tree (AST)

mod error;
mod expressions;
mod statements;
mod token_stream;

use crate::ast::Statement;
use crate::error::MetorexError;
use crate::lexer::{Token, TokenKind};

use error::ErrorHandler;
use token_stream::TokenStream;

/// The parser converts a token stream into an AST
pub struct Parser {
    /// Token stream for navigation
    stream: TokenStream,
    /// Error handler for reporting and recovery
    error_handler: ErrorHandler,
    /// Track if we're currently parsing inside a class body
    in_class_body: bool,
}

impl Parser {
    /// Create a new parser from a vector of tokens
    pub fn new(tokens: Vec<Token>) -> Self {
        Self {
            stream: TokenStream::new(tokens),
            error_handler: ErrorHandler::new(),
            in_class_body: false,
        }
    }

    /// Get the current token without consuming it
    fn peek(&self) -> &Token {
        self.stream.peek()
    }

    /// Peek ahead by offset tokens
    fn peek_ahead(&self, offset: usize) -> &Token {
        self.stream.peek_ahead(offset)
    }

    /// Get the previous token
    fn previous(&self) -> &Token {
        self.stream.previous()
    }

    /// Check if we're at the end of the token stream
    fn is_at_end(&self) -> bool {
        self.stream.is_at_end()
    }

    /// Advance to the next token and return the previous one
    fn advance(&mut self) -> Token {
        self.stream.advance()
    }

    /// Check if the current token matches any of the given kinds
    fn check(&self, kinds: &[TokenKind]) -> bool {
        self.stream.check(kinds)
    }

    /// Check if the current token matches a specific kind (handles complex matching)
    fn match_kind(&self, kind: &TokenKind) -> bool {
        self.stream.match_kind(kind)
    }

    /// Consume the current token if it matches any of the given kinds
    fn match_token(&mut self, kinds: &[TokenKind]) -> bool {
        self.stream.match_token(kinds)
    }

    /// Expect a specific token kind and consume it, or report an error
    fn expect(&mut self, kind: TokenKind, message: &str) -> Result<Token, MetorexError> {
        if self.match_kind(&kind) {
            Ok(self.advance())
        } else {
            let _token = self.peek();
            Err(self.error_at_current(message))
        }
    }

    /// Skip newlines and comments
    fn skip_whitespace(&mut self) {
        self.stream.skip_whitespace()
    }

    /// Get a reference to the token stream for advanced operations
    pub(crate) fn stream(&self) -> &TokenStream {
        &self.stream
    }

    /// Create an error at the current token
    fn error_at_current(&self, message: &str) -> MetorexError {
        self.error_handler.error_at_current(message, self.peek())
    }

    /// Create an error at the previous token
    fn error_at_previous(&self, message: &str) -> MetorexError {
        self.error_handler
            .error_at_previous(message, self.previous())
    }

    /// Report an error and enter panic mode
    fn report_error(&mut self, error: MetorexError) {
        self.error_handler.report_error(error);
    }

    /// Synchronize after an error (panic mode recovery)
    /// Skip tokens until we find a statement boundary
    fn synchronize(&mut self) {
        self.error_handler.start_synchronize();

        while !self.is_at_end() {
            // If we just passed a newline or semicolon, we're at a statement boundary
            if matches!(
                self.previous().kind,
                TokenKind::Newline | TokenKind::Semicolon
            ) {
                return;
            }

            // Also synchronize at the start of a new statement
            match self.peek().kind {
                TokenKind::Class
                | TokenKind::Def
                | TokenKind::If
                | TokenKind::While
                | TokenKind::Do
                | TokenKind::End => return,
                _ => {}
            }

            self.advance();
        }
    }

    /// Parse a complete program (list of statements)
    pub fn parse(&mut self) -> Result<Vec<Statement>, Vec<MetorexError>> {
        let mut statements = Vec::new();

        // Skip leading whitespace
        self.skip_whitespace();

        while !self.is_at_end() {
            // Skip any whitespace between statements
            self.skip_whitespace();

            if self.is_at_end() {
                break;
            }

            match self.parse_statement() {
                Ok(stmt) => statements.push(stmt),
                Err(err) => {
                    self.report_error(err);
                    self.synchronize();
                }
            }

            // Skip trailing whitespace after statement
            self.skip_whitespace();
        }

        if self.error_handler.has_errors() {
            Err(self.error_handler.errors().to_vec())
        } else {
            Ok(statements)
        }
    }
}

// Attribute accessor parsing (attr_reader, attr_writer, attr_accessor)

use crate::ast::Statement;
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse attr_reader statement: attr_reader :name1, :name2, ...
    pub(crate) fn parse_attr_reader(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::AttrReader, "Expected 'attr_reader'")?
            .position;
        self.skip_whitespace();

        let attributes = self.parse_symbol_list()?;

        Ok(Statement::AttrReader {
            attributes,
            position: start_pos,
        })
    }

    /// Parse attr_writer statement: attr_writer :name1, :name2, ...
    pub(crate) fn parse_attr_writer(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::AttrWriter, "Expected 'attr_writer'")?
            .position;
        self.skip_whitespace();

        let attributes = self.parse_symbol_list()?;

        Ok(Statement::AttrWriter {
            attributes,
            position: start_pos,
        })
    }

    /// Parse attr_accessor statement: attr_accessor :name1, :name2, ...
    pub(crate) fn parse_attr_accessor(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::AttrAccessor, "Expected 'attr_accessor'")?
            .position;
        self.skip_whitespace();

        let attributes = self.parse_symbol_list()?;

        Ok(Statement::AttrAccessor {
            attributes,
            position: start_pos,
        })
    }

    /// Parse a comma-separated list of symbols (:name1, :name2, ...)
    fn parse_symbol_list(&mut self) -> Result<Vec<String>, MetorexError> {
        let mut attributes = Vec::new();

        // Parse first symbol
        self.expect(TokenKind::Colon, "Expected ':' before attribute name")?;
        self.skip_whitespace();

        match self.advance().kind {
            TokenKind::Ident(name) => attributes.push(name),
            _ => return Err(self.error_at_previous("Expected attribute name after ':'")),
        }

        // Parse remaining symbols
        loop {
            self.skip_whitespace();

            if !self.match_token(&[TokenKind::Comma]) {
                break;
            }

            self.skip_whitespace();
            self.expect(TokenKind::Colon, "Expected ':' before attribute name")?;
            self.skip_whitespace();

            match self.advance().kind {
                TokenKind::Ident(name) => attributes.push(name),
                _ => return Err(self.error_at_previous("Expected attribute name after ':'")),
            }
        }

        Ok(attributes)
    }
}

// Class definition parsing

use crate::ast::Statement;
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse a class definition
    pub(crate) fn parse_class_def(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::Class, "Expected 'class'")?.position;
        self.skip_whitespace();

        let name = match self.advance().kind {
            TokenKind::Ident(name) => name,
            _ => return Err(self.error_at_previous("Expected class name")),
        };

        self.skip_whitespace();

        // Check for superclass
        let superclass = if self.match_token(&[TokenKind::Less]) {
            self.skip_whitespace();
            match self.advance().kind {
                TokenKind::Ident(parent) => Some(parent),
                _ => return Err(self.error_at_previous("Expected superclass name")),
            }
        } else {
            None
        };

        self.skip_whitespace();

        // Parse class body - set flag to indicate we're inside a class
        let was_in_class = self.in_class_body;
        self.in_class_body = true;

        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::End]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        // Restore the previous state
        self.in_class_body = was_in_class;

        self.expect(TokenKind::End, "Expected 'end' after class body")?;

        Ok(Statement::ClassDef {
            name,
            superclass,
            body,
            position: start_pos,
        })
    }

    /// Parse a module definition
    pub(crate) fn parse_module_def(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::Module, "Expected 'module'")?
            .position;
        self.skip_whitespace();

        let name = match self.advance().kind {
            TokenKind::Ident(name) => name,
            _ => return Err(self.error_at_previous("Expected module name")),
        };

        self.skip_whitespace();

        let was_in_class = self.in_class_body;
        self.in_class_body = true;

        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::End]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.in_class_body = was_in_class;
        self.expect(TokenKind::End, "Expected 'end' after module body")?;

        Ok(Statement::ModuleDef {
            name,
            body,
            position: start_pos,
        })
    }

    /// Parse an include statement
    pub(crate) fn parse_include(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::Include, "Expected 'include'")?
            .position;
        self.skip_whitespace();

        let module_name = match self.advance().kind {
            TokenKind::Ident(name) => name,
            _ => return Err(self.error_at_previous("Expected module name after 'include'")),
        };

        Ok(Statement::Include {
            module_name,
            position: start_pos,
        })
    }

    /// Parse an extend statement
    pub(crate) fn parse_extend(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::Extend, "Expected 'extend'")?
            .position;
        self.skip_whitespace();

        let module_name = match self.advance().kind {
            TokenKind::Ident(name) => name,
            _ => return Err(self.error_at_previous("Expected module name after 'extend'")),
        };

        Ok(Statement::Extend {
            module_name,
            position: start_pos,
        })
    }
}

// Control flow statement parsing (if, while, for, case)

use crate::ast::{ElsifBranch, Expression, MatchCase, MatchPattern, Statement};
use crate::error::{MetorexError, SourceLocation};
use crate::lexer::{Position, TokenKind};
use crate::parser::Parser;

impl Parser {
    /// Parse an if statement
    pub(crate) fn parse_if_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::If, "Expected 'if'")?.position;
        self.skip_whitespace();

        let condition = self.parse_expression()?;
        self.skip_whitespace();

        // Parse then branch
        let mut then_branch = Vec::new();
        while !self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) && !self.is_at_end()
        {
            self.skip_whitespace();
            if self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) {
                break;
            }
            then_branch.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        // Parse optional elsif branches
        let mut elsif_branches = Vec::new();
        while self.match_token(&[TokenKind::Elsif]) {
            let elsif_pos = self.previous().position;
            self.skip_whitespace();

            let elsif_condition = self.parse_expression()?;
            self.skip_whitespace();

            let mut elsif_body = Vec::new();
            while !self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End])
                && !self.is_at_end()
            {
                self.skip_whitespace();
                if self.check(&[TokenKind::Elsif, TokenKind::Else, TokenKind::End]) {
                    break;
                }
                elsif_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }

            elsif_branches.push(ElsifBranch {
                condition: elsif_condition,
                body: elsif_body,
                position: elsif_pos,
            });
        }

        // Parse optional else branch
        let else_branch = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            let mut else_stmts = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_stmts.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(else_stmts)
        } else {
            None
        };

        self.expect(TokenKind::End, "Expected 'end' after if statement")?;

        Ok(Statement::If {
            condition,
            then_branch,
            elsif_branches,
            else_branch,
            position: start_pos,
        })
    }

    /// Parse a while loop
    pub(crate) fn parse_while_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::While, "Expected 'while'")?.position;
        self.skip_whitespace();

        let condition = self.parse_expression()?;
        self.skip_whitespace();

        // Optionally consume 'do'
        self.match_token(&[TokenKind::Do]);
        self.skip_whitespace();

        // Parse loop body
        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::End]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.expect(TokenKind::End, "Expected 'end' after while loop")?;

        Ok(Statement::While {
            condition,
            body,
            position: start_pos,
        })
    }

    /// Parse a for loop
    pub(crate) fn parse_for_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::For, "Expected 'for'")?.position;
        self.skip_whitespace();

        // Parse the loop variable
        let variable = if let TokenKind::Ident(name) = &self.peek().kind {
            let var_name = name.clone();
            self.advance();
            var_name
        } else {
            return Err(MetorexError::syntax_error(
                "Expected identifier after 'for'",
                SourceLocation::new(
                    self.peek().position.line,
                    self.peek().position.column,
                    self.peek().position.offset,
                ),
            ));
        };

        self.skip_whitespace();

        // Expect 'in' keyword
        self.expect(TokenKind::In, "Expected 'in' after loop variable")?;
        self.skip_whitespace();

        // Parse the iterable expression
        let iterable = self.parse_expression()?;
        self.skip_whitespace();

        // Optionally consume 'do'
        self.match_token(&[TokenKind::Do]);
        self.skip_whitespace();

        // Parse loop body
        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::End]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.expect(TokenKind::End, "Expected 'end' after for loop")?;

        Ok(Statement::For {
            variable,
            iterable,
            body,
            position: start_pos,
        })
    }

    /// Parse a break statement
    pub(crate) fn parse_break_statement(&mut self) -> Result<Statement, MetorexError> {
        let pos = self.expect(TokenKind::Break, "Expected 'break'")?.position;
        Ok(Statement::Break { position: pos })
    }

    /// Parse a continue statement
    pub(crate) fn parse_continue_statement(&mut self) -> Result<Statement, MetorexError> {
        let pos = self
            .expect(TokenKind::Continue, "Expected 'continue'")?
            .position;
        Ok(Statement::Continue { position: pos })
    }

    /// Parse an unless statement
    pub(crate) fn parse_unless_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self
            .expect(TokenKind::Unless, "Expected 'unless'")?
            .position;
        self.skip_whitespace();

        let condition = self.parse_expression()?;
        self.skip_whitespace();

        // Parse then branch
        let mut then_branch = Vec::new();
        while !self.check(&[TokenKind::Else, TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::Else, TokenKind::End]) {
                break;
            }
            then_branch.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        // Parse optional else branch
        let else_branch = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            let mut else_stmts = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_stmts.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(else_stmts)
        } else {
            None
        };

        self.expect(TokenKind::End, "Expected 'end' after unless statement")?;

        Ok(Statement::Unless {
            condition,
            then_branch,
            else_branch,
            position: start_pos,
        })
    }

    /// Parse a return statement
    pub(crate) fn parse_return_statement(&mut self) -> Result<Statement, MetorexError> {
        let pos = self
            .expect(TokenKind::Return, "Expected 'return'")?
            .position;
        self.skip_whitespace();

        // Check if there's a return value
        let value = if self.check(&[TokenKind::Newline, TokenKind::Semicolon, TokenKind::EOF])
            || self.is_at_end()
        {
            None
        } else {
            Some(self.parse_expression()?)
        };

        Ok(Statement::Return {
            value,
            position: pos,
        })
    }

    /// Parse a case statement (Ruby-style case/when)
    /// Syntax:
    ///   case expression
    ///   when pattern1
    ///     body1
    ///   when pattern2
    ///     body2
    ///   else
    ///     else_body
    ///   end
    pub(crate) fn parse_case_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::Case, "Expected 'case'")?.position;
        self.skip_whitespace();

        // Parse the expression to match against
        let expression = self.parse_expression()?;
        self.skip_whitespace();

        // Detect whether this is case/when or case/in
        if self.check(&[TokenKind::In]) {
            return self.parse_case_in_body(expression, start_pos);
        }

        // Parse when clauses
        let mut cases = Vec::new();
        loop {
            self.skip_whitespace(); // Skip whitespace before checking for when
            if !self.match_token(&[TokenKind::When]) {
                break;
            }
            let when_pos = self.previous().position;
            self.skip_whitespace();

            // Parse the pattern (may include comma-separated alternatives)
            let pattern = self.parse_case_pattern_with_alternatives()?;
            self.skip_whitespace();

            // Consume optional 'then' keyword (allows inline: when 1, 2 then body)
            self.match_token(&[TokenKind::Then]);
            self.skip_whitespace();

            // Parse optional guard clause (if ...)
            let guard = if self.match_token(&[TokenKind::If]) {
                self.skip_whitespace();
                Some(self.parse_expression()?)
            } else {
                None
            };
            self.skip_whitespace();

            // Parse the body
            let mut body = Vec::new();
            while !self.check(&[TokenKind::When, TokenKind::Else, TokenKind::End])
                && !self.is_at_end()
            {
                self.skip_whitespace();
                if self.check(&[TokenKind::When, TokenKind::Else, TokenKind::End]) {
                    break;
                }
                body.push(self.parse_statement()?);
                self.skip_whitespace();
            }

            cases.push(MatchCase {
                pattern,
                guard,
                body,
                position: when_pos,
            });
        }

        // Parse optional else clause (as a wildcard pattern)
        self.skip_whitespace(); // Skip whitespace before checking for else
        if self.match_token(&[TokenKind::Else]) {
            let else_pos = self.previous().position;
            self.skip_whitespace();

            let mut else_body = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }

            // Add an else clause as a wildcard case
            cases.push(MatchCase {
                pattern: MatchPattern::Wildcard,
                guard: None,
                body: else_body,
                position: else_pos,
            });
        }

        self.skip_whitespace(); // Skip whitespace before end
        self.expect(TokenKind::End, "Expected 'end' after case statement")?;

        Ok(Statement::Match {
            expression,
            cases,
            position: start_pos,
        })
    }

    /// Parse the body of a `case/in` statement (Ruby 2.7+ pattern matching).
    /// Called after `case expr` has been consumed and `in` is the next token.
    fn parse_case_in_body(
        &mut self,
        expression: Expression,
        start_pos: Position,
    ) -> Result<Statement, MetorexError> {
        let mut cases = Vec::new();

        loop {
            self.skip_whitespace();
            if !self.match_token(&[TokenKind::In]) {
                break;
            }
            let in_pos = self.previous().position;
            self.skip_whitespace();

            // Parse the pattern (supports `=> name` binding)
            let pattern = self.parse_case_in_pattern()?;
            self.skip_whitespace();

            // Parse optional guard clause (if ...)
            let guard = if self.match_token(&[TokenKind::If]) {
                self.skip_whitespace();
                Some(self.parse_expression()?)
            } else {
                None
            };
            self.skip_whitespace();

            // Parse the body
            let mut body = Vec::new();
            while !self.check(&[TokenKind::In, TokenKind::Else, TokenKind::End])
                && !self.is_at_end()
            {
                self.skip_whitespace();
                if self.check(&[TokenKind::In, TokenKind::Else, TokenKind::End]) {
                    break;
                }
                body.push(self.parse_statement()?);
                self.skip_whitespace();
            }

            cases.push(MatchCase {
                pattern,
                guard,
                body,
                position: in_pos,
            });
        }

        // Parse optional else clause (as a wildcard pattern)
        self.skip_whitespace();
        if self.match_token(&[TokenKind::Else]) {
            let else_pos = self.previous().position;
            self.skip_whitespace();

            let mut else_body = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                else_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }

            cases.push(MatchCase {
                pattern: MatchPattern::Wildcard,
                guard: None,
                body: else_body,
                position: else_pos,
            });
        }

        self.skip_whitespace();
        self.expect(TokenKind::End, "Expected 'end' after case/in statement")?;

        Ok(Statement::CaseIn {
            expression,
            cases,
            position: start_pos,
        })
    }

    /// Parse a single pattern for `case/in`, supporting `pattern => name` binding
    /// at the top level and inside array patterns.
    fn parse_case_in_pattern(&mut self) -> Result<MatchPattern, MetorexError> {
        self.parse_case_in_pattern_inner()
    }

    /// Recursive inner parser for `case/in` patterns with `=> name` bind support.
    fn parse_case_in_pattern_inner(&mut self) -> Result<MatchPattern, MetorexError> {
        let token = self.peek().clone();

        let inner = match &token.kind {
            // Array pattern — parse each element with bind support
            TokenKind::LBracket => {
                self.advance();
                self.skip_whitespace();
                let mut patterns = Vec::new();
                while !self.check(&[TokenKind::RBracket]) && !self.is_at_end() {
                    self.skip_whitespace();
                    if self.match_token(&[TokenKind::DotDotDot]) {
                        self.skip_whitespace();
                        if let TokenKind::Ident(name) = &self.peek().kind {
                            let rest_name = name.clone();
                            self.advance();
                            patterns.push(MatchPattern::Rest(rest_name));
                        } else {
                            return Err(MetorexError::syntax_error(
                                "Expected identifier after ... in array pattern".to_string(),
                                SourceLocation::new(
                                    self.peek().position.line,
                                    self.peek().position.column,
                                    self.peek().position.offset,
                                ),
                            ));
                        }
                    } else {
                        patterns.push(self.parse_case_in_pattern_inner()?);
                    }
                    self.skip_whitespace();
                    if !self.check(&[TokenKind::RBracket]) {
                        self.expect(TokenKind::Comma, "Expected ',' or ']' in array pattern")?;
                        self.skip_whitespace();
                    }
                }
                self.expect(TokenKind::RBracket, "Expected ']' after array pattern")?;
                MatchPattern::Array(patterns)
            }
            // For all other patterns, delegate to the base parser
            _ => self.parse_case_pattern()?,
        };

        self.skip_whitespace();

        // Check for `=> name` binding
        if self.match_token(&[TokenKind::FatArrow]) {
            self.skip_whitespace();
            let name = if let TokenKind::Ident(n) = &self.peek().kind {
                let n = n.clone();
                self.advance();
                n
            } else {
                return Err(self.error_at_current("Expected identifier after '=>' in pattern"));
            };
            Ok(MatchPattern::Bind {
                pattern: Box::new(inner),
                name,
            })
        } else {
            Ok(inner)
        }
    }

    /// Parse a pattern for a case statement
    /// Supports:
    /// - Literal patterns (integers, strings, booleans, nil)
    /// - Wildcard pattern (_)
    /// - Variable binding pattern (identifier)
    /// - Array destructuring ([a, b, c] or [first, ...rest])
    /// - Object destructuring ({x, y} or {x: a, y: b})
    ///
    /// This method is public within the parser module so it can be used
    /// by both statement parsing (case statements) and expression parsing (case expressions)
    /// Parse a pattern that may include comma-separated alternatives
    /// Returns a MatchPattern::Multiple if multiple patterns are found, otherwise a single pattern
    pub(in crate::parser) fn parse_case_pattern_with_alternatives(
        &mut self,
    ) -> Result<MatchPattern, MetorexError> {
        // Parse the first pattern
        let first_pattern = self.parse_case_pattern()?;
        self.skip_whitespace();

        // Check if there's a comma indicating multiple patterns
        if !self.check(&[TokenKind::Comma]) {
            // Single pattern, return as-is
            return Ok(first_pattern);
        }

        // Multiple patterns: collect all comma-separated patterns
        let mut patterns = vec![first_pattern];

        while self.match_token(&[TokenKind::Comma]) {
            self.skip_whitespace();

            // Check if we've hit a terminal token (then, if, newline context)
            // This prevents consuming commas from other constructs
            if self.check(&[
                TokenKind::Then,
                TokenKind::If,
                TokenKind::When,
                TokenKind::Else,
                TokenKind::End,
            ]) {
                break;
            }

            patterns.push(self.parse_case_pattern()?);
            self.skip_whitespace();
        }

        // If we only collected one pattern, return it directly
        if patterns.len() == 1 {
            Ok(patterns.into_iter().next().unwrap())
        } else {
            Ok(MatchPattern::Multiple(patterns))
        }
    }

    /// Parse a single case pattern (internal helper)
    pub(in crate::parser) fn parse_case_pattern(&mut self) -> Result<MatchPattern, MetorexError> {
        let token = self.peek().clone();

        match &token.kind {
            // Array pattern
            TokenKind::LBracket => {
                self.advance(); // consume '['
                self.skip_whitespace();

                let mut patterns = Vec::new();

                // Parse patterns inside the array
                while !self.check(&[TokenKind::RBracket]) && !self.is_at_end() {
                    self.skip_whitespace();

                    // Check for rest pattern (...)
                    if self.match_token(&[TokenKind::DotDotDot]) {
                        self.skip_whitespace();

                        // Next token should be an identifier for the rest binding
                        if let TokenKind::Ident(name) = &self.peek().kind {
                            let rest_name = name.clone();
                            self.advance();
                            patterns.push(MatchPattern::Rest(rest_name));
                        } else {
                            return Err(MetorexError::syntax_error(
                                "Expected identifier after ... in array pattern".to_string(),
                                SourceLocation::new(
                                    self.peek().position.line,
                                    self.peek().position.column,
                                    self.peek().position.offset,
                                ),
                            ));
                        }
                    } else {
                        // Parse a regular pattern
                        patterns.push(self.parse_case_pattern()?);
                    }

                    self.skip_whitespace();

                    // Check for comma
                    if !self.check(&[TokenKind::RBracket]) {
                        self.expect(TokenKind::Comma, "Expected ',' or ']' in array pattern")?;
                        self.skip_whitespace();
                    }
                }

                self.expect(TokenKind::RBracket, "Expected ']' after array pattern")?;
                Ok(MatchPattern::Array(patterns))
            }

            // Object/Dictionary pattern
            TokenKind::LBrace => {
                self.advance(); // consume '{'
                self.skip_whitespace();

                let mut key_patterns = Vec::new();

                // Parse key-pattern pairs inside the object
                while !self.check(&[TokenKind::RBrace]) && !self.is_at_end() {
                    self.skip_whitespace();

                    // Expect an identifier as the key
                    let key = if let TokenKind::Ident(name) = &self.peek().kind {
                        let k = name.clone();
                        self.advance();
                        k
                    } else if let TokenKind::String(s) = &self.peek().kind {
                        let k = s.clone();
                        self.advance();
                        k
                    } else {
                        return Err(MetorexError::syntax_error(
                            "Expected identifier or string key in object pattern".to_string(),
                            SourceLocation::new(
                                self.peek().position.line,
                                self.peek().position.column,
                                self.peek().position.offset,
                            ),
                        ));
                    };

                    self.skip_whitespace();

                    // Check if there's a colon for explicit pattern (e.g., {x: a, y: b})
                    let pattern = if self.match_token(&[TokenKind::Colon]) {
                        self.skip_whitespace();
                        self.parse_case_pattern()?
                    } else {
                        // Shorthand: {x, y} means {x: x, y: y}
                        MatchPattern::Identifier(key.clone())
                    };

                    key_patterns.push((key, pattern));

                    self.skip_whitespace();

                    // Check for comma
                    if !self.check(&[TokenKind::RBrace]) {
                        self.expect(TokenKind::Comma, "Expected ',' or '}' in object pattern")?;
                        self.skip_whitespace();
                    }
                }

                self.expect(TokenKind::RBrace, "Expected '}' after object pattern")?;
                Ok(MatchPattern::Object(key_patterns))
            }

            // Literal patterns (may be followed by .. or ... to form a range pattern)
            TokenKind::Int(n) => {
                let value = *n;
                self.advance();
                let start = MatchPattern::IntLiteral(value);
                self.parse_range_pattern_suffix(start)
            }
            TokenKind::Float(f) => {
                let value = *f;
                self.advance();
                let start = MatchPattern::FloatLiteral(value);
                self.parse_range_pattern_suffix(start)
            }
            TokenKind::String(s) => {
                let value = s.clone();
                self.advance();
                let start = MatchPattern::StringLiteral(value);
                self.parse_range_pattern_suffix(start)
            }
            TokenKind::True => {
                self.advance();
                Ok(MatchPattern::BoolLiteral(true))
            }
            TokenKind::False => {
                self.advance();
                Ok(MatchPattern::BoolLiteral(false))
            }
            TokenKind::Nil => {
                self.advance();
                Ok(MatchPattern::NilLiteral)
            }
            // Wildcard pattern
            TokenKind::Ident(name) if name == "_" => {
                self.advance();
                Ok(MatchPattern::Wildcard)
            }
            // Type pattern (capitalized identifiers like Integer, String, Hash, Array)
            TokenKind::Ident(name) if name.chars().next().is_some_and(|c| c.is_uppercase()) => {
                let type_name = name.clone();
                self.advance();
                Ok(MatchPattern::Type(type_name))
            }
            // Variable binding pattern
            TokenKind::Ident(name) => {
                let var_name = name.clone();
                self.advance();
                Ok(MatchPattern::Identifier(var_name))
            }
            _ => Err(MetorexError::syntax_error(
                format!("Expected pattern, found {:?}", token.kind),
                SourceLocation::new(
                    token.position.line,
                    token.position.column,
                    token.position.offset,
                ),
            )),
        }
    }

    /// If `..` or `...` follows a literal pattern, wrap it in a Range pattern.
    fn parse_range_pattern_suffix(
        &mut self,
        start: MatchPattern,
    ) -> Result<MatchPattern, MetorexError> {
        if self.match_token(&[TokenKind::DotDotDot]) {
            let end = self.parse_case_pattern()?;
            Ok(MatchPattern::Range {
                start: Box::new(start),
                end: Box::new(end),
                exclusive: true,
            })
        } else if self.match_token(&[TokenKind::DotDot]) {
            let end = self.parse_case_pattern()?;
            Ok(MatchPattern::Range {
                start: Box::new(start),
                end: Box::new(end),
                exclusive: false,
            })
        } else {
            Ok(start)
        }
    }
}

// Exception handling statement parsing (begin/rescue/raise)

use crate::ast::{RescueClause, Statement};
use crate::error::{MetorexError, SourceLocation};
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse a begin...rescue...else...ensure...end statement
    pub(crate) fn parse_begin_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::Begin, "Expected 'begin'")?.position;
        self.skip_whitespace();

        // Parse the main body
        let mut body = Vec::new();
        while !self.check(&[
            TokenKind::Rescue,
            TokenKind::Else,
            TokenKind::Ensure,
            TokenKind::End,
        ]) && !self.is_at_end()
        {
            self.skip_whitespace();
            if self.check(&[
                TokenKind::Rescue,
                TokenKind::Else,
                TokenKind::Ensure,
                TokenKind::End,
            ]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        // Parse rescue clauses
        let mut rescue_clauses = Vec::new();
        while self.match_token(&[TokenKind::Rescue]) {
            rescue_clauses.push(self.parse_rescue_clause()?);
            self.skip_whitespace();
        }

        // Parse optional else clause
        let else_clause = if self.match_token(&[TokenKind::Else]) {
            self.skip_whitespace();
            let mut else_body = Vec::new();
            while !self.check(&[TokenKind::Ensure, TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::Ensure, TokenKind::End]) {
                    break;
                }
                else_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(else_body)
        } else {
            None
        };

        // Parse optional ensure clause
        let ensure_block = if self.match_token(&[TokenKind::Ensure]) {
            self.skip_whitespace();
            let mut ensure_body = Vec::new();
            while !self.check(&[TokenKind::End]) && !self.is_at_end() {
                self.skip_whitespace();
                if self.check(&[TokenKind::End]) {
                    break;
                }
                ensure_body.push(self.parse_statement()?);
                self.skip_whitespace();
            }
            Some(ensure_body)
        } else {
            None
        };

        self.expect(TokenKind::End, "Expected 'end' after begin block")?;

        Ok(Statement::Begin {
            body,
            rescue_clauses,
            else_clause,
            ensure_block,
            position: start_pos,
        })
    }

    /// Parse a rescue clause
    pub(crate) fn parse_rescue_clause(&mut self) -> Result<RescueClause, MetorexError> {
        let start_pos = self.previous().position;

        // Don't skip whitespace yet - we need to check if there's a newline after rescue
        // If there's a newline, then no exception types are specified
        let has_newline = self.check(&[TokenKind::Newline]);

        self.skip_whitespace();

        // Parse exception types (comma-separated identifiers)
        let mut exception_types = Vec::new();
        let mut variable_name = None;

        // Check if there's an exception type specified
        // An exception type is present if:
        // 1. There's no newline after rescue
        // 2. We see an identifier that's NOT followed by '=' (which would be an assignment)
        if !has_newline && self.check(&[TokenKind::Ident(String::new())]) {
            // Peek ahead to see if this looks like an exception type or an assignment
            // If the next token after the identifier is '=', it's an assignment, not an exception type
            let current_pos = self.stream().current_position();
            let next_is_assignment = if let Some(next) = self.stream().tokens().get(current_pos + 1)
            {
                matches!(next.kind, TokenKind::Equal)
            } else {
                false
            };

            if !next_is_assignment {
                // Parse exception types
                while let TokenKind::Ident(name) = &self.peek().kind {
                    exception_types.push(name.clone());
                    self.advance();
                    self.skip_whitespace();

                    // Check for comma (multiple exception types)
                    if !self.match_token(&[TokenKind::Comma]) {
                        break;
                    }
                    self.skip_whitespace();
                }
            }
        }

        // Check for variable binding (=> var)
        if self.match_token(&[TokenKind::FatArrow]) {
            self.skip_whitespace();
            if let TokenKind::Ident(name) = &self.peek().kind {
                variable_name = Some(name.clone());
                self.advance();
                self.skip_whitespace();
            } else {
                return Err(MetorexError::syntax_error(
                    "Expected variable name after '=>'",
                    SourceLocation::new(
                        self.peek().position.line,
                        self.peek().position.column,
                        self.peek().position.offset,
                    ),
                ));
            }
        }

        // Parse rescue body
        let mut body = Vec::new();
        while !self.check(&[
            TokenKind::Rescue,
            TokenKind::Else,
            TokenKind::Ensure,
            TokenKind::End,
        ]) && !self.is_at_end()
        {
            self.skip_whitespace();
            if self.check(&[
                TokenKind::Rescue,
                TokenKind::Else,
                TokenKind::Ensure,
                TokenKind::End,
            ]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        Ok(RescueClause {
            exception_types,
            variable_name,
            body,
            position: start_pos,
        })
    }

    /// Parse a raise statement
    pub(crate) fn parse_raise_statement(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::Raise, "Expected 'raise'")?.position;
        self.skip_whitespace();

        // Check if there's an exception expression
        // If the next token is a newline, semicolon, or end, it's a bare raise
        let exception = if self.check(&[TokenKind::Newline, TokenKind::Semicolon, TokenKind::End])
            || self.is_at_end()
        {
            None
        } else {
            Some(self.parse_expression()?)
        };

        Ok(Statement::Raise {
            exception,
            position: start_pos,
        })
    }
}

// Function definition parsing

use crate::ast::{Parameter, Statement};
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse a function definition
    pub(crate) fn parse_function_def(&mut self) -> Result<Statement, MetorexError> {
        let start_pos = self.expect(TokenKind::Def, "Expected 'def'")?.position;
        self.skip_whitespace();

        let name = match self.advance().kind {
            TokenKind::Ident(name) => name,
            // Operator method names
            TokenKind::Plus => "+".to_string(),
            TokenKind::Minus => "-".to_string(),
            TokenKind::Star => "*".to_string(),
            TokenKind::Slash => "/".to_string(),
            TokenKind::Percent => "%".to_string(),
            TokenKind::EqualEqual => "==".to_string(),
            TokenKind::BangEqual => "!=".to_string(),
            TokenKind::Less => "<".to_string(),
            TokenKind::Greater => ">".to_string(),
            TokenKind::LessEqual => "<=".to_string(),
            TokenKind::GreaterEqual => ">=".to_string(),
            TokenKind::Pipe => "|".to_string(),
            TokenKind::Ampersand => "&".to_string(),
            // [] and []= operator method names
            TokenKind::LBracket => {
                self.expect(TokenKind::RBracket, "Expected ']' after '[' in method name")?;
                if self.match_token(&[TokenKind::Equal]) {
                    "[]=".to_string()
                } else {
                    "[]".to_string()
                }
            }
            _ => return Err(self.error_at_previous("Expected function name")),
        };

        self.skip_whitespace();

        // Parse parameters (optional parentheses)
        let parameters = if self.match_token(&[TokenKind::LParen]) {
            self.parse_parameters()?
        } else {
            Vec::new()
        };

        self.skip_whitespace();

        // Parse function body
        let mut body = Vec::new();
        while !self.check(&[TokenKind::End]) && !self.is_at_end() {
            self.skip_whitespace();
            if self.check(&[TokenKind::End]) {
                break;
            }
            body.push(self.parse_statement()?);
            self.skip_whitespace();
        }

        self.expect(TokenKind::End, "Expected 'end' after function body")?;

        // Return MethodDef if we're inside a class, otherwise FunctionDef
        if self.in_class_body {
            Ok(Statement::MethodDef {
                name,
                parameters,
                body,
                position: start_pos,
            })
        } else {
            Ok(Statement::FunctionDef {
                name,
                parameters,
                body,
                position: start_pos,
            })
        }
    }

    /// Parse function parameters
    pub(crate) fn parse_parameters(&mut self) -> Result<Vec<Parameter>, MetorexError> {
        let mut params = Vec::new();
        self.skip_whitespace();

        if self.check(&[TokenKind::RParen]) {
            self.advance();
            return Ok(params);
        }

        loop {
            self.skip_whitespace();

            let param_pos = self.peek().position;

            // Check for block parameter (&block)
            if self.match_token(&[TokenKind::Ampersand]) {
                let name = match self.advance().kind {
                    TokenKind::Ident(name) => name,
                    _ => return Err(self.error_at_previous("Expected parameter name after '&'")),
                };
                params.push(Parameter::block(name, param_pos));
            }
            // Check for variadic parameter (*args)
            else if self.match_token(&[TokenKind::Star]) {
                let name = match self.advance().kind {
                    TokenKind::Ident(name) => name,
                    _ => return Err(self.error_at_previous("Expected parameter name after '*'")),
                };
                params.push(Parameter::variadic(name, param_pos));
            } else {
                let name = match self.advance().kind {
                    TokenKind::Ident(name) => name,
                    _ => return Err(self.error_at_previous("Expected parameter name")),
                };

                // Check for `name:` or `name: default` (named keyword argument)
                if self.match_token(&[TokenKind::Colon]) {
                    // `name:` alone means required keyword arg (no default)
                    // `name: expr` means optional keyword arg with default
                    let default =
                        if self.check(&[TokenKind::Comma, TokenKind::RParen, TokenKind::Newline]) {
                            None
                        } else {
                            Some(self.parse_expression()?)
                        };
                    params.push(Parameter::named_keyword(name, default, param_pos));
                // Check for positional default value
                } else if self.match_token(&[TokenKind::Equal]) {
                    let default = self.parse_expression()?;
                    params.push(Parameter::with_default(name, default, param_pos));
                } else {
                    params.push(Parameter::simple(name, param_pos));
                }
            }

            self.skip_whitespace();

            if !self.match_token(&[TokenKind::Comma]) {
                break;
            }
        }

        self.skip_whitespace();
        self.expect(TokenKind::RParen, "Expected ')' after parameters")?;

        Ok(params)
    }
}

// Statement parsing module
// Handles parsing of all statement types

mod attributes;
mod class;
mod control_flow;
mod exception;
mod function;

use crate::ast::{BinaryOp, Expression, Statement};
use crate::error::MetorexError;
use crate::lexer::TokenKind;
use crate::parser::Parser;

impl Parser {
    /// Parse a single statement
    pub(crate) fn parse_statement(&mut self) -> Result<Statement, MetorexError> {
        // Skip leading whitespace
        self.skip_whitespace();

        let token = self.peek().clone();
        match &token.kind {
            TokenKind::Class => self.parse_class_def(),
            TokenKind::Def => self.parse_function_def(),
            TokenKind::If => self.parse_if_statement(),
            TokenKind::Unless => self.parse_unless_statement(),
            TokenKind::While => self.parse_while_statement(),
            TokenKind::For => self.parse_for_statement(),
            TokenKind::Case => self.parse_case_statement(),
            TokenKind::Begin => self.parse_begin_statement(),
            TokenKind::Raise => self.parse_raise_statement(),
            TokenKind::Break => self.parse_break_statement(),
            TokenKind::Continue => self.parse_continue_statement(),
            TokenKind::Return => self.parse_return_statement(),
            TokenKind::AttrReader => self.parse_attr_reader(),
            TokenKind::AttrWriter => self.parse_attr_writer(),
            TokenKind::AttrAccessor => self.parse_attr_accessor(),
            TokenKind::Module => self.parse_module_def(),
            TokenKind::Include => self.parse_include(),
            TokenKind::Extend => self.parse_extend(),
            _ => {
                // Try to parse as an expression or assignment (including arrow lambdas)
                let expr = self.parse_expression_with_lambda()?;

                // Check if this is an assignment
                if self.check(&[
                    TokenKind::Equal,
                    TokenKind::PlusEqual,
                    TokenKind::MinusEqual,
                    TokenKind::StarEqual,
                    TokenKind::SlashEqual,
                ]) {
                    let op_token = self.advance();
                    let value = self.parse_expression_with_lambda()?;

                    // Convert compound assignment to regular assignment with binary op
                    let final_value = match op_token.kind {
                        TokenKind::PlusEqual => Expression::BinaryOp {
                            op: BinaryOp::Add,
                            left: Box::new(expr.clone()),
                            right: Box::new(value),
                            position: op_token.position,
                        },
                        TokenKind::MinusEqual => Expression::BinaryOp {
                            op: BinaryOp::Subtract,
                            left: Box::new(expr.clone()),
                            right: Box::new(value),
                            position: op_token.position,
                        },
                        TokenKind::StarEqual => Expression::BinaryOp {
                            op: BinaryOp::Multiply,
                            left: Box::new(expr.clone()),
                            right: Box::new(value),
                            position: op_token.position,
                        },
                        TokenKind::SlashEqual => Expression::BinaryOp {
                            op: BinaryOp::Divide,
                            left: Box::new(expr.clone()),
                            right: Box::new(value),
                            position: op_token.position,
                        },
                        TokenKind::Equal => value,
                        _ => unreachable!(),
                    };

                    Ok(Statement::Assignment {
                        target: expr,
                        value: final_value,
                        position: token.position,
                    })
                } else {
                    // It's just an expression statement
                    Ok(Statement::Expression {
                        expression: expr,
                        position: token.position,
                    })
                }
            }
        }
    }
}

// Token stream management for the parser
// Handles token navigation, matching, and whitespace handling

use crate::lexer::{Token, TokenKind};

/// Encapsulates token navigation state and operations
pub struct TokenStream {
    /// The tokens to parse
    tokens: Vec<Token>,
    /// Current position in the token stream
    current: usize,
}

impl TokenStream {
    /// Create a new token stream from a vector of tokens
    pub fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, current: 0 }
    }

    /// Get the current token without consuming it
    pub fn peek(&self) -> &Token {
        self.tokens.get(self.current).unwrap_or_else(|| {
            // If we're past the end, return the last token (should be EOF)
            self.tokens.last().unwrap()
        })
    }

    /// Get the token at an offset from the current position
    #[allow(dead_code)]
    pub fn peek_ahead(&self, offset: usize) -> &Token {
        self.tokens
            .get(self.current + offset)
            .unwrap_or_else(|| self.tokens.last().unwrap())
    }

    /// Get the previous token
    pub fn previous(&self) -> &Token {
        if self.current > 0 {
            &self.tokens[self.current - 1]
        } else {
            &self.tokens[0]
        }
    }

    /// Check if we're at the end of the token stream
    pub fn is_at_end(&self) -> bool {
        matches!(self.peek().kind, TokenKind::EOF)
    }

    /// Advance to the next token and return the previous one
    pub fn advance(&mut self) -> Token {
        if !self.is_at_end() {
            self.current += 1;
        }
        self.previous().clone()
    }

    /// Check if the current token matches any of the given kinds
    pub fn check(&self, kinds: &[TokenKind]) -> bool {
        if self.is_at_end() {
            return false;
        }
        kinds.iter().any(|kind| self.match_kind(kind))
    }

    /// Check if the current token matches a specific kind (handles complex matching)
    pub fn match_kind(&self, kind: &TokenKind) -> bool {
        let current = &self.peek().kind;
        match (kind, current) {
            (TokenKind::Ident(_), TokenKind::Ident(_)) => true,
            (TokenKind::Int(_), TokenKind::Int(_)) => true,
            (TokenKind::Float(_), TokenKind::Float(_)) => true,
            (TokenKind::String(_), TokenKind::String(_)) => true,
            (TokenKind::InterpolatedString(_), TokenKind::InterpolatedString(_)) => true,
            (TokenKind::InstanceVar(_), TokenKind::InstanceVar(_)) => true,
            (TokenKind::ClassVar(_), TokenKind::ClassVar(_)) => true,
            (TokenKind::Comment(_), TokenKind::Comment(_)) => true,
            _ => kind == current,
        }
    }

    /// Consume the current token if it matches any of the given kinds
    pub fn match_token(&mut self, kinds: &[TokenKind]) -> bool {
        if self.check(kinds) {
            self.advance();
            true
        } else {
            false
        }
    }

    /// Skip any newline tokens
    #[allow(dead_code)]
    pub fn skip_newlines(&mut self) {
        while self.match_token(&[TokenKind::Newline]) {
            // Keep consuming newlines
        }
    }

    /// Skip any comment tokens
    #[allow(dead_code)]
    pub fn skip_comments(&mut self) {
        while matches!(self.peek().kind, TokenKind::Comment(_)) {
            self.advance();
        }
    }

    /// Skip newlines and comments
    pub fn skip_whitespace(&mut self) {
        while let TokenKind::Newline | TokenKind::Comment(_) = &self.peek().kind {
            self.advance();
        }
    }

    /// Get direct access to tokens for advanced operations (e.g., lookahead)
    pub fn tokens(&self) -> &[Token] {
        &self.tokens
    }

    /// Get the current position in the token stream
    pub fn current_position(&self) -> usize {
        self.current
    }

    /// Restore the position in the token stream (for backtracking)
    pub fn restore_position(&mut self, position: usize) {
        self.current = position;
    }
}

// Metorex REPL
// Interactive Read-Eval-Print Loop for Metorex

use crate::error::MetorexError;
use crate::lexer::Lexer;
use crate::object::Object;
use crate::parser::Parser;
use crate::vm::VirtualMachine;
use rustyline::error::ReadlineError;
use rustyline::{DefaultEditor, Result as RustylineResult};

const PROMPT: &str = ">> ";
const CONTINUATION_PROMPT: &str = ".. ";
const BANNER: &str = include_str!("banner.txt");

pub struct Repl {
    vm: VirtualMachine,
    editor: DefaultEditor,
    buffer: String,
}

impl Repl {
    /// Create a new REPL instance
    pub fn new() -> RustylineResult<Self> {
        let editor = DefaultEditor::new()?;
        Ok(Self {
            vm: VirtualMachine::new(),
            editor,
            buffer: String::new(),
        })
    }

    /// Start the REPL loop
    pub fn run(&mut self) -> RustylineResult<()> {
        println!("{}", BANNER);
        println!("Metorex REPL v{}", env!("CARGO_PKG_VERSION"));
        println!("Type .help for more information, .exit to quit");
        println!();

        loop {
            let prompt = if self.buffer.is_empty() {
                PROMPT
            } else {
                CONTINUATION_PROMPT
            };

            match self.editor.readline(prompt) {
                Ok(line) => {
                    // Add to history
                    let _ = self.editor.add_history_entry(&line);

                    // Handle special commands
                    if self.buffer.is_empty() && line.trim().starts_with('.') {
                        if self.handle_command(&line) {
                            return Ok(());
                        }
                        continue;
                    }

                    // Add line to buffer
                    if !self.buffer.is_empty() {
                        self.buffer.push('\n');
                    }
                    self.buffer.push_str(&line);

                    // Try to evaluate the buffer
                    if self.should_evaluate() {
                        self.evaluate_buffer();
                        self.buffer.clear();
                    }
                }
                Err(ReadlineError::Interrupted) => {
                    // Ctrl-C - clear buffer and continue
                    println!("^C");
                    self.buffer.clear();
                }
                Err(ReadlineError::Eof) => {
                    // Ctrl-D - exit
                    println!("exit");
                    return Ok(());
                }
                Err(err) => {
                    eprintln!("Error: {}", err);
                    return Err(err);
                }
            }
        }
    }

    /// Handle special REPL commands
    fn handle_command(&mut self, line: &str) -> bool {
        let cmd = line.trim();

        match cmd {
            ".exit" | ".quit" => {
                println!("Goodbye!");
                return true;
            }
            ".help" => {
                self.print_help();
            }
            ".clear" => {
                print!("\x1B[2J\x1B[1;1H"); // ANSI escape codes to clear screen
                println!("{}", BANNER);
                println!("Metorex REPL v{}", env!("CARGO_PKG_VERSION"));
                println!("Type .help for more information, .exit to quit");
                println!();
            }
            ".reset" => {
                self.vm = VirtualMachine::new();
                println!("VM state reset");
            }
            _ => {
                eprintln!("Unknown command: {}", cmd);
                eprintln!("Type .help for available commands");
            }
        }

        false
    }

    /// Print help information
    fn print_help(&self) {
        println!("Metorex REPL Commands:");
        println!("  .help       Show this help message");
        println!("  .exit       Exit the REPL (or Ctrl-D)");
        println!("  .quit       Alias for .exit");
        println!("  .clear      Clear the screen");
        println!("  .reset      Reset the VM state");
        println!();
        println!("Keyboard shortcuts:");
        println!("  Ctrl-C      Clear current input buffer");
        println!("  Ctrl-D      Exit the REPL");
        println!();
        println!("Multi-line input:");
        println!("  The REPL automatically detects incomplete expressions");
        println!("  and prompts for continuation with '..'");
        println!();
    }

    /// Determine if the current buffer should be evaluated
    fn should_evaluate(&self) -> bool {
        let trimmed = self.buffer.trim();

        // Empty input
        if trimmed.is_empty() {
            return true;
        }

        // Try to parse and see if we get a complete statement
        let lexer = Lexer::new(&self.buffer);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens);

        match parser.parse() {
            Ok(_) => true, // Successfully parsed, ready to evaluate
            Err(errors) => {
                // Check if error indicates incomplete input
                for error in &errors {
                    let error_msg = error.to_string().to_lowercase();
                    if error_msg.contains("unexpected end of input")
                        || error_msg.contains("expected 'end'")
                        || error_msg.contains("unclosed")
                        || error_msg.contains("incomplete")
                    {
                        return false; // Need more input
                    }
                }
                // Other parse errors - try to evaluate anyway to show the error
                true
            }
        }
    }

    /// Evaluate the current buffer
    fn evaluate_buffer(&mut self) {
        // Tokenize
        let lexer = Lexer::new(&self.buffer);
        let tokens = lexer.tokenize();

        // Parse
        let mut parser = Parser::new(tokens);
        let program = match parser.parse() {
            Ok(prog) => prog,
            Err(errors) => {
                for err in errors {
                    eprintln!("Parse error: {}", err);
                }
                return;
            }
        };

        // Execute and display result
        match self.vm.execute_program(&program) {
            Ok(Some(result)) => {
                // Display non-nil results
                if !matches!(result, Object::Nil) {
                    println!("=> {}", Self::format_object(&result));
                }
            }
            Ok(None) => {
                // No result (e.g., statements like assignments)
            }
            Err(err) => {
                eprintln!("Runtime error: {}", self.format_error(&err));
            }
        }
    }

    /// Format an object for display
    pub fn format_object(obj: &Object) -> String {
        match obj {
            Object::Nil => "nil".to_string(),
            Object::Bool(b) => b.to_string(),
            Object::Int(i) => i.to_string(),
            Object::Float(f) => {
                // Format float nicely
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{:.1}", f)
                } else {
                    f.to_string()
                }
            }
            Object::String(s) => format!("\"{}\"", s),
            Object::Symbol(s) => format!(":{}", s),
            Object::Array(items) => {
                let items_borrowed = items.borrow();
                let formatted_items: Vec<String> =
                    items_borrowed.iter().map(Self::format_object).collect();
                format!("[{}]", formatted_items.join(", "))
            }
            Object::Dict(map) => {
                let map_borrowed = map.borrow();
                let mut entries: Vec<String> = map_borrowed
                    .iter()
                    .map(|(k, v)| format!("\"{}\" => {}", k, Self::format_object(v)))
                    .collect();
                entries.sort(); // Sort for consistent display
                format!("{{{}}}", entries.join(", "))
            }
            Object::Block { .. } => "<Block>".to_string(),
            Object::Method { .. } => "<Method>".to_string(),
            Object::NativeFunction(name) => format!("<NativeFunction: {}>", name),
            Object::Class(class) => format!("<Class: {}>", class.name()),
            Object::Module(module) => format!("<Module: {}>", module.name()),
            Object::Instance(instance) => {
                let instance_borrowed = instance.borrow();
                format!("<{} instance>", instance_borrowed.class_name())
            }
            Object::Range {
                start,
                end,
                exclusive,
            } => {
                if *exclusive {
                    format!(
                        "{}...{}",
                        Self::format_object(start),
                        Self::format_object(end)
                    )
                } else {
                    format!(
                        "{}..{}",
                        Self::format_object(start),
                        Self::format_object(end)
                    )
                }
            }
            Object::Exception(e) => {
                let e_borrowed = e.borrow();
                format!("<Exception: {}>", e_borrowed.message)
            }
            Object::Set(s) => {
                let s_borrowed = s.borrow();
                format!("<Set: {} items>", s_borrowed.len())
            }
            Object::Result(r) => match r {
                Ok(v) => format!("<Ok: {}>", Self::format_object(v)),
                Err(e) => format!("<Err: {}>", Self::format_object(e)),
            },
            Object::Binding(binding) => {
                format!("<Binding with {} vars>", binding.variables.len())
            }
        }
    }

    /// Format an error for display
    fn format_error(&self, err: &MetorexError) -> String {
        err.to_string()
    }
}

impl Default for Repl {
    fn default() -> Self {
        Self::new().expect("Failed to initialize REPL")
    }
}

// Variable resolution for Metorex
// This module implements static analysis for variable declarations and usage
// It tracks variable scopes, detects undefined variables, and identifies shadowing

use crate::ast::node::{Expression, MatchCase, MatchPattern, RescueClause, Statement};
use crate::error::{MetorexError, SourceLocation};
use crate::lexer::Position;
use std::collections::HashMap;

/// Convert a Position to SourceLocation
fn pos_to_loc(pos: Position) -> SourceLocation {
    SourceLocation::new(pos.line, pos.column, pos.offset)
}

/// Represents information about a variable declaration
#[derive(Debug, Clone)]
pub struct VariableInfo {
    /// The name of the variable
    pub name: String,

    /// The depth at which this variable was declared (0 = global)
    pub depth: usize,

    /// The position where this variable was declared
    pub position: Position,

    /// Whether this variable has been used
    pub used: bool,
}

/// Result of variable resolution
#[derive(Debug, Clone)]
pub struct ResolutionResult {
    /// Variables declared at each scope depth
    pub variables: HashMap<String, VariableInfo>,

    /// Errors encountered during resolution (undefined variables, shadowing, etc.)
    pub errors: Vec<MetorexError>,

    /// Warnings (unused variables, etc.)
    pub warnings: Vec<String>,
}

impl ResolutionResult {
    pub fn has_errors(&self) -> bool {
        !self.errors.is_empty()
    }
}

/// Variable resolver - performs static analysis on AST
pub struct Resolver {
    /// Stack of scopes, each scope is a map of variable names to their info
    scopes: Vec<HashMap<String, VariableInfo>>,

    /// Current depth in the scope stack (0 = global)
    current_depth: usize,

    /// Accumulated errors
    errors: Vec<MetorexError>,

    /// Accumulated warnings
    warnings: Vec<String>,

    /// Whether to treat undefined variables as errors
    strict_mode: bool,
}

impl Resolver {
    /// Creates a new resolver
    pub fn new() -> Self {
        Resolver {
            scopes: vec![HashMap::new()], // Start with global scope
            current_depth: 0,
            errors: Vec::new(),
            warnings: Vec::new(),
            strict_mode: true,
        }
    }

    /// Creates a new resolver with strict mode setting
    pub fn with_strict_mode(strict_mode: bool) -> Self {
        let mut resolver = Self::new();
        resolver.strict_mode = strict_mode;
        resolver
    }

    /// Resolves variables in a list of statements
    pub fn resolve(&mut self, statements: &[Statement]) -> ResolutionResult {
        for statement in statements {
            self.resolve_statement(statement);
        }

        // Check for unused variables
        self.check_unused_variables();

        ResolutionResult {
            variables: self.collect_all_variables(),
            errors: self.errors.clone(),
            warnings: self.warnings.clone(),
        }
    }

    /// Collects all variables from all scopes
    fn collect_all_variables(&self) -> HashMap<String, VariableInfo> {
        let mut all_vars = HashMap::new();
        for scope in &self.scopes {
            for (name, info) in scope {
                all_vars.insert(name.clone(), info.clone());
            }
        }
        all_vars
    }

    /// Checks for unused variables and generates warnings
    fn check_unused_variables(&mut self) {
        for scope in &self.scopes {
            for (name, info) in scope {
                if !info.used && !name.starts_with('_') {
                    self.warnings.push(format!(
                        "Unused variable '{}' at {}:{}",
                        name, info.position.line, info.position.column
                    ));
                }
            }
        }
    }

    /// Enters a new scope
    fn push_scope(&mut self) {
        self.scopes.push(HashMap::new());
        self.current_depth += 1;
    }

    /// Exits the current scope
    fn pop_scope(&mut self) {
        if self.scopes.len() > 1 {
            self.scopes.pop();
            self.current_depth -= 1;
        }
    }

    /// Declares a variable in the current scope
    fn declare(&mut self, name: String, position: Position) {
        // Check for shadowing in current scope first
        if let Some(existing) = self.scopes.last().unwrap().get(&name) {
            self.errors.push(MetorexError::syntax_error(
                format!(
                    "Variable '{}' is already declared in this scope at {}:{}",
                    name, existing.position.line, existing.position.column
                ),
                pos_to_loc(position),
            ));
            return;
        }

        // Check for shadowing from outer scopes
        let scope_count = self.scopes.len();
        if scope_count > 1 {
            for scope in self.scopes.iter().take(scope_count - 1).rev() {
                if let Some(existing) = scope.get(&name) {
                    self.warnings.push(format!(
                        "Variable '{}' at {}:{} shadows variable from outer scope at {}:{}",
                        name,
                        position.line,
                        position.column,
                        existing.position.line,
                        existing.position.column
                    ));
                    break;
                }
            }
        }

        // Now insert into current scope
        self.scopes.last_mut().unwrap().insert(
            name.clone(),
            VariableInfo {
                name,
                depth: self.current_depth,
                position,
                used: false,
            },
        );
    }

    /// Looks up a variable in the scope chain
    fn resolve_variable(&mut self, name: &str, position: Position) -> Option<usize> {
        // Search from innermost to outermost scope
        for (depth, scope) in self.scopes.iter_mut().enumerate().rev() {
            if let Some(var_info) = scope.get_mut(name) {
                var_info.used = true;
                return Some(depth);
            }
        }

        // Variable not found
        if self.strict_mode {
            self.errors.push(MetorexError::syntax_error(
                format!("Undefined variable '{}'", name),
                pos_to_loc(position),
            ));
        }

        None
    }

    /// Resolves a statement
    fn resolve_statement(&mut self, statement: &Statement) {
        match statement {
            Statement::Expression { expression, .. } => {
                self.resolve_expression(expression);
            }

            Statement::Assignment { target, value, .. } => {
                // Resolve the value first
                self.resolve_expression(value);

                // Then handle the target - this declares or updates a variable
                match target {
                    Expression::Identifier { name, position } => {
                        // Check if variable exists in CURRENT scope only
                        let exists_in_current_scope =
                            self.scopes.last().unwrap().contains_key(name);

                        if exists_in_current_scope {
                            // Update existing variable in current scope - mark it as used
                            if let Some(var_info) = self.scopes.last_mut().unwrap().get_mut(name) {
                                var_info.used = true;
                            }
                        } else {
                            // Declare new variable in current scope
                            // This might shadow a variable from an outer scope
                            self.declare(name.clone(), *position);
                        }
                    }
                    Expression::InstanceVariable { .. } | Expression::ClassVariable { .. } => {
                        // Instance and class variables don't need resolution
                    }
                    Expression::Index { array, index, .. } => {
                        // Resolve array and index expressions
                        self.resolve_expression(array);
                        self.resolve_expression(index);
                    }
                    _ => {
                        // Resolve target as expression
                        self.resolve_expression(target);
                    }
                }
            }

            Statement::FunctionDef {
                name,
                parameters,
                body,
                position,
            } => {
                // Declare function name in current scope
                self.declare(name.clone(), *position);

                // Enter function scope
                self.push_scope();

                // Declare parameters
                for param in parameters {
                    self.declare(param.name.clone(), param.position);
                    if let Some(default) = &param.default_value {
                        self.resolve_expression(default);
                    }
                }

                // Resolve function body
                for stmt in body {
                    self.resolve_statement(stmt);
                }

                // Exit function scope
                self.pop_scope();
            }

            Statement::MethodDef {
                parameters, body, ..
            } => {
                // Methods are similar to functions but don't declare a name in outer scope
                self.push_scope();

                // Declare parameters
                for param in parameters {
                    self.declare(param.name.clone(), param.position);
                    if let Some(default) = &param.default_value {
                        self.resolve_expression(default);
                    }
                }

                // Resolve method body
                for stmt in body {
                    self.resolve_statement(stmt);
                }

                self.pop_scope();
            }

            Statement::ClassDef { name, body, .. } => {
                // Class definitions create their own scope
                self.push_scope();

                // Resolve class body
                for stmt in body {
                    self.resolve_statement(stmt);
                }

                self.pop_scope();

                // Declare class name after resolving body
                self.declare(name.clone(), Position::default());
            }

            Statement::If {
                condition,
                then_branch,
                elsif_branches,
                else_branch,
                ..
            } => {
                self.resolve_expression(condition);

                self.push_scope();
                for stmt in then_branch {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();

                for elsif in elsif_branches {
                    self.resolve_expression(&elsif.condition);
                    self.push_scope();
                    for stmt in &elsif.body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }

                if let Some(else_body) = else_branch {
                    self.push_scope();
                    for stmt in else_body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
            }

            Statement::Unless {
                condition,
                then_branch,
                else_branch,
                ..
            } => {
                self.resolve_expression(condition);

                self.push_scope();
                for stmt in then_branch {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();

                if let Some(else_body) = else_branch {
                    self.push_scope();
                    for stmt in else_body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
            }

            Statement::While {
                condition, body, ..
            } => {
                self.resolve_expression(condition);
                self.push_scope();
                for stmt in body {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
            }

            Statement::For {
                variable,
                iterable,
                body,
                position,
            } => {
                self.resolve_expression(iterable);
                self.push_scope();
                self.declare(variable.clone(), *position);
                for stmt in body {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
            }

            Statement::Return { value, .. } => {
                if let Some(expr) = value {
                    self.resolve_expression(expr);
                }
            }

            Statement::Break { .. } | Statement::Continue { .. } => {
                // Nothing to resolve
            }

            Statement::Match {
                expression, cases, ..
            }
            | Statement::CaseIn {
                expression, cases, ..
            } => {
                self.resolve_expression(expression);

                for case in cases {
                    self.resolve_match_case(case);
                }
            }

            Statement::Begin {
                body,
                rescue_clauses,
                else_clause,
                ensure_block,
                ..
            } => {
                self.push_scope();
                for stmt in body {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();

                for rescue in rescue_clauses {
                    self.resolve_rescue_clause(rescue);
                }

                if let Some(else_body) = else_clause {
                    self.push_scope();
                    for stmt in else_body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }

                if let Some(ensure_body) = ensure_block {
                    self.push_scope();
                    for stmt in ensure_body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
            }

            Statement::Raise { exception, .. } => {
                if let Some(expr) = exception {
                    self.resolve_expression(expr);
                }
            }

            Statement::Block { statements, .. } => {
                self.push_scope();
                for stmt in statements {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
            }

            Statement::AttrReader { .. }
            | Statement::AttrWriter { .. }
            | Statement::AttrAccessor { .. } => {
                // These are class-level declarations, no variable resolution needed
            }

            Statement::ModuleDef { name, body, .. } => {
                self.push_scope();
                for stmt in body {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
                self.declare(name.clone(), Position::default());
            }

            Statement::Include { .. } | Statement::Extend { .. } => {
                // Module inclusion/extension, no variable resolution needed
            }
        }
    }

    /// Resolves a match case
    fn resolve_match_case(&mut self, case: &MatchCase) {
        self.push_scope();

        // Declare variables from pattern
        self.resolve_pattern(&case.pattern);

        // Resolve guard condition
        if let Some(guard) = &case.guard {
            self.resolve_expression(guard);
        }

        // Resolve case body
        for stmt in &case.body {
            self.resolve_statement(stmt);
        }

        self.pop_scope();
    }

    /// Resolves a rescue clause
    fn resolve_rescue_clause(&mut self, rescue: &RescueClause) {
        self.push_scope();

        // Declare exception variable if present
        if let Some(var_name) = &rescue.variable_name {
            self.declare(var_name.clone(), rescue.position);
        }

        // Resolve rescue body
        for stmt in &rescue.body {
            self.resolve_statement(stmt);
        }

        self.pop_scope();
    }

    /// Resolves variables declared in a pattern
    fn resolve_pattern(&mut self, pattern: &MatchPattern) {
        match pattern {
            MatchPattern::Identifier(name) => {
                self.declare(name.clone(), Position::default());
            }
            MatchPattern::Array(patterns) => {
                for p in patterns {
                    self.resolve_pattern(p);
                }
            }
            MatchPattern::Rest(name) => {
                self.declare(name.clone(), Position::default());
            }
            MatchPattern::Object(fields) => {
                for (_, pattern) in fields {
                    self.resolve_pattern(pattern);
                }
            }
            _ => {
                // Literals and wildcards don't declare variables
            }
        }
    }

    /// Resolves an expression
    fn resolve_expression(&mut self, expression: &Expression) {
        match expression {
            Expression::Identifier { name, position } => {
                self.resolve_variable(name, *position);
            }

            Expression::InstanceVariable { .. } | Expression::ClassVariable { .. } => {
                // Instance and class variables don't need resolution
            }

            Expression::BinaryOp { left, right, .. } => {
                self.resolve_expression(left);
                self.resolve_expression(right);
            }

            Expression::UnaryOp { operand, .. } => {
                self.resolve_expression(operand);
            }

            Expression::Call {
                callee, arguments, ..
            } => {
                self.resolve_expression(callee);
                for arg in arguments {
                    self.resolve_expression(arg);
                }
            }

            Expression::MethodCall {
                receiver,
                arguments,
                ..
            } => {
                self.resolve_expression(receiver);
                for arg in arguments {
                    self.resolve_expression(arg);
                }
            }

            Expression::Array { elements, .. } => {
                for element in elements {
                    self.resolve_expression(element);
                }
            }

            Expression::Index { array, index, .. } => {
                self.resolve_expression(array);
                self.resolve_expression(index);
            }

            Expression::Dictionary { entries, .. } => {
                for (key, value) in entries {
                    self.resolve_expression(key);
                    self.resolve_expression(value);
                }
            }

            Expression::Lambda {
                parameters, body, ..
            } => {
                self.push_scope();

                // Declare parameters
                for param in parameters {
                    self.declare(param.clone(), Position::default());
                }

                // Resolve lambda body
                for stmt in body {
                    self.resolve_statement(stmt);
                }

                self.pop_scope();
            }

            Expression::Grouped { expression, .. } => {
                self.resolve_expression(expression);
            }

            Expression::Range { start, end, .. } => {
                self.resolve_expression(start);
                self.resolve_expression(end);
            }

            Expression::InterpolatedString { parts, .. } => {
                for part in parts {
                    if let crate::ast::node::InterpolationPart::Expression(expr) = part {
                        self.resolve_expression(expr);
                    }
                }
            }

            Expression::Case {
                expression,
                cases,
                else_case,
                ..
            } => {
                // Resolve the match expression
                self.resolve_expression(expression);

                // Resolve each case
                for case in cases {
                    // Push a new scope for this case
                    self.push_scope();

                    // Declare variables from pattern
                    self.resolve_pattern(&case.pattern);

                    // Resolve guard if present
                    if let Some(guard) = &case.guard {
                        self.resolve_expression(guard);
                    }

                    // Resolve body expression
                    self.resolve_expression(&case.body);

                    self.pop_scope();
                }

                // Resolve else case if present
                if let Some(else_expr) = else_case {
                    self.resolve_expression(else_expr);
                }
            }

            Expression::ScopeResolution { namespace, .. } => {
                self.resolve_expression(namespace);
            }

            Expression::GlobalVariable { .. } => {
                // Global variables don't need scope resolution
            }

            Expression::If {
                condition,
                then_branch,
                elsif_branches,
                else_branch,
                ..
            } => {
                self.resolve_expression(condition);
                self.push_scope();
                for stmt in then_branch {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
                for elsif in elsif_branches {
                    self.resolve_expression(&elsif.condition);
                    self.push_scope();
                    for stmt in &elsif.body {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
                if let Some(else_stmts) = else_branch {
                    self.push_scope();
                    for stmt in else_stmts {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
            }

            Expression::Unless {
                condition,
                then_branch,
                else_branch,
                ..
            } => {
                self.resolve_expression(condition);
                self.push_scope();
                for stmt in then_branch {
                    self.resolve_statement(stmt);
                }
                self.pop_scope();
                if let Some(else_stmts) = else_branch {
                    self.push_scope();
                    for stmt in else_stmts {
                        self.resolve_statement(stmt);
                    }
                    self.pop_scope();
                }
            }

            // Literals don't need resolution
            Expression::IntLiteral { .. }
            | Expression::FloatLiteral { .. }
            | Expression::StringLiteral { .. }
            | Expression::Symbol { .. }
            | Expression::BoolLiteral { .. }
            | Expression::NilLiteral { .. }
            | Expression::SelfExpr { .. }
            | Expression::Super { .. } => {}
        }
    }
}

impl Default for Resolver {
    fn default() -> Self {
        Self::new()
    }
}

// Scope and variable management for Metorex
// This module implements lexical scoping with scope chain traversal

use crate::object::Object;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

/// Represents a single scope in the scope chain
/// Each scope can have a parent scope, forming a chain for variable lookup
#[derive(Debug)]
pub struct Scope {
    /// Variable storage: maps variable names to shared mutable references
    /// This allows closures to mutate captured variables
    variables: HashMap<String, Rc<RefCell<Object>>>,

    /// Reference to the parent scope (None for global scope)
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    /// Creates a new scope with no parent (global scope)
    pub fn new() -> Self {
        Scope {
            variables: HashMap::new(),
            parent: None,
        }
    }

    /// Creates a new scope with the given parent scope
    pub fn with_parent(parent: Rc<RefCell<Scope>>) -> Self {
        Scope {
            variables: HashMap::new(),
            parent: Some(parent),
        }
    }

    /// Defines a new variable in the current scope
    /// If the variable already exists in this scope, it will be overwritten
    pub fn define(&mut self, name: String, value: Object) {
        self.variables.insert(name, Rc::new(RefCell::new(value)));
    }

    /// Defines a new variable in the current scope with a shared reference
    /// Used when a closure defines a captured variable
    pub fn define_shared(&mut self, name: String, value: Rc<RefCell<Object>>) {
        self.variables.insert(name, value);
    }

    /// Gets a variable value by traversing the scope chain
    /// Returns None if the variable is not found in any scope
    pub fn get(&self, name: &str) -> Option<Object> {
        // First, check if the variable exists in this scope
        if let Some(value_ref) = self.variables.get(name) {
            return Some(value_ref.borrow().clone());
        }

        // If not found, check the parent scope recursively
        if let Some(parent) = &self.parent {
            return parent.borrow().get(name);
        }

        // Variable not found in any scope
        None
    }

    /// Gets a shared reference to a variable by traversing the scope chain
    /// Used for closure capture to enable mutable closures
    pub fn get_ref(&self, name: &str) -> Option<Rc<RefCell<Object>>> {
        // First, check if the variable exists in this scope
        if let Some(value_ref) = self.variables.get(name) {
            return Some(value_ref.clone());
        }

        // If not found, check the parent scope recursively
        if let Some(parent) = &self.parent {
            return parent.borrow().get_ref(name);
        }

        // Variable not found in any scope
        None
    }

    /// Sets a variable value by traversing the scope chain
    /// Returns true if the variable was found and updated, false otherwise
    /// This method will NOT create a new variable if it doesn't exist
    pub fn set(&mut self, name: &str, value: Object) -> bool {
        // First, check if the variable exists in this scope
        if let Some(value_ref) = self.variables.get(name) {
            *value_ref.borrow_mut() = value;
            return true;
        }

        // If not found, try to set it in the parent scope
        if let Some(parent) = &self.parent {
            return parent.borrow_mut().set(name, value);
        }

        // Variable not found in any scope
        false
    }

    /// Gets a variable at a specific depth in the scope chain
    /// depth=0 means current scope, depth=1 means parent, etc.
    /// This is useful for closure resolution where we know the exact depth
    pub fn get_at(&self, depth: usize, name: &str) -> Option<Object> {
        if depth == 0 {
            return self.variables.get(name).map(|v| v.borrow().clone());
        }

        if let Some(parent) = &self.parent {
            return parent.borrow().get_at(depth - 1, name);
        }

        None
    }

    /// Sets a variable at a specific depth in the scope chain
    /// depth=0 means current scope, depth=1 means parent, etc.
    /// Returns true if successful, false if the depth is invalid or variable doesn't exist
    pub fn set_at(&mut self, depth: usize, name: &str, value: Object) -> bool {
        if depth == 0 {
            if let Some(value_ref) = self.variables.get(name) {
                *value_ref.borrow_mut() = value;
                return true;
            }
            return false;
        }

        if let Some(parent) = &self.parent {
            return parent.borrow_mut().set_at(depth - 1, name, value);
        }

        false
    }

    /// Collects all variables from the entire scope chain
    /// Returns a HashMap with all visible variables (parent scope vars may be shadowed)
    pub fn collect_all_vars(&self) -> HashMap<String, Object> {
        let mut all_vars = HashMap::new();

        // Start from parent and work backwards, so that closer scopes override farther ones
        if let Some(parent) = &self.parent {
            all_vars = parent.borrow().collect_all_vars();
        }

        // Now add this scope's variables (potentially overriding parent values)
        for (name, value_ref) in &self.variables {
            all_vars.insert(name.clone(), value_ref.borrow().clone());
        }

        all_vars
    }

    /// Collects all variable references from the entire scope chain
    /// Returns a HashMap with shared references to all visible variables
    /// Used for closure capture to enable mutable closures
    pub fn collect_all_var_refs(&self) -> HashMap<String, Rc<RefCell<Object>>> {
        let mut all_vars = HashMap::new();

        // Start from parent and work backwards, so that closer scopes override farther ones
        if let Some(parent) = &self.parent {
            all_vars = parent.borrow().collect_all_var_refs();
        }

        // Now add this scope's variables (potentially overriding parent values)
        for (name, value_ref) in &self.variables {
            all_vars.insert(name.clone(), value_ref.clone());
        }

        all_vars
    }
}

impl Default for Scope {
    fn default() -> Self {
        Self::new()
    }
}

//! Call frame tracking for the Metorex virtual machine.
//!
//! This module provides call frame information used for debugging and stack traces.

/// Call frame information stored on the VM call stack for debugging.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CallFrame {
    /// Human-readable frame identifier (method/function name).
    name: String,
    /// Optional source location ("file:line") to aid debugging.
    location: Option<String>,
}

impl CallFrame {
    /// Create a new call frame description.
    pub fn new(name: impl Into<String>, location: Option<String>) -> Self {
        Self {
            name: name.into(),
            location,
        }
    }

    /// Return the frame name.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// Return the optional source location.
    pub fn location(&self) -> Option<&str> {
        self.location.as_deref()
    }
}

// Class and function definition execution for the Metorex VM.
// This module handles class and function definition statements.

use super::ControlFlow;
use super::core::VirtualMachine;
use super::utils::*;

use crate::ast::{Expression, Statement};
use crate::class::Class;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::{Method, Object};
use std::rc::Rc;

impl VirtualMachine {
    /// Execute class definition - create a Class object and register it in the environment.
    pub(crate) fn execute_class_def(
        &mut self,
        name: &str,
        superclass_name: Option<&str>,
        body: &[Statement],
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        // Resolve superclass if specified
        let superclass = if let Some(super_name) = superclass_name {
            match self.environment().get(super_name) {
                Some(Object::Class(class)) => Some(class),
                Some(_) => {
                    return Err(MetorexError::runtime_error(
                        format!("Superclass '{}' must be a class", super_name),
                        position_to_location(position),
                    ));
                }
                None => {
                    return Err(MetorexError::runtime_error(
                        format!("Undefined superclass '{}'", super_name),
                        position_to_location(position),
                    ));
                }
            }
        } else {
            None
        };

        // Create the class object
        let class = Rc::new(Class::new(name, superclass));

        // Process the class body to extract methods and instance variable declarations
        for statement in body {
            match statement {
                Statement::MethodDef {
                    name: method_name,
                    parameters,
                    body: method_body,
                    ..
                } => {
                    // Create a Method object
                    let param_names: Vec<String> = parameters
                        .iter()
                        .filter(|p| !p.is_named_keyword && !p.is_block)
                        .map(|p| p.name.clone())
                        .collect();
                    let keyword_parameters: Vec<(String, Option<crate::ast::Expression>)> =
                        parameters
                            .iter()
                            .filter(|p| p.is_named_keyword)
                            .map(|p| (p.name.clone(), p.default_value.clone()))
                            .collect();
                    let block_parameter = parameters
                        .iter()
                        .find(|p| p.is_block)
                        .map(|p| p.name.clone());
                    let mut m = Method::new(method_name.clone(), param_names, method_body.clone());
                    m.keyword_parameters = keyword_parameters;
                    m.block_parameter = block_parameter;
                    let method = Rc::new(m);
                    class.define_method(method_name, method);
                }
                Statement::Assignment {
                    target: Expression::InstanceVariable { name: var_name, .. },
                    ..
                } => {
                    // Declaring an instance variable (e.g., @x = nil in class body)
                    class.declare_instance_var(var_name);
                }
                Statement::Assignment {
                    target: Expression::ClassVariable { name: var_name, .. },
                    value,
                    ..
                } => {
                    // Class variable initialization (e.g., @@count = 0 in class body)
                    let initial_value = self.evaluate_expression(value)?;
                    class.set_class_var(var_name, initial_value);
                }
                Statement::Expression {
                    expression: Expression::InstanceVariable { name: var_name, .. },
                    ..
                } => {
                    // Instance variable declaration without assignment
                    class.declare_instance_var(var_name);
                }
                Statement::AttrReader { attributes, .. } => {
                    // Generate getter methods for each attribute
                    for attr_name in attributes {
                        let getter_body = vec![Statement::Return {
                            value: Some(Expression::InstanceVariable {
                                name: attr_name.clone(),
                                position,
                            }),
                            position,
                        }];
                        let method = Rc::new(Method::new(attr_name.clone(), vec![], getter_body));
                        class.define_method(attr_name, method);
                        class.declare_instance_var(attr_name);
                    }
                }
                Statement::AttrWriter { attributes, .. } => {
                    // Generate setter methods for each attribute
                    for attr_name in attributes {
                        let setter_body = vec![Statement::Assignment {
                            target: Expression::InstanceVariable {
                                name: attr_name.clone(),
                                position,
                            },
                            value: Expression::Identifier {
                                name: "value".to_string(),
                                position,
                            },
                            position,
                        }];
                        let method = Rc::new(Method::new(
                            format!("{}=", attr_name),
                            vec!["value".to_string()],
                            setter_body,
                        ));
                        class.define_method(format!("{}=", attr_name), method);
                        class.declare_instance_var(attr_name);
                    }
                }
                Statement::AttrAccessor { attributes, .. } => {
                    // Generate both getter and setter methods for each attribute
                    for attr_name in attributes {
                        // Getter
                        let getter_body = vec![Statement::Return {
                            value: Some(Expression::InstanceVariable {
                                name: attr_name.clone(),
                                position,
                            }),
                            position,
                        }];
                        let getter_method =
                            Rc::new(Method::new(attr_name.clone(), vec![], getter_body));
                        class.define_method(attr_name, getter_method);

                        // Setter
                        let setter_body = vec![Statement::Assignment {
                            target: Expression::InstanceVariable {
                                name: attr_name.clone(),
                                position,
                            },
                            value: Expression::Identifier {
                                name: "value".to_string(),
                                position,
                            },
                            position,
                        }];
                        let setter_method = Rc::new(Method::new(
                            format!("{}=", attr_name),
                            vec!["value".to_string()],
                            setter_body,
                        ));
                        class.define_method(format!("{}=", attr_name), setter_method);

                        class.declare_instance_var(attr_name);
                    }
                }
                Statement::Assignment {
                    target:
                        Expression::Identifier {
                            name: const_name, ..
                        },
                    value,
                    ..
                } => {
                    // Constant assignment in class body (e.g., PI = 3.14159)
                    let const_value = self.evaluate_expression(value)?;
                    class.set_class_var(const_name, const_value);
                }
                Statement::Include {
                    module_name,
                    position,
                } => {
                    // include ModuleName: copy module instance methods into this class
                    match self.environment().get(module_name) {
                        Some(Object::Module(module)) => {
                            for method_name in module.method_names() {
                                if let Some(method) = module.find_method(&method_name) {
                                    class.define_method(&method_name, method);
                                }
                            }
                        }
                        Some(_) => {
                            return Err(MetorexError::runtime_error(
                                format!("'{}' is not a module", module_name),
                                position_to_location(*position),
                            ));
                        }
                        None => {
                            return Err(MetorexError::runtime_error(
                                format!("Undefined module '{}'", module_name),
                                position_to_location(*position),
                            ));
                        }
                    }
                }
                Statement::Extend {
                    module_name,
                    position,
                } => {
                    // extend ModuleName: add module methods as class-level methods
                    match self.environment().get(module_name) {
                        Some(Object::Module(module)) => {
                            for method_name in module.method_names() {
                                if let Some(method) = module.find_method(&method_name) {
                                    class.set_class_var(
                                        format!("__ext__{}", method_name),
                                        Object::Method(method),
                                    );
                                }
                            }
                        }
                        Some(_) => {
                            return Err(MetorexError::runtime_error(
                                format!("'{}' is not a module", module_name),
                                position_to_location(*position),
                            ));
                        }
                        None => {
                            return Err(MetorexError::runtime_error(
                                format!("Undefined module '{}'", module_name),
                                position_to_location(*position),
                            ));
                        }
                    }
                }
                _ => {
                    // Handle define_method(:name) { |args| body } calls in class body
                    if let Statement::Expression {
                        expression:
                            Expression::Call {
                                callee,
                                arguments: call_args,
                                trailing_block: Some(block_expr),
                                ..
                            },
                        ..
                    } = statement
                        && let Expression::Identifier {
                            name: callee_name, ..
                        } = callee.as_ref()
                        && callee_name == "define_method"
                    {
                        let method_name_str = if let Some(name_expr) = call_args.first() {
                            match self.evaluate_expression(name_expr)? {
                                Object::String(s) => (*s).clone(),
                                Object::Symbol(s) => (*s).clone(),
                                _ => {
                                    return Err(MetorexError::runtime_error(
                                        "define_method: first argument must be a String or Symbol",
                                        position_to_location(position),
                                    ));
                                }
                            }
                        } else {
                            return Err(MetorexError::runtime_error(
                                "define_method requires at least one argument",
                                position_to_location(position),
                            ));
                        };
                        let block_obj = self.evaluate_expression(block_expr)?;
                        let block = match block_obj {
                            Object::Block(b) => b,
                            _ => {
                                return Err(MetorexError::runtime_error(
                                    "define_method requires a block",
                                    position_to_location(position),
                                ));
                            }
                        };
                        let mut method = Method::new(
                            method_name_str.clone(),
                            block.parameters.clone(),
                            block.body.clone(),
                        );
                        // Capture closure: prefer existing captured_vars, otherwise snap current scope
                        method.captured_vars = Some(if block.captured_vars.is_empty() {
                            self.environment().current_scope_var_refs()
                        } else {
                            block.captured_vars.clone()
                        });
                        class.define_method(&method_name_str, Rc::new(method));
                    }
                }
            }
        }

        // Register the class in the environment
        self.environment_mut()
            .define(name.to_string(), Object::Class(class));

        Ok(ControlFlow::Next)
    }

    /// Execute function definition - create a Method object and register it in the environment as a function.
    pub(crate) fn execute_function_def(
        &mut self,
        name: &str,
        parameters: &[crate::ast::Parameter],
        body: &[Statement],
        position: crate::lexer::Position,
    ) -> Result<ControlFlow, MetorexError> {
        // Extract positional parameter names (exclude named keyword and block params)
        let param_names: Vec<String> = parameters
            .iter()
            .filter(|p| !p.is_named_keyword && !p.is_block)
            .map(|p| p.name.clone())
            .collect();

        // Extract named keyword parameters
        let keyword_parameters: Vec<(String, Option<crate::ast::Expression>)> = parameters
            .iter()
            .filter(|p| p.is_named_keyword)
            .map(|p| (p.name.clone(), p.default_value.clone()))
            .collect();

        // Extract block parameter name
        let block_parameter = parameters
            .iter()
            .find(|p| p.is_block)
            .map(|p| p.name.clone());

        // Create source location from position
        let source_location =
            crate::error::SourceLocation::new(position.line, position.column, position.offset);

        // Create a Method object to represent the function
        let mut function = Method::with_source_location(
            name.to_string(),
            param_names,
            body.to_vec(),
            source_location,
        );
        function.keyword_parameters = keyword_parameters;
        function.block_parameter = block_parameter;
        let function = Rc::new(function);

        // Register the function in the environment
        self.environment_mut()
            .define(name.to_string(), Object::Method(function));

        Ok(ControlFlow::Next)
    }

    /// Execute module definition - create a Module object and register it.
    pub(crate) fn execute_module_def(
        &mut self,
        name: &str,
        body: &[Statement],
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        let module = Rc::new(Class::new(name, None));

        for statement in body {
            match statement {
                Statement::MethodDef {
                    name: method_name,
                    parameters,
                    body: method_body,
                    ..
                } => {
                    let param_names: Vec<String> = parameters
                        .iter()
                        .filter(|p| !p.is_named_keyword && !p.is_block)
                        .map(|p| p.name.clone())
                        .collect();
                    let keyword_parameters: Vec<(String, Option<crate::ast::Expression>)> =
                        parameters
                            .iter()
                            .filter(|p| p.is_named_keyword)
                            .map(|p| (p.name.clone(), p.default_value.clone()))
                            .collect();
                    let block_parameter = parameters
                        .iter()
                        .find(|p| p.is_block)
                        .map(|p| p.name.clone());
                    let mut m = Method::new(method_name.clone(), param_names, method_body.clone());
                    m.keyword_parameters = keyword_parameters;
                    m.block_parameter = block_parameter;
                    module.define_method(method_name, Rc::new(m));
                }
                _ => {
                    return Err(MetorexError::runtime_error(
                        "Unsupported statement in module body".to_string(),
                        position_to_location(position),
                    ));
                }
            }
        }

        self.environment_mut()
            .define(name.to_string(), Object::Module(module));

        Ok(ControlFlow::Next)
    }

    /// Execute include at statement level (outside class body - error).
    pub(crate) fn execute_include(
        &mut self,
        _module_name: &str,
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        Err(MetorexError::runtime_error(
            "include can only be used inside a class definition",
            position_to_location(position),
        ))
    }

    /// Execute extend at statement level (outside class body - error).
    pub(crate) fn execute_extend(
        &mut self,
        _module_name: &str,
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        Err(MetorexError::runtime_error(
            "extend can only be used inside a class definition",
            position_to_location(position),
        ))
    }
}

//! Control flow representation for the Metorex virtual machine.
//!
//! This module defines the `ControlFlow` enum that represents signals produced
//! during statement execution (return, break, continue, exceptions).

use crate::lexer::Position;
use crate::object::Object;

/// Represents control-flow signals produced during statement execution.
#[derive(Debug, Clone, PartialEq)]
pub(crate) enum ControlFlow {
    /// Normal execution, continue with next statement.
    Next,
    /// A return statement was encountered with an associated value.
    Return { value: Object, position: Position },
    /// A break statement was encountered.
    Break { position: Position },
    /// A continue statement was encountered.
    Continue { position: Position },
    /// An exception was raised and is propagating.
    Exception {
        exception: Object,
        position: Position,
    },
}

// Control structure execution for the Metorex VM.
// This module handles if/else, while loops, and for loops.

use super::ControlFlow;
use super::core::VirtualMachine;
use super::utils::*;

use crate::ast::{ElsifBranch, Expression, Statement};
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;

impl VirtualMachine {
    /// Execute an if/elsif/else statement.
    pub(crate) fn execute_if(
        &mut self,
        condition: &Expression,
        then_branch: &[Statement],
        elsif_branches: &[ElsifBranch],
        else_branch: &Option<Vec<Statement>>,
    ) -> Result<ControlFlow, MetorexError> {
        let condition_value = self.evaluate_expression(condition)?;

        if is_truthy(&condition_value) {
            self.execute_statements_internal(then_branch)
        } else {
            // Try each elsif branch
            for elsif in elsif_branches {
                let elsif_condition_value = self.evaluate_expression(&elsif.condition)?;
                if is_truthy(&elsif_condition_value) {
                    return self.execute_statements_internal(&elsif.body);
                }
            }

            // If no elsif matched, try else branch
            if let Some(else_stmts) = else_branch {
                self.execute_statements_internal(else_stmts)
            } else {
                Ok(ControlFlow::Next)
            }
        }
    }

    /// Execute an unless statement (inverted if).
    pub(crate) fn execute_unless(
        &mut self,
        condition: &Expression,
        then_branch: &[Statement],
        else_branch: &Option<Vec<Statement>>,
    ) -> Result<ControlFlow, MetorexError> {
        let condition_value = self.evaluate_expression(condition)?;

        if !is_truthy(&condition_value) {
            self.execute_statements_internal(then_branch)
        } else if let Some(else_stmts) = else_branch {
            self.execute_statements_internal(else_stmts)
        } else {
            Ok(ControlFlow::Next)
        }
    }

    /// Execute a while loop.
    pub(crate) fn execute_while(
        &mut self,
        condition: &Expression,
        body: &[Statement],
    ) -> Result<ControlFlow, MetorexError> {
        loop {
            let condition_value = self.evaluate_expression(condition)?;

            if !is_truthy(&condition_value) {
                break;
            }

            match self.execute_statements_internal(body)? {
                ControlFlow::Next => continue,
                ControlFlow::Break { .. } => break,
                ControlFlow::Continue { .. } => continue,
                ControlFlow::Return { value, position } => {
                    return Ok(ControlFlow::Return { value, position });
                }
                ControlFlow::Exception {
                    exception,
                    position,
                } => {
                    return Ok(ControlFlow::Exception {
                        exception,
                        position,
                    });
                }
            }
        }

        Ok(ControlFlow::Next)
    }

    /// Execute a for loop over an iterable.
    pub(crate) fn execute_for(
        &mut self,
        variable: &str,
        iterable_expr: &Expression,
        body: &[Statement],
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        let iterable = self.evaluate_expression(iterable_expr)?;

        let elements = match iterable {
            Object::Array(array_rc) => {
                let arr = array_rc.borrow();
                arr.clone()
            }
            Object::Range {
                start,
                end,
                exclusive,
            } => {
                // Convert range to array of integers
                match (*start, *end) {
                    (Object::Int(start_val), Object::Int(end_val)) => {
                        let mut elements = Vec::new();
                        let end_inclusive = if exclusive { end_val - 1 } else { end_val };

                        if start_val <= end_inclusive {
                            for i in start_val..=end_inclusive {
                                elements.push(Object::Int(i));
                            }
                        } else {
                            // Reverse range
                            for i in (end_inclusive..=start_val).rev() {
                                elements.push(Object::Int(i));
                            }
                        }
                        elements
                    }
                    _ => {
                        return Err(MetorexError::type_error(
                            "Range bounds must be integers for iteration",
                            position_to_location(position),
                        ));
                    }
                }
            }
            other => {
                return Err(MetorexError::type_error(
                    format!(
                        "Cannot iterate over type '{}', expected Array or Range",
                        other.type_name()
                    ),
                    position_to_location(position),
                ));
            }
        };

        for element in elements {
            self.environment_mut().push_scope();
            self.environment_mut().define(variable.to_string(), element);

            let result = self.execute_statements_internal(body);

            self.environment_mut().pop_scope();

            match result? {
                ControlFlow::Next => continue,
                ControlFlow::Break { .. } => break,
                ControlFlow::Continue { .. } => continue,
                ControlFlow::Return { value, position } => {
                    return Ok(ControlFlow::Return { value, position });
                }
                ControlFlow::Exception {
                    exception,
                    position,
                } => {
                    return Ok(ControlFlow::Exception {
                        exception,
                        position,
                    });
                }
            }
        }

        Ok(ControlFlow::Next)
    }
}

// Virtual machine core structure for the Metorex AST interpreter.
// This module defines the runtime scaffolding that powers execution.

use super::errors::*;
use super::init::*;
use super::utils::*;
use super::{CallFrame, ControlFlow, GlobalRegistry, Heap};

use crate::ast::{BinaryOp, Expression, Statement};
use crate::builtin_classes::BuiltinClasses;
use crate::environment::Environment;
use crate::error::MetorexError;
use crate::object::{BlockStatement, Object};
use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::rc::Rc;

/// Core virtual machine responsible for executing Metorex programs.
pub struct VirtualMachine {
    environment: Environment,
    call_stack: Vec<CallFrame>,
    globals: GlobalRegistry,
    heap: Rc<RefCell<Heap>>,
    builtins: BuiltinClasses,
    current_file: Option<PathBuf>,
    loaded_files: HashSet<PathBuf>,
    /// Trailing block passed to the current call (e.g., `foo() do |x| ... end`).
    /// Set before invoke_method/invoke_callable; taken at method body entry.
    pub(crate) pending_block: Option<Object>,
}

impl VirtualMachine {
    /// Construct a new virtual machine instance with all built-ins registered.
    pub fn new() -> Self {
        let mut environment = Environment::new();
        let builtins = BuiltinClasses::new();

        initialize_builtin_methods(&builtins);

        let mut globals = GlobalRegistry::new();
        register_builtin_classes(&mut globals, &builtins);
        register_singletons(&mut globals);
        register_native_functions(&mut globals);

        seed_environment_with_globals(&mut environment, &globals);

        Self {
            environment,
            call_stack: Vec::new(),
            globals,
            heap: Rc::new(RefCell::new(Heap::default())),
            builtins,
            current_file: None,
            loaded_files: HashSet::new(),
            pending_block: None,
        }
    }

    /// Access the environment.
    pub fn environment(&self) -> &Environment {
        &self.environment
    }

    /// Mutably access the environment (used by the interpreter).
    pub fn environment_mut(&mut self) -> &mut Environment {
        &mut self.environment
    }

    /// Access the registered built-in classes.
    pub fn builtins(&self) -> &BuiltinClasses {
        &self.builtins
    }

    /// Access the global registry.
    pub fn globals(&self) -> &GlobalRegistry {
        &self.globals
    }

    /// Mutably access the global registry.
    pub fn globals_mut(&mut self) -> &mut GlobalRegistry {
        &mut self.globals
    }

    /// Borrow the heap allocator.
    pub fn heap(&self) -> Rc<RefCell<Heap>> {
        Rc::clone(&self.heap)
    }

    /// Set the current file being executed.
    pub fn set_current_file(&mut self, path: PathBuf) {
        self.current_file = Some(path);
    }

    /// Get the current file being executed.
    pub fn get_current_file(&self) -> Option<&PathBuf> {
        self.current_file.as_ref()
    }

    /// Mark a file as loaded in the registry.
    pub fn mark_file_loaded(&mut self, path: PathBuf) {
        self.loaded_files.insert(path);
    }

    /// Check if a file has already been loaded.
    pub fn is_file_loaded(&self, path: &PathBuf) -> bool {
        self.loaded_files.contains(path)
    }

    /// Run a closure with a new call frame pushed onto the stack.
    pub fn with_call_frame<F, R>(&mut self, frame: CallFrame, action: F) -> R
    where
        F: FnOnce(&mut Self) -> R,
    {
        self.call_stack.push(frame);
        let result = action(self);
        self.call_stack.pop();
        result
    }

    /// Inspect the current call stack (top is last element).
    pub fn call_stack(&self) -> &[CallFrame] {
        &self.call_stack
    }

    /// Get the name of the current method being executed (from the top of the call stack).
    pub(crate) fn get_current_method_name(&self) -> Option<&str> {
        self.call_stack.last().map(|frame| frame.name())
    }

    /// Execute a sequence of statements and return an optional result (from return statements).
    pub fn execute_program(
        &mut self,
        statements: &[Statement],
    ) -> Result<Option<Object>, MetorexError> {
        let mut last_value = None;

        for statement in statements {
            // If it's an expression statement, track its value
            if let Statement::Expression {
                expression,
                position,
            } = statement
            {
                let result = self.evaluate_expression(expression)?;

                // Ruby-style auto-call: if expression statement evaluates to a Method
                // and the expression is a bare identifier, auto-call it with zero args
                if matches!(expression, Expression::Identifier { .. })
                    && matches!(result, Object::Method(_))
                {
                    last_value = Some(self.invoke_callable(result, vec![], *position)?);
                    continue;
                }

                last_value = Some(result);
                continue;
            }

            // Match/CaseIn statements also produce values
            if matches!(
                statement,
                Statement::Match { .. } | Statement::CaseIn { .. }
            ) {
                match self.execute_statement(statement)? {
                    ControlFlow::Return { value, .. } => {
                        last_value = Some(value);
                        continue;
                    }
                    ControlFlow::Next => {}
                    ControlFlow::Exception {
                        exception,
                        position,
                    } => {
                        return Err(MetorexError::runtime_error(
                            format!("Uncaught exception: {}", format_exception(&exception)),
                            position_to_location(position),
                        ));
                    }
                    ControlFlow::Break { position } => {
                        return Err(loop_control_error("break", position));
                    }
                    ControlFlow::Continue { position } => {
                        return Err(loop_control_error("continue", position));
                    }
                }
                continue;
            }

            // Execute other statements
            match self.execute_statement(statement)? {
                ControlFlow::Next => {}
                ControlFlow::Return { value, .. } => return Ok(Some(value)),
                ControlFlow::Exception {
                    exception,
                    position,
                } => {
                    return Err(MetorexError::runtime_error(
                        format!("Uncaught exception: {}", format_exception(&exception)),
                        position_to_location(position),
                    ));
                }
                ControlFlow::Break { position } => {
                    return Err(loop_control_error("break", position));
                }
                ControlFlow::Continue { position } => {
                    return Err(loop_control_error("continue", position));
                }
            }
        }

        Ok(last_value)
    }

    /// Execute a file with automatic deduplication and path tracking.
    ///
    /// This method loads and executes a file, handling:
    /// - File deduplication (files are only executed once)
    /// - Current file path tracking (for require_relative)
    /// - Automatic path canonicalization
    /// - Proper restoration of the previous current file
    ///
    /// # Arguments
    /// * `path` - The path to the file to execute
    ///
    /// # Returns
    /// * `Ok(Object)` - The result of executing the file (or Nil if already loaded)
    /// * `Err(MetorexError)` - If loading, parsing, or execution fails
    pub fn execute_file(&mut self, path: &std::path::Path) -> Result<Object, MetorexError> {
        use crate::error::SourceLocation;
        use crate::file_loader::{find_file_path, load_file_source, parse_file};

        // Find the actual file path (with extension auto-detection)
        let actual_path = find_file_path(path).map_err(|e| {
            MetorexError::runtime_error(
                format!("Failed to find file '{}': {}", path.display(), e),
                SourceLocation::new(0, 0, 0),
            )
        })?;

        // Canonicalize the file path to absolute path for proper deduplication
        let canonical_path = actual_path.canonicalize().map_err(|e| {
            MetorexError::runtime_error(
                format!(
                    "Failed to canonicalize file path '{}': {}",
                    actual_path.display(),
                    e
                ),
                SourceLocation::new(0, 0, 0),
            )
        })?;

        // Check if file is already loaded (deduplication)
        if self.is_file_loaded(&canonical_path) {
            return Ok(Object::Nil);
        }

        // Mark file as loaded before executing to prevent circular dependencies
        self.mark_file_loaded(canonical_path.clone());

        // Save the current file path to restore later
        let previous_file = self.current_file.clone();

        // Load file source with error context
        let source = load_file_source(&canonical_path).map_err(|e| {
            MetorexError::runtime_error(
                format!("Failed to load file '{}': {}", canonical_path.display(), e),
                SourceLocation::new(0, 0, 0),
            )
        })?;

        // Parse file with error context
        let statements = parse_file(&source, &canonical_path.to_string_lossy()).map_err(|e| {
            MetorexError::runtime_error(
                format!("Failed to parse file '{}': {}", canonical_path.display(), e),
                SourceLocation::new(0, 0, 0),
            )
        })?;

        // Update current file path for require_relative calls within this file
        self.set_current_file(canonical_path.clone());

        // Execute the parsed statements
        let result = self.execute_program(&statements).map_err(|e| {
            MetorexError::runtime_error(
                format!("Error executing file '{}': {}", canonical_path.display(), e),
                SourceLocation::new(0, 0, 0),
            )
        })?;

        // Restore previous current file path
        self.current_file = previous_file;

        // Return the result or Nil if no return value
        Ok(result.unwrap_or(Object::Nil))
    }

    /// Evaluate an expression to a runtime value.
    pub(crate) fn evaluate_expression(
        &mut self,
        expression: &Expression,
    ) -> Result<Object, MetorexError> {
        match expression {
            Expression::IntLiteral { value, .. } => Ok(Object::Int(*value)),
            Expression::FloatLiteral { value, .. } => Ok(Object::Float(*value)),
            Expression::StringLiteral { value, .. } => Ok(Object::String(Rc::new(value.clone()))),
            Expression::Symbol { value, .. } => Ok(Object::Symbol(Rc::new(value.clone()))),
            Expression::InterpolatedString { parts, .. } => self
                .evaluate_interpolated_string(parts)
                .map(|s| Object::String(Rc::new(s))),
            Expression::BoolLiteral { value, .. } => Ok(Object::Bool(*value)),
            Expression::NilLiteral { .. } => Ok(Object::Nil),
            Expression::Identifier { name, position } => self
                .environment
                .get(name)
                .ok_or_else(|| undefined_variable_error(name, *position)),
            Expression::Lambda {
                parameters,
                body,
                captured_vars,
                ..
            } => {
                let mut captured = HashMap::new();
                if let Some(names) = captured_vars {
                    if names.is_empty() {
                        // Empty vec signals automatic capture of all current scope variables
                        //  This is used for true lambdas (lambda do ... end, arrow syntax)
                        captured = self.environment().current_scope_var_refs();
                    } else {
                        // Explicit list of variables to capture
                        for name in names {
                            if let Some(value_ref) = self.environment().get_ref(name) {
                                captured.insert(name.clone(), value_ref);
                            }
                        }
                    }
                }
                // If captured_vars is None, don't capture anything (regular blocks for .each, etc.)
                let block = BlockStatement::new(parameters.clone(), body.clone(), captured);
                Ok(Object::Block(Rc::new(block)))
            }
            Expression::Grouped { expression, .. } => self.evaluate_expression(expression),
            Expression::UnaryOp {
                op,
                operand,
                position,
            } => {
                let value = self.evaluate_expression(operand)?;
                self.evaluate_unary_operation(op, value, *position)
            }
            Expression::BinaryOp {
                op,
                left,
                right,
                position,
            } => {
                // Short-circuit evaluation for logical operators
                match op {
                    BinaryOp::And => {
                        let left_value = self.evaluate_expression(left)?;
                        return if !is_truthy(&left_value) {
                            Ok(left_value)
                        } else {
                            self.evaluate_expression(right)
                        };
                    }
                    BinaryOp::Or => {
                        let left_value = self.evaluate_expression(left)?;
                        return if is_truthy(&left_value) {
                            Ok(left_value)
                        } else {
                            self.evaluate_expression(right)
                        };
                    }
                    _ => {}
                }
                let left_value = self.evaluate_expression(left)?;
                let right_value = self.evaluate_expression(right)?;
                // Check for user-defined operator methods on instances
                if let (Some(op_name), Object::Instance(instance_rc)) =
                    (binary_op_method_name(op), &left_value)
                {
                    let class = Rc::clone(&instance_rc.borrow().class);
                    if let Some(method) = class.find_method(op_name) {
                        return self.invoke_method(
                            class,
                            method,
                            left_value.clone(),
                            vec![right_value],
                            *position,
                        );
                    }
                }
                self.evaluate_binary_operation(op, left_value, right_value, *position)
            }
            Expression::Array { elements, .. } => self.evaluate_array_literal(elements),
            Expression::Dictionary { entries, .. } => self.evaluate_dictionary_literal(entries),
            Expression::Index {
                array,
                index,
                position,
            } => {
                let collection = self.evaluate_expression(array)?;
                let key = self.evaluate_expression(index)?;
                // Check for user-defined [] method on instances
                if let Object::Instance(instance_rc) = &collection {
                    let class = Rc::clone(&instance_rc.borrow().class);
                    if let Some(method) = class.find_method("[]") {
                        return self.invoke_method(
                            class,
                            method,
                            collection.clone(),
                            vec![key],
                            *position,
                        );
                    }
                }
                self.evaluate_index_operation(collection, key, *position)
            }
            Expression::MethodCall {
                receiver,
                method,
                arguments,
                trailing_block,
                position,
            } => self.evaluate_method_call(
                receiver,
                method,
                arguments,
                trailing_block.as_ref().map(|b| b.as_ref()),
                *position,
            ),
            Expression::Call {
                callee,
                arguments,
                trailing_block,
                position,
            } => {
                let callable = self.evaluate_expression(callee)?;
                let mut evaluated_args = Vec::with_capacity(arguments.len());
                for argument in arguments {
                    evaluated_args.push(self.evaluate_expression(argument)?);
                }
                if let Some(block_expr) = trailing_block {
                    self.pending_block = Some(self.evaluate_expression(block_expr)?);
                }
                self.invoke_callable(callable, evaluated_args, *position)
            }
            Expression::SelfExpr { position } => self
                .environment
                .get("self")
                .ok_or_else(|| undefined_self_error(*position)),
            Expression::InstanceVariable { name, position } => {
                // Instance variables can only be read within a method (where 'self' is defined)
                match self.environment.get("self") {
                    Some(Object::Instance(instance_rc)) => {
                        let instance = instance_rc.borrow();
                        Ok(instance.get_var(name).cloned().unwrap_or(Object::Nil))
                    }
                    Some(_) => Err(MetorexError::runtime_error(
                        format!("Cannot read instance variable @{} on non-instance", name),
                        position_to_location(*position),
                    )),
                    None => Err(MetorexError::runtime_error(
                        format!(
                            "Instance variable @{} can only be used within a method",
                            name
                        ),
                        position_to_location(*position),
                    )),
                }
            }
            Expression::GlobalVariable { name, .. } => {
                Ok(self.globals.get(name).unwrap_or(Object::Nil))
            }
            Expression::ClassVariable { name, position } => {
                // Class variables can be read within a method or class context
                match self.environment.get("self") {
                    Some(Object::Instance(instance_rc)) => {
                        let instance = instance_rc.borrow();
                        Ok(instance.class.get_class_var(name).unwrap_or(Object::Nil))
                    }
                    Some(Object::Class(class)) => {
                        Ok(class.get_class_var(name).unwrap_or(Object::Nil))
                    }
                    Some(_) => Err(MetorexError::runtime_error(
                        format!("Cannot read class variable @@{} in this context", name),
                        position_to_location(*position),
                    )),
                    None => Err(MetorexError::runtime_error(
                        format!(
                            "Class variable @@{} can only be used within a class or method",
                            name
                        ),
                        position_to_location(*position),
                    )),
                }
            }
            Expression::Super {
                arguments,
                position,
            } => {
                // Get the current self (must be an instance)
                let instance = match self.environment.get("self") {
                    Some(Object::Instance(instance_rc)) => instance_rc,
                    Some(_) => {
                        return Err(MetorexError::runtime_error(
                            "super can only be called from within an instance method".to_string(),
                            position_to_location(*position),
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "super can only be called from within a method".to_string(),
                            position_to_location(*position),
                        ));
                    }
                };

                // Get the current method name from the call stack
                // The call stack stores method names as "Class#method", so we need to extract both parts
                let current_frame = self.get_current_method_name().ok_or_else(|| {
                    MetorexError::runtime_error(
                        "super called outside of a method context".to_string(),
                        position_to_location(*position),
                    )
                })?;

                // Extract the class name and method name (format: "Class#method")
                let (class_name, method_name) = if let Some(pos) = current_frame.rfind('#') {
                    (&current_frame[..pos], &current_frame[pos + 1..])
                } else {
                    return Err(MetorexError::runtime_error(
                        "super called in invalid context (no class information)".to_string(),
                        position_to_location(*position),
                    ));
                };

                // Get the instance's class to walk the inheritance chain
                let instance_borrowed = instance.borrow();
                let instance_class = &instance_borrowed.class;

                // Find the class that matches the current frame's class name
                let mut current_class = Some(Rc::clone(instance_class));
                let defining_class = loop {
                    match current_class {
                        Some(ref class) if class.name() == class_name => {
                            break Some(Rc::clone(class));
                        }
                        Some(ref class) => {
                            current_class = class.superclass();
                        }
                        None => break None,
                    }
                };

                let defining_class = defining_class.ok_or_else(|| {
                    MetorexError::runtime_error(
                        format!(
                            "Could not find defining class '{}' in inheritance chain",
                            class_name
                        ),
                        position_to_location(*position),
                    )
                })?;

                // Get the parent class of the defining class
                let parent_class = defining_class.superclass().ok_or_else(|| {
                    MetorexError::runtime_error(
                        format!("Class {} has no superclass", class_name),
                        position_to_location(*position),
                    )
                })?;

                // Look up the method in the parent class
                let method = parent_class.find_method(method_name).ok_or_else(|| {
                    MetorexError::runtime_error(
                        format!(
                            "Superclass {} does not define method '{}'",
                            parent_class.name(),
                            method_name
                        ),
                        position_to_location(*position),
                    )
                })?;

                // Evaluate the arguments
                let mut evaluated_args = Vec::with_capacity(arguments.len());
                for arg in arguments {
                    evaluated_args.push(self.evaluate_expression(arg)?);
                }

                // Drop the borrow before invoking the method
                drop(instance_borrowed);

                // Invoke the parent method with self as the receiver
                self.invoke_method(
                    parent_class,
                    method,
                    Object::Instance(Rc::clone(&instance)),
                    evaluated_args,
                    *position,
                )
            }
            Expression::Range {
                start,
                end,
                exclusive,
                ..
            } => {
                let start_value = self.evaluate_expression(start)?;
                let end_value = self.evaluate_expression(end)?;
                Ok(Object::Range {
                    start: Box::new(start_value),
                    end: Box::new(end_value),
                    exclusive: *exclusive,
                })
            }
            Expression::Case {
                expression,
                cases,
                else_case,
                position,
            } => {
                // This will be implemented in Phase 3
                // For now, delegate to the pattern matching module
                self.evaluate_case_expression(expression, cases, else_case.as_deref(), *position)
            }
            Expression::ScopeResolution {
                namespace,
                name,
                position,
            } => {
                let ns_value = self.evaluate_expression(namespace)?;
                match ns_value {
                    Object::Class(class_rc) => class_rc.get_class_var(name).ok_or_else(|| {
                        MetorexError::runtime_error(
                            format!("Uninitialized constant {}::{}", class_rc.name(), name),
                            position_to_location(*position),
                        )
                    }),
                    _ => Err(MetorexError::runtime_error(
                        "'::' scope resolution requires a class or module as namespace".to_string(),
                        position_to_location(*position),
                    )),
                }
            }

            Expression::If {
                condition,
                then_branch,
                elsif_branches,
                else_branch,
                ..
            } => self.evaluate_if_expression(condition, then_branch, elsif_branches, else_branch),

            Expression::Unless {
                condition,
                then_branch,
                else_branch,
                ..
            } => self.evaluate_unless_expression(condition, then_branch, else_branch),
        }
    }
}

impl Default for VirtualMachine {
    fn default() -> Self {
        Self::new()
    }
}

/// Map a binary operator to its operator method name for user-defined dispatch.
fn binary_op_method_name(op: &BinaryOp) -> Option<&'static str> {
    match op {
        BinaryOp::Add => Some("+"),
        BinaryOp::Subtract => Some("-"),
        BinaryOp::Multiply => Some("*"),
        BinaryOp::Divide => Some("/"),
        BinaryOp::Modulo => Some("%"),
        BinaryOp::Equal => Some("=="),
        BinaryOp::NotEqual => Some("!="),
        BinaryOp::Less => Some("<"),
        BinaryOp::Greater => Some(">"),
        BinaryOp::LessEqual => Some("<="),
        BinaryOp::GreaterEqual => Some(">="),
        _ => None,
    }
}

//! Error construction functions for the Metorex virtual machine.
//!
//! This module provides helper functions for constructing various runtime, type,
//! and internal errors that can occur during VM execution.

use super::utils::position_to_location;
use crate::ast::{BinaryOp, Expression, Statement, UnaryOp};
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;

// ============================================================================
// Control Flow Errors
// ============================================================================

/// Produce a runtime error for unsupported control-flow usage (e.g., break outside loop).
pub(super) fn loop_control_error(keyword: &str, position: Position) -> MetorexError {
    MetorexError::runtime_error(
        format!("{keyword} cannot be used outside of a loop"),
        position_to_location(position),
    )
}

// ============================================================================
// Variable and Assignment Errors
// ============================================================================

/// Produce a runtime error when attempting to assign to an invalid target.
pub(super) fn invalid_assignment_target_error(target: &Expression) -> MetorexError {
    MetorexError::runtime_error(
        "Invalid assignment target",
        position_to_location(target.position()),
    )
}

/// Produce a runtime error for referencing an undefined variable.
pub(super) fn undefined_variable_error(name: &str, position: Position) -> MetorexError {
    MetorexError::runtime_error(
        format!("Undefined variable '{name}'"),
        position_to_location(position),
    )
}

/// Produce a runtime error when accessing `self` outside of a method context.
pub(super) fn undefined_self_error(position: Position) -> MetorexError {
    MetorexError::runtime_error(
        "Undefined self in current context",
        position_to_location(position),
    )
}

// ============================================================================
// Method and Callable Errors
// ============================================================================

/// Produce a runtime error when invoking an undefined method on a receiver.
pub(super) fn undefined_method_error(
    method: &str,
    receiver: &Object,
    position: Position,
) -> MetorexError {
    MetorexError::runtime_error(
        format!(
            "Undefined method '{}' for type '{}'",
            method,
            receiver.type_name()
        ),
        position_to_location(position),
    )
}

/// Produce a runtime error when a method receives the wrong number of arguments.
pub(super) fn method_argument_error(
    method: &str,
    expected: usize,
    found: usize,
    position: Position,
) -> MetorexError {
    MetorexError::runtime_error(
        format!(
            "Method '{}' expected {} argument(s) but received {}",
            method, expected, found
        ),
        position_to_location(position),
    )
}

/// Produce a type error for invalid method argument type.
pub(super) fn method_argument_type_error(
    method: &str,
    expected: &str,
    found: &Object,
    position: Position,
) -> MetorexError {
    MetorexError::type_error(
        format!(
            "Method '{}' expected argument of type '{}' but found '{}'",
            method,
            expected,
            found.type_name()
        ),
        position_to_location(position),
    )
}

/// Produce a runtime error when attempting to call a non-callable object.
pub(super) fn not_callable_error(value: &Object, position: Position) -> MetorexError {
    MetorexError::runtime_error(
        format!("Object of type '{}' is not callable", value.type_name()),
        position_to_location(position),
    )
}

/// Produce a runtime error when a callable receives the wrong number of arguments.
pub(super) fn callable_argument_error(
    callable_name: &str,
    expected: usize,
    found: usize,
    position: Position,
) -> MetorexError {
    MetorexError::runtime_error(
        format!(
            "Callable '{}' expected {} argument(s) but received {}",
            callable_name, expected, found
        ),
        position_to_location(position),
    )
}

// ============================================================================
// Operator Errors
// ============================================================================

/// Produce a type error for unary operations.
pub(super) fn unary_type_error(op: &UnaryOp, value: &Object, position: Position) -> MetorexError {
    MetorexError::type_error(
        format!(
            "Cannot apply unary operator '{:?}' to type '{}'",
            op,
            value.type_name()
        ),
        position_to_location(position),
    )
}

/// Produce a type error for binary operations.
pub(super) fn binary_type_error(
    op: BinaryOp,
    left: &Object,
    right: &Object,
    position: Position,
) -> MetorexError {
    MetorexError::type_error(
        format!(
            "Cannot apply operator '{:?}' to types '{}' and '{}'",
            op,
            left.type_name(),
            right.type_name()
        ),
        position_to_location(position),
    )
}

/// Produce a divide-by-zero runtime error.
pub(super) fn divide_by_zero_error(position: Position) -> MetorexError {
    MetorexError::runtime_error("Division by zero", position_to_location(position))
}

// ============================================================================
// Indexing and Collection Errors
// ============================================================================

/// Produce an index out of bounds runtime error.
pub(super) fn index_out_of_bounds_error(
    index: i64,
    length: usize,
    position: Position,
) -> MetorexError {
    MetorexError::runtime_error(
        format!(
            "Index {} is out of bounds for array of length {}",
            index, length
        ),
        position_to_location(position),
    )
}

/// Produce a runtime error when a dictionary key is missing.
pub(super) fn undefined_dictionary_key_error(key: &str, position: Position) -> MetorexError {
    MetorexError::runtime_error(
        format!("Key '{}' not found in dictionary", key),
        position_to_location(position),
    )
}

