// Internal Errors
// ============================================================================

/// Produce an internal error for statements that are not yet implemented.
pub(super) fn unimplemented_statement_error(statement: &Statement) -> MetorexError {
    MetorexError::internal_error(format!(
        "Statement execution not implemented for {:?}",
        statement
    ))
}

// Exception handling for the Metorex VM.
// This module handles raise and begin/rescue/else/ensure blocks.

use super::ControlFlow;
use super::core::VirtualMachine;
use super::utils::*;

use crate::ast::Statement;
use crate::class::Class;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute a raise statement to throw an exception.
    pub(crate) fn execute_raise(
        &mut self,
        exception: &Option<crate::ast::Expression>,
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        let exception_obj = if let Some(expr) = exception {
            // Evaluate the exception expression
            let value = self.evaluate_expression(expr)?;

            // If it's already an Exception object, use it directly
            // If it's a String, create a RuntimeError exception
            // If it's a Class (exception class), instantiate it
            match value {
                Object::Exception(_) => value,
                Object::String(message) => {
                    // Create a RuntimeError exception with the string message
                    Object::exception("RuntimeError", (*message).clone())
                }
                Object::Class(class) => {
                    // Instantiate the exception class with an empty message
                    Object::exception(class.name(), String::new())
                }
                _ => {
                    return Err(MetorexError::runtime_error(
                        "Exception must be an Exception object, String, or exception class"
                            .to_string(),
                        position_to_location(position),
                    ));
                }
            }
        } else {
            // Bare raise - re-raise current exception
            // For now, we'll check if there's a $! variable (current exception)
            // If not, it's an error to use bare raise outside a rescue block
            match self.environment().get("$!") {
                Some(Object::Exception(_)) => self.environment().get("$!").unwrap(),
                _ => {
                    return Err(MetorexError::runtime_error(
                        "No exception to re-raise (bare raise only allowed in rescue blocks)"
                            .to_string(),
                        position_to_location(position),
                    ));
                }
            }
        };

        // Capture stack trace and add source location to exception
        let exception_obj = self.add_stack_trace_to_exception(exception_obj, position);

        Ok(ControlFlow::Exception {
            exception: exception_obj,
            position,
        })
    }

    /// Add stack trace and source location to an exception object
    fn add_stack_trace_to_exception(&self, exception: Object, position: Position) -> Object {
        if let Object::Exception(exc_ref) = exception {
            let mut exc = exc_ref.borrow_mut();

            // Add source location if not already set
            if exc.location.is_none() {
                exc.location = Some(crate::object::SourceLocation::new(
                    "script".to_string(),
                    position.line,
                    position.column,
                ));
            }

            // Generate stack trace from call stack
            let backtrace: Vec<String> = self
                .call_stack()
                .iter()
                .map(|frame| {
                    if let Some(loc) = frame.location() {
                        format!("  at {} ({})", frame.name(), loc)
                    } else {
                        format!("  at {}", frame.name())
                    }
                })
                .collect();

            // Add current position to backtrace
            let mut full_backtrace = vec![format!("  at {}:{}", position.line, position.column)];
            full_backtrace.extend(backtrace);

            exc.backtrace = Some(full_backtrace);

            drop(exc); // Release the borrow before returning
            Object::Exception(exc_ref)
        } else {
            exception
        }
    }

    /// Execute a begin/rescue/else/ensure block.
    pub(crate) fn execute_begin(
        &mut self,
        body: &[Statement],
        rescue_clauses: &[crate::ast::RescueClause],
        else_clause: &Option<Vec<Statement>>,
        ensure_block: &Option<Vec<Statement>>,
        _position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        // Execute the try block
        let body_result = self.execute_statements_internal(body);

        // Track whether an exception was handled
        let mut handled_exception = false;
        let mut final_result = body_result;

        // Convert UncaughtException errors to ControlFlow::Exception
        if let Err(MetorexError::UncaughtException {
            exception,
            location,
            ..
        }) = &final_result
        {
            final_result = Ok(ControlFlow::Exception {
                exception: exception.clone(),
                position: Position {
                    line: location.line,
                    column: location.column,
                    offset: 0,
                },
            });
        }

        // If an exception occurred, try to match rescue clauses
        if let Ok(ControlFlow::Exception {
            exception,
            position: _ex_pos,
        }) = &final_result
        {
            // Store the current exception in $! for access in rescue blocks
            self.environment_mut()
                .define("$!".to_string(), exception.clone());

            // Try each rescue clause in order
            for rescue_clause in rescue_clauses {
                if self.exception_matches(exception, &rescue_clause.exception_types)? {
                    // Bind exception to variable if specified (=> e)
                    if let Some(var_name) = &rescue_clause.variable_name {
                        self.environment_mut()
                            .define(var_name.clone(), exception.clone());
                    }

                    // Execute the rescue block
                    final_result = self.execute_statements_internal(&rescue_clause.body);
                    handled_exception = true;
                    break;
                }
            }

            // If exception wasn't handled, it will propagate
            if !handled_exception {
                // Keep the exception result to propagate it
                // Don't execute else clause
            } else {
                // Clear the $! variable since exception was handled
                self.environment_mut().define("$!".to_string(), Object::Nil);
            }
        } else if final_result.is_ok() && matches!(final_result, Ok(ControlFlow::Next)) {
            // No exception occurred - execute else clause if present
            if let Some(else_stmts) = else_clause {
                final_result = self.execute_statements_internal(else_stmts);
            }
        }

        // Always execute ensure block, regardless of what happened
        if let Some(ensure_stmts) = ensure_block {
            let ensure_result = self.execute_statements_internal(ensure_stmts);

            // If ensure block raises an exception or changes control flow,
            // it overrides the previous result
            match ensure_result {
                Ok(ControlFlow::Exception { .. }) => {
                    final_result = ensure_result;
                }
                Ok(ControlFlow::Next) => {
                    // Ensure completed normally, don't override final_result
                }
                Ok(_) => {
                    // Other control flow (return, break, continue)
                    final_result = ensure_result;
                }
                Err(_) => {
                    // Error in ensure block overrides previous result
                    final_result = ensure_result;
                }
            }
        }

        final_result
    }

    /// Check if an exception matches the given exception type list.
    pub(crate) fn exception_matches(
        &self,
        exception: &Object,
        exception_types: &[String],
    ) -> Result<bool, MetorexError> {
        // Empty exception_types list means catch all exceptions
        if exception_types.is_empty() {
            return Ok(true);
        }

        // Get the exception's type name
        let exception_type_name = match exception {
            Object::Exception(ex) => ex.borrow().exception_type.clone(),
            _ => return Ok(false),
        };

        // Check if the exception's type matches any of the specified types
        for type_name in exception_types {
            // Look up the exception type class in the environment
            if let Some(Object::Class(target_class)) = self.environment().get(type_name) {
                // Get the class for this exception type
                if let Some(Object::Class(exception_class)) =
                    self.environment().get(&exception_type_name)
                {
                    // Check if exception_class is the target_class or a subclass of it
                    if Self::is_class_or_subclass(&exception_class, &target_class) {
                        return Ok(true);
                    }
                }
            }
        }

        Ok(false)
    }

    /// Check if a class is the same as or a subclass of another class.
    pub(crate) fn is_class_or_subclass(class: &Rc<Class>, target: &Rc<Class>) -> bool {
        if Rc::ptr_eq(class, target) {
            return true;
        }

        // Check superclass chain
        if let Some(superclass) = class.superclass() {
            return Self::is_class_or_subclass(&superclass, target);
        }

        false
    }
}

//! Expression evaluation functions for the Metorex VM.
//!
//! This module contains the core logic for evaluating expressions including:
//! - Interpolated strings
//! - Array literals
//! - Dictionary literals
//! - Index operations (array/dictionary access)

use crate::ast::node::ElsifBranch;
use crate::ast::{Expression, InterpolationPart, Statement};
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use super::core::VirtualMachine;
use super::errors::{index_out_of_bounds_error, undefined_dictionary_key_error};
use super::utils::{format_exception, is_truthy, object_to_dict_key, position_to_location};

impl VirtualMachine {
    /// Evaluate string interpolation parts into a single owned string.
    pub(crate) fn evaluate_interpolated_string(
        &mut self,
        parts: &[InterpolationPart],
    ) -> Result<String, MetorexError> {
        let mut buffer = String::new();

        for part in parts {
            match part {
                InterpolationPart::Text(text) => buffer.push_str(text),
                InterpolationPart::Expression(expr) => {
                    let value = self.evaluate_expression(expr)?;
                    buffer.push_str(&value.to_string());
                }
            }
        }

        Ok(buffer)
    }

    /// Evaluate array literal expressions.
    pub(crate) fn evaluate_array_literal(
        &mut self,
        elements: &[Expression],
    ) -> Result<Object, MetorexError> {
        let mut evaluated = Vec::with_capacity(elements.len());
        for element in elements {
            evaluated.push(self.evaluate_expression(element)?);
        }
        Ok(Object::Array(Rc::new(RefCell::new(evaluated))))
    }

    /// Evaluate dictionary literal expressions.
    pub(crate) fn evaluate_dictionary_literal(
        &mut self,
        entries: &[(Expression, Expression)],
    ) -> Result<Object, MetorexError> {
        let mut map = HashMap::with_capacity(entries.len());

        for (key_expr, value_expr) in entries {
            let key_value = self.evaluate_expression(key_expr)?;
            let key_string = object_to_dict_key(&key_value).ok_or_else(|| {
                MetorexError::type_error(
                    format!(
                        "Dictionary keys must be String, Symbol, Integer, Float, Bool, or Nil, found {}",
                        key_value.type_name()
                    ),
                    position_to_location(key_expr.position()),
                )
            })?;

            let value = self.evaluate_expression(value_expr)?;
            map.insert(key_string, value);
        }

        Ok(Object::Dict(Rc::new(RefCell::new(map))))
    }

    /// Evaluate indexing operations on arrays and dictionaries.
    pub(crate) fn evaluate_index_operation(
        &self,
        collection: Object,
        key: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match collection {
            Object::Array(elements_rc) => match key {
                Object::Int(index) => {
                    let elements = elements_rc.borrow();
                    if index < 0 || (index as usize) >= elements.len() {
                        Err(index_out_of_bounds_error(index, elements.len(), position))
                    } else {
                        Ok(elements[index as usize].clone())
                    }
                }
                _ => Err(MetorexError::type_error(
                    format!("Array index must be an Integer, found {}", key.type_name()),
                    position_to_location(position),
                )),
            },
            Object::Dict(dict_rc) => {
                let key_string = object_to_dict_key(&key).ok_or_else(|| {
                    MetorexError::type_error(
                        format!(
                            "Dictionary index must be String, Symbol, Integer, Float, Bool, or Nil, found {}",
                            key.type_name()
                        ),
                        position_to_location(position),
                    )
                })?;

                let dict = dict_rc.borrow();
                dict.get(&key_string)
                    .cloned()
                    .ok_or_else(|| undefined_dictionary_key_error(&key_string, position))
            }

            other => Err(MetorexError::type_error(
                format!("Cannot index into type '{}'", other.type_name()),
                position_to_location(position),
            )),
        }
    }

    /// Evaluate an if expression, returning the value of the matching branch.
    pub(crate) fn evaluate_if_expression(
        &mut self,
        condition: &Expression,
        then_branch: &[Statement],
        elsif_branches: &[ElsifBranch],
        else_branch: &Option<Vec<Statement>>,
    ) -> Result<Object, MetorexError> {
        if is_truthy(&self.evaluate_expression(condition)?) {
            return self.evaluate_branch_value(then_branch);
        }
        for elsif in elsif_branches {
            if is_truthy(&self.evaluate_expression(&elsif.condition)?) {
                return self.evaluate_branch_value(&elsif.body);
            }
        }
        if let Some(else_stmts) = else_branch {
            return self.evaluate_branch_value(else_stmts);
        }
        Ok(Object::Nil)
    }

    /// Evaluate an unless expression, returning the value of the matching branch.
    pub(crate) fn evaluate_unless_expression(
        &mut self,
        condition: &Expression,
        then_branch: &[Statement],
        else_branch: &Option<Vec<Statement>>,
    ) -> Result<Object, MetorexError> {
        if !is_truthy(&self.evaluate_expression(condition)?) {
            return self.evaluate_branch_value(then_branch);
        }
        if let Some(else_stmts) = else_branch {
            return self.evaluate_branch_value(else_stmts);
        }
        Ok(Object::Nil)
    }

    /// Execute a list of statements and return the value of the last expression statement.
    fn evaluate_branch_value(&mut self, stmts: &[Statement]) -> Result<Object, MetorexError> {
        use super::ControlFlow;
        self.environment_mut().push_scope();
        let mut last_value = Object::Nil;
        for stmt in stmts {
            if let Statement::Expression { expression, .. } = stmt {
                last_value = self.evaluate_expression(expression)?;
                continue;
            }
            match self.execute_statement(stmt)? {
                ControlFlow::Next => {}
                ControlFlow::Return { value, .. } => {
                    self.environment_mut().pop_scope();
                    return Ok(value);
                }
                ControlFlow::Exception {
                    exception,
                    position,
                } => {
                    self.environment_mut().pop_scope();
                    return Err(MetorexError::UncaughtException {
                        exception: exception.clone(),
                        location: position_to_location(position),
                        message: format_exception(&exception),
                    });
                }
                _ => {
                    // Break/Continue — fall through to pop_scope at end of function
                    break;
                }
            }
        }
        self.environment_mut().pop_scope();
        Ok(last_value)
    }
}

//! Global object registry for the Metorex virtual machine.
//!
//! This module provides a registry that owns global objects accessible throughout the VM,
//! including built-in classes and singleton values.

use crate::object::Object;
use std::collections::HashMap;

/// Registry that owns global objects accessible throughout the VM.
#[derive(Debug, Default)]
pub struct GlobalRegistry {
    objects: HashMap<String, Object>,
}

impl GlobalRegistry {
    /// Create an empty registry.
    pub fn new() -> Self {
        Self::default()
    }

    /// Insert or replace a named global object.
    pub fn set(&mut self, name: impl Into<String>, object: Object) {
        self.objects.insert(name.into(), object);
    }

    /// Fetch a named global object if present.
    pub fn get(&self, name: &str) -> Option<Object> {
        self.objects.get(name).cloned()
    }

    /// Determine whether a name exists in the registry.
    pub fn contains(&self, name: &str) -> bool {
        self.objects.contains_key(name)
    }

    /// Iterator over registered globals (useful for seeding environments).
    pub fn iter(&self) -> impl Iterator<Item = (&String, &Object)> {
        self.objects.iter()
    }
}

//! Heap memory management for the Metorex virtual machine.
//!
//! This module provides a lightweight heap structure that tracks allocated objects.
//! Currently a stub implementation; will be expanded for garbage collection integration.

use crate::object::Object;

/// Lightweight heap placeholder that will evolve with the runtime.
#[derive(Debug, Default)]
pub struct Heap {
    /// Tracks allocated objects for future GC integration.
    allocated: Vec<Object>,
}

impl Heap {
    /// Allocate an object on the heap (no-op stub for now).
    pub fn allocate(&mut self, object: Object) {
        self.allocated.push(object);
    }

    /// Returns number of tracked allocations (for testing/introspection).
    pub fn allocation_count(&self) -> usize {
        self.allocated.len()
    }
}

//! VM initialization functions.
//!
//! This module contains functions for initializing the virtual machine with built-in
//! classes, methods, and global values.

use super::GlobalRegistry;
use crate::builtin_classes::{self, BuiltinClasses};
use crate::environment::Environment;
use crate::object::Object;

/// Initialize built-in methods for core classes.
pub(super) fn initialize_builtin_methods(builtins: &BuiltinClasses) {
    builtin_classes::init_object_methods(builtins.object_class.as_ref());
    builtin_classes::init_string_methods(builtins.string_class.as_ref());
    builtin_classes::init_array_methods(builtins.array_class.as_ref());
    builtin_classes::init_hash_methods(builtins.hash_class.as_ref());
    builtin_classes::init_exception_methods(builtins.exception_class.as_ref());
}

/// Register all built-in classes in the global registry.
pub(super) fn register_builtin_classes(globals: &mut GlobalRegistry, builtins: &BuiltinClasses) {
    for (name, class) in builtins.all_classes() {
        globals.set(name, Object::Class(class));
    }
}

/// Register singleton values (nil, true, false) in the global registry.
pub(super) fn register_singletons(globals: &mut GlobalRegistry) {
    globals.set("nil", Object::Nil);
    globals.set("true", Object::Bool(true));
    globals.set("false", Object::Bool(false));
    // block_given? defaults to false at global scope (no block context)
    globals.set("block_given?", Object::Bool(false));
}

/// Register native functions in the global registry.
pub(super) fn register_native_functions(globals: &mut GlobalRegistry) {
    globals.set("puts", Object::NativeFunction("puts".to_string()));
    globals.set("print", Object::NativeFunction("print".to_string()));
    globals.set("p", Object::NativeFunction("p".to_string()));
    globals.set("gets", Object::NativeFunction("gets".to_string()));
    globals.set("method", Object::NativeFunction("method".to_string()));
    globals.set(
        "require_relative",
        Object::NativeFunction("require_relative".to_string()),
    );
}

/// Seed the environment with values from the global registry.
pub(super) fn seed_environment_with_globals(
    environment: &mut Environment,
    globals: &GlobalRegistry,
) {
    for (name, value) in globals.iter() {
        environment.define(name.clone(), value.clone());
    }
}

//! Method invocation and execution for the virtual machine.
//!
//! This module handles the actual execution of methods and callable objects,
//! including scope management and control flow handling.

use super::errors::*;
use super::utils::*;
use super::{CallFrame, ControlFlow, VirtualMachine};
use crate::ast::{Expression, Statement};
use crate::callable::Callable;
use crate::class::Class;
use crate::error::{MetorexError, StackFrame};
use crate::lexer::Position;
use crate::object::{BlockStatement, Method, Object};
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

impl VirtualMachine {
    /// Invoke a resolved method with evaluated arguments.
    pub(crate) fn invoke_callable(
        &mut self,
        callable: Object,
        arguments: Vec<Object>,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match callable {
            Object::Block(block) => block.call(self, arguments, position),
            Object::Method(method) => {
                // Call standalone function (represented as Method object)
                // Validate positional argument count (kwargs dict doesn't count)
                let expected = method.parameters.len();
                let positional_count = positional_arg_count(&arguments);
                if expected != positional_count {
                    return Err(method_argument_error(
                        &method.name,
                        expected,
                        positional_count,
                        position,
                    ));
                }
                // Execute function body without self
                self.execute_function_body(&method, arguments)
            }
            Object::Class(class) => {
                // Check if this is an exception class
                let is_exception_class = self.is_exception_class(&class);

                if is_exception_class {
                    // Create an Exception object instead of a regular Instance
                    let message = if arguments.is_empty() {
                        String::new()
                    } else if arguments.len() == 1 {
                        // Extract message from first argument
                        match &arguments[0] {
                            Object::String(s) => (**s).clone(),
                            other => format!("{:?}", other),
                        }
                    } else {
                        return Err(MetorexError::runtime_error(
                            format!(
                                "Exception.new takes 0 or 1 argument, got {}",
                                arguments.len()
                            ),
                            position_to_location(position),
                        ));
                    };

                    let exception_obj = Object::exception(class.name(), message);
                    Ok(exception_obj)
                } else {
                    // Create a new instance of the class
                    let instance = Rc::new(RefCell::new(crate::object::Instance::new(Rc::clone(
                        &class,
                    ))));
                    let instance_obj = Object::Instance(Rc::clone(&instance));

                    // Look for an 'initialize' method and call it if present
                    if let Some(init_method) = class.find_method("initialize") {
                        self.invoke_method(
                            class,
                            init_method,
                            instance_obj.clone(),
                            arguments,
                            position,
                        )?;
                    } else if !arguments.is_empty() {
                        // If no initialize method exists, reject non-empty arguments
                        return Err(MetorexError::runtime_error(
                            format!(
                                "No initialize method defined, but {} argument(s) provided",
                                arguments.len()
                            ),
                            position_to_location(position),
                        ));
                    }

                    Ok(instance_obj)
                }
            }
            Object::NativeFunction(name) => self.call_native_function(&name, arguments, position),
            other => Err(not_callable_error(&other, position)),
        }
    }

    /// Execute a block callable within the VM, handling scope capture and return semantics.
    pub(crate) fn execute_block_callable(
        &mut self,
        block: &BlockStatement,
        arguments: Vec<Object>,
        position: Position,
    ) -> Result<Object, MetorexError> {
        let expected = block.arity();
        let found = arguments.len();

        if expected != found {
            return Err(callable_argument_error(
                block.name(),
                expected,
                found,
                position,
            ));
        }

        let frame_name = block.name().to_string();
        let frame_location = position_to_location(position);
        let frame_location_string = Some(format!("{}", frame_location));

        let execution_result = self.with_call_frame(
            CallFrame::new(frame_name.clone(), frame_location_string),
            move |vm| vm.execute_block_body(block, arguments),
        );

        match execution_result {
            Ok(value) => Ok(value),
            Err(error) => Err(error.with_stack_frame(StackFrame::new(frame_name, frame_location))),
        }
    }

    /// Execute the statements inside a block object with its captured scope.
    pub(crate) fn execute_block_body(
        &mut self,
        block: &BlockStatement,
        arguments: Vec<Object>,
    ) -> Result<Object, MetorexError> {
        self.environment_mut().push_scope();

        let result = (|| -> Result<Object, MetorexError> {
            // Define captured variables using shared references
            for (name, value_ref) in block.captured_vars() {
                self.environment_mut()
                    .define_shared(name.clone(), value_ref.clone());
            }

            // Define parameters as regular variables
            for (param, argument) in block.parameters().iter().zip(arguments.into_iter()) {
                self.environment_mut().define(param.clone(), argument);
            }

            let mut last_value = Object::Nil;

            for statement in block.body() {
                if let Statement::Expression { expression, .. } = statement {
                    last_value = self.evaluate_expression(expression)?;
                    continue;
                }

                match self.execute_statement(statement)? {
                    ControlFlow::Next => {}
                    ControlFlow::Return { value, .. } => {
                        last_value = value;
                        break;
                    }
                    ControlFlow::Exception {
                        exception,
                        position,
                    } => {
                        return Err(MetorexError::UncaughtException {
                            exception: exception.clone(),
                            location: position_to_location(position),
                            message: format_exception(&exception),
                        });
                    }
                    ControlFlow::Break { position } => {
                        return Err(loop_control_error("break", position));
                    }
                    ControlFlow::Continue { position } => {
                        return Err(loop_control_error("continue", position));
                    }
                }
            }

            Ok(last_value)
        })();

        self.environment_mut().pop_scope();
        result
    }

    /// Execute a block body and return ControlFlow (for use in iterators like .each)
    /// This version propagates Break/Continue instead of converting them to errors
    pub(crate) fn execute_block_with_control_flow(
        &mut self,
        block: &BlockStatement,
        arguments: Vec<Object>,
    ) -> Result<ControlFlow, MetorexError> {
        self.environment_mut().push_scope();

        let result = (|| -> Result<ControlFlow, MetorexError> {
            // Define captured variables using shared references
            for (name, value_ref) in block.captured_vars() {
                self.environment_mut()
                    .define_shared(name.clone(), value_ref.clone());
            }

            // Define parameters as regular variables
            for (param, argument) in block.parameters().iter().zip(arguments.into_iter()) {
                self.environment_mut().define(param.clone(), argument);
            }

            for statement in block.body() {
                match self.execute_statement(statement)? {
                    ControlFlow::Next => {}
                    flow @ (ControlFlow::Return { .. }
                    | ControlFlow::Break { .. }
                    | ControlFlow::Continue { .. }
                    | ControlFlow::Exception { .. }) => {
                        return Ok(flow);
                    }
                }
            }

            Ok(ControlFlow::Next)
        })();

        self.environment_mut().pop_scope();
        result
    }

    /// Invoke a resolved method with evaluated arguments.
    pub(crate) fn invoke_method(
        &mut self,
        class: Rc<Class>,
        method: Rc<Method>,
        receiver: Object,
        arguments: Vec<Object>,
        position: Position,
    ) -> Result<Object, MetorexError> {
        let method_name = method.name.clone();

        if let Some(result) = self.call_native_method(
            class.as_ref(),
            &receiver,
            &method_name,
            &arguments,
            position,
        )? {
            return Ok(result);
        }

        let expected = method.parameters.len();
        let positional_count = positional_arg_count(&arguments);
        if expected != positional_count {
            return Err(method_argument_error(
                &method_name,
                expected,
                positional_count,
                position,
            ));
        }

        let frame_name = format!("{}#{}", class.name(), method_name);
        let frame_location = position_to_location(position);
        let frame_location_string = Some(format!("{}", frame_location));

        let method_for_body = Rc::clone(&method);
        let self_for_body = method
            .receiver()
            .cloned()
            .unwrap_or_else(|| receiver.clone());
        let arguments_for_body = arguments.clone();
        let execution_result = self.with_call_frame(
            CallFrame::new(frame_name.clone(), frame_location_string),
            move |vm| {
                vm.execute_method_body(
                    method_for_body.as_ref(),
                    self_for_body.clone(),
                    arguments_for_body.clone(),
                )
            },
        );

        match execution_result {
            Ok(value) => Ok(value),
            Err(error) => Err(error.with_stack_frame(StackFrame::new(frame_name, frame_location))),
        }
    }

    /// Execute the body of a method within a fresh scope.
    pub(crate) fn execute_method_body(
        &mut self,
        method: &Method,
        self_value: Object,
        arguments: Vec<Object>,
    ) -> Result<Object, MetorexError> {
        self.environment_mut().push_scope();

        // Take the pending block now so nested calls don't see it.
        let block = self.pending_block.take();

        let result = (|| -> Result<Object, MetorexError> {
            self.environment_mut()
                .define("self".to_string(), self_value.clone());

            // Inject captured closure variables (from define_method blocks)
            if let Some(captured) = &method.captured_vars {
                for (name, value_ref) in captured {
                    self.environment_mut()
                        .define_shared(name.clone(), value_ref.clone());
                }
            }

            let (positional, kwargs) = split_keyword_args(arguments);
            for (param, value) in method.parameters.iter().zip(positional.into_iter()) {
                self.environment_mut().define(param.clone(), value);
            }
            self.bind_keyword_params(&method.keyword_parameters, kwargs)?;

            // Bind the block: define block_given? as a Bool, __block__ for internal use,
            // and the named &block parameter if the method declared one.
            self.environment_mut()
                .define("block_given?".to_string(), Object::Bool(block.is_some()));
            if let Some(block_value) = block {
                self.environment_mut()
                    .define("__block__".to_string(), block_value.clone());
                if let Some(block_param) = &method.block_parameter {
                    self.environment_mut()
                        .define(block_param.clone(), block_value);
                }
            }

            // Execute all statements, tracking the last expression value
            let body = method.body();
            let mut last_value = Object::Nil;

            for (i, statement) in body.iter().enumerate() {
                let is_last = i == body.len() - 1;

                // If this is the last statement, capture its value
                if is_last {
                    match statement {
                        Statement::Expression { expression, .. } => {
                            last_value = self.evaluate_expression(expression)?;
                            continue;
                        }
                        Statement::If {
                            condition,
                            then_branch,
                            elsif_branches,
                            else_branch,
                            ..
                        } => {
                            last_value = self.evaluate_if_expression(
                                condition,
                                then_branch,
                                elsif_branches,
                                else_branch,
                            )?;
                            continue;
                        }
                        Statement::Unless {
                            condition,
                            then_branch,
                            else_branch,
                            ..
                        } => {
                            last_value = self.evaluate_unless_expression(
                                condition,
                                then_branch,
                                else_branch,
                            )?;
                            continue;
                        }
                        _ => {}
                    }
                }

                match self.execute_statement(statement)? {
                    ControlFlow::Next => continue,
                    ControlFlow::Return { value, .. } => return Ok(value),
                    ControlFlow::Exception {
                        exception,
                        position,
                    } => {
                        return Err(MetorexError::UncaughtException {
                            exception: exception.clone(),
                            location: position_to_location(position),
                            message: format_exception(&exception),
                        });
                    }
                    ControlFlow::Break { position } => {
                        return Err(loop_control_error("break", position));
                    }
                    ControlFlow::Continue { position } => {
                        return Err(loop_control_error("continue", position));
                    }
                }
            }

            Ok(last_value)
        })();

        self.environment_mut().pop_scope();
        result
    }

    /// Execute the body of a standalone function within a fresh scope (no self).
    pub(crate) fn execute_function_body(
        &mut self,
        function: &Method,
        arguments: Vec<Object>,
    ) -> Result<Object, MetorexError> {
        self.environment_mut().push_scope();

        // Take the pending block now so nested calls don't see it.
        let block = self.pending_block.take();

        let result = (|| -> Result<Object, MetorexError> {
            // Bind parameters to arguments (no self for standalone functions)
            let (positional, kwargs) = split_keyword_args(arguments);
            for (param, value) in function.parameters.iter().zip(positional.into_iter()) {
                self.environment_mut().define(param.clone(), value);
            }
            self.bind_keyword_params(&function.keyword_parameters, kwargs)?;

            // Bind the block: define block_given? as a Bool, __block__ for internal use,
            // and the named &block parameter if the function declared one.
            self.environment_mut()
                .define("block_given?".to_string(), Object::Bool(block.is_some()));
            if let Some(block_value) = block {
                self.environment_mut()
                    .define("__block__".to_string(), block_value.clone());
                if let Some(block_param) = &function.block_parameter {
                    self.environment_mut()
                        .define(block_param.clone(), block_value);
                }
            }

            // Execute all statements, tracking the last expression value
            let body = function.body();
            let mut last_value = Object::Nil;

            for (i, statement) in body.iter().enumerate() {
                let is_last = i == body.len() - 1;

                // If this is the last statement, capture its value
                if is_last {
                    match statement {
                        Statement::Expression { expression, .. } => {
                            last_value = self.evaluate_expression(expression)?;
                            continue;
                        }
                        Statement::If {
                            condition,
                            then_branch,
                            elsif_branches,
                            else_branch,
                            ..
                        } => {
                            last_value = self.evaluate_if_expression(
                                condition,
                                then_branch,
                                elsif_branches,
                                else_branch,
                            )?;
                            continue;
                        }
                        Statement::Unless {
                            condition,
                            then_branch,
                            else_branch,
                            ..
                        } => {
                            last_value = self.evaluate_unless_expression(
                                condition,
                                then_branch,
                                else_branch,
                            )?;
                            continue;
                        }
                        _ => {}
                    }
                }

                match self.execute_statement(statement)? {
                    ControlFlow::Next => continue,
                    ControlFlow::Return { value, .. } => return Ok(value),
                    ControlFlow::Exception {
                        exception,
                        position,
                    } => {
                        return Err(MetorexError::UncaughtException {
                            exception: exception.clone(),
                            location: position_to_location(position),
                            message: format_exception(&exception),
                        });
                    }
                    ControlFlow::Break { position } => {
                        return Err(loop_control_error("break", position));
                    }
                    ControlFlow::Continue { position } => {
                        return Err(loop_control_error("continue", position));
                    }
                }
            }

            Ok(last_value)
        })();

        self.environment_mut().pop_scope();
        result
    }

    /// Check if a class is an exception class (Exception or its subclasses)
    pub(crate) fn is_exception_class(&self, class: &Class) -> bool {
        Self::is_exception_class_static(class)
    }

    /// Static helper to check if a class is an exception class
    fn is_exception_class_static(class: &Class) -> bool {
        let exception_classes = [
            "Exception",
            "StandardError",
            "RuntimeError",
            "TypeError",
            "ValueError",
        ];

        // Check if the class name matches any exception class
        if exception_classes.contains(&class.name()) {
            return true;
        }

        // Check if any parent class is an exception class
        if let Some(superclass) = class.superclass() {
            return Self::is_exception_class_static(&superclass);
        }

        false
    }

    /// Bind named keyword parameters to the current scope.
    /// `kwargs` is a HashMap of string key → Object extracted from the keyword-args dict.
    pub(crate) fn bind_keyword_params(
        &mut self,
        keyword_parameters: &[(String, Option<Expression>)],
        kwargs: HashMap<String, Object>,
    ) -> Result<(), MetorexError> {
        for (name, default_expr) in keyword_parameters {
            let value = if let Some(v) = kwargs.get(name) {
                v.clone()
            } else if let Some(expr) = default_expr {
                self.evaluate_expression(expr)?
            } else {
                return Err(MetorexError::runtime_error(
                    format!("Missing required keyword argument: {}", name),
                    crate::error::SourceLocation::new(0, 0, 0),
                ));
            };
            self.environment_mut().define(name.clone(), value);
        }
        Ok(())
    }
}

/// Count the number of positional arguments, excluding a trailing kwargs dict.
fn positional_arg_count(arguments: &[Object]) -> usize {
    if let Some(Object::Dict(dict_rc)) = arguments.last() {
        let dict = dict_rc.borrow();
        if !dict.is_empty() && dict.keys().all(|k| k.starts_with(':')) {
            return arguments.len() - 1;
        }
    }
    arguments.len()
}

/// Split a list of evaluated arguments into positional args and keyword args.
/// If the last argument is a Dict with symbol-style keys, it's treated as keyword args.
fn split_keyword_args(mut arguments: Vec<Object>) -> (Vec<Object>, HashMap<String, Object>) {
    if let Some(Object::Dict(dict_rc)) = arguments.last() {
        let dict = dict_rc.borrow();
        // Keyword arg dicts use symbol-style keys (starting with ':')
        let all_symbol_keys = !dict.is_empty() && dict.keys().all(|k| k.starts_with(':'));
        if all_symbol_keys {
            let kwargs: HashMap<String, Object> = dict
                .iter()
                .map(|(k, v)| (k[1..].to_string(), v.clone()))
                .collect();
            drop(dict);
            arguments.pop();
            return (arguments, kwargs);
        }
    }
    (arguments, HashMap::new())
}

//! Method lookup and dispatch for the virtual machine.
//!
//! This module handles resolving method calls on receiver objects and dispatching
//! to the appropriate method implementation.

use super::VirtualMachine;
use super::errors::*;
use crate::ast::Expression;
use crate::class::Class;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::{Method, Object};
use std::rc::Rc;

impl VirtualMachine {
    /// Evaluate a method call expression on a receiver object.
    pub(crate) fn evaluate_method_call(
        &mut self,
        receiver_expr: &Expression,
        method_name: &str,
        argument_exprs: &[Expression],
        trailing_block: Option<&Expression>,
        position: Position,
    ) -> Result<Object, MetorexError> {
        let receiver = self.evaluate_expression(receiver_expr)?;
        let mut arguments = Vec::with_capacity(argument_exprs.len());
        for argument in argument_exprs {
            arguments.push(self.evaluate_expression(argument)?);
        }

        // If there's a trailing block, evaluate it and store as pending_block.
        // Native methods (each, map, etc.) will take it from self.pending_block.
        if let Some(block_expr) = trailing_block {
            self.pending_block = Some(self.evaluate_expression(block_expr)?);
        }

        match self.lookup_method(&receiver, method_name) {
            Some((class, method)) => {
                self.invoke_method(class, method, receiver, arguments, position)
            }
            None => {
                // For Class receivers, check for extended methods (__ext__name class var)
                if let Object::Class(class_rc) = &receiver {
                    let ext_key = format!("__ext__{}", method_name);
                    if let Some(Object::Method(ext_method)) = class_rc.get_class_var(&ext_key) {
                        return self.invoke_method(
                            Rc::clone(class_rc),
                            ext_method,
                            receiver.clone(),
                            arguments,
                            position,
                        );
                    }
                }
                // Try native method as fallback
                let class = self.builtins().class_of(&receiver);
                let native_result =
                    self.call_native_method(&class, &receiver, method_name, &arguments, position)?;

                if let Some(result) = native_result {
                    return Ok(result);
                }

                // For user-defined class instances, fall back to base Object methods
                let object_result =
                    self.call_object_method(&receiver, method_name, &arguments, position)?;

                if let Some(result) = object_result {
                    return Ok(result);
                }

                // Try method_missing as a final fallback
                if let Some((method_missing_class, method_missing_method)) =
                    self.lookup_method(&receiver, "method_missing")
                {
                    // Call method_missing with the method name as a string argument
                    let method_name_obj = Object::String(Rc::new(method_name.to_string()));
                    self.invoke_method(
                        method_missing_class,
                        method_missing_method,
                        receiver,
                        vec![method_name_obj],
                        position,
                    )
                } else {
                    Err(undefined_method_error(method_name, &receiver, position))
                }
            }
        }
    }

    /// Look up a method on the receiver and return its class and method definition.
    pub(crate) fn lookup_method(
        &self,
        receiver: &Object,
        method_name: &str,
    ) -> Option<(Rc<Class>, Rc<Method>)> {
        match receiver {
            Object::Instance(instance_rc) => {
                let instance_ref = instance_rc.borrow();
                let class = Rc::clone(&instance_ref.class);
                drop(instance_ref);
                class.find_method(method_name).map(|method| (class, method))
            }
            Object::Class(class_rc) => class_rc
                .find_method(method_name)
                .map(|method| (Rc::clone(class_rc), method)),
            _ => {
                let class = self.builtins().class_of(receiver);
                class.find_method(method_name).map(|method| (class, method))
            }
        }
    }
}

