//! Native (built-in) function implementations for the virtual machine.
//!
//! This module contains implementations of global built-in functions like puts, print, etc.

use super::VirtualMachine;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;

impl VirtualMachine {
    /// Call a native function by name.
    pub(crate) fn call_native_function(
        &mut self,
        name: &str,
        arguments: Vec<Object>,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match name {
            "puts" => {
                // puts prints each argument on a new line
                for arg in &arguments {
                    // Try to call to_s or inspect method if it exists on the object
                    let output = self.get_string_representation(arg, position)?;
                    println!("{}", output);
                }
                Ok(Object::Nil)
            }
            "method" => {
                // method(:name) returns a Method object for the given method name
                if arguments.len() != 1 {
                    return Err(MetorexError::runtime_error(
                        format!("method() expects 1 argument, got {}", arguments.len()),
                        crate::vm::utils::position_to_location(position),
                    ));
                }

                let method_name = match &arguments[0] {
                    Object::Symbol(name) => name.as_str(),
                    _ => {
                        return Err(MetorexError::runtime_error(
                            format!(
                                "method() expects a Symbol argument, got {}",
                                arguments[0].type_name()
                            ),
                            crate::vm::utils::position_to_location(position),
                        ));
                    }
                };

                // Look up the method in the current environment
                if let Some(obj) = self.environment().get(method_name) {
                    match obj {
                        Object::Method(_) => Ok(obj),
                        _ => Err(MetorexError::runtime_error(
                            format!("'{}' is not a method", method_name),
                            crate::vm::utils::position_to_location(position),
                        )),
                    }
                } else {
                    Err(MetorexError::runtime_error(
                        format!("undefined method '{}'", method_name),
                        crate::vm::utils::position_to_location(position),
                    ))
                }
            }
            "require_relative" => {
                // require_relative(path) loads and executes a file relative to the current file
                if arguments.len() != 1 {
                    return Err(MetorexError::runtime_error(
                        format!(
                            "require_relative() expects 1 argument, got {}",
                            arguments.len()
                        ),
                        crate::vm::utils::position_to_location(position),
                    ));
                }

                let relative_path = match &arguments[0] {
                    Object::String(path) => path.as_ref(),
                    _ => {
                        return Err(MetorexError::runtime_error(
                            format!(
                                "require_relative() expects a String argument, got {}",
                                arguments[0].type_name()
                            ),
                            crate::vm::utils::position_to_location(position),
                        ));
                    }
                };

                // Get current file path
                let current_file = self.get_current_file().ok_or_else(|| {
                    MetorexError::runtime_error(
                        "require_relative cannot be used without a current file context (e.g., in REPL)"
                            .to_string(),
                        crate::vm::utils::position_to_location(position),
                    )
                })?;

                // Resolve the relative path
                let resolved_path =
                    crate::file_loader::resolve_relative_path(current_file, relative_path)
                        .map_err(|e| {
                            MetorexError::runtime_error(
                                format!("Failed to resolve path '{}': {}", relative_path, e),
                                crate::vm::utils::position_to_location(position),
                            )
                        })?;

                // Find the actual file path with extension auto-detection
                let actual_path =
                    crate::file_loader::find_file_path(&resolved_path).map_err(|e| {
                        MetorexError::runtime_error(
                            format!("Error in require_relative: {}", e),
                            crate::vm::utils::position_to_location(position),
                        )
                    })?;

                // Canonicalize to get the absolute path for deduplication checking
                let canonical_path = actual_path.canonicalize().map_err(|e| {
                    MetorexError::runtime_error(
                        format!(
                            "Failed to canonicalize path '{}': {}",
                            actual_path.display(),
                            e
                        ),
                        crate::vm::utils::position_to_location(position),
                    )
                })?;

                // Check if file was already loaded BEFORE executing
                let was_already_loaded = self.is_file_loaded(&canonical_path);

                // Execute the file (it will handle its own deduplication)
                self.execute_file(&resolved_path).map_err(|e| {
                    MetorexError::runtime_error(
                        format!("Error in require_relative: {}", e),
                        crate::vm::utils::position_to_location(position),
                    )
                })?;

                // Return true if newly loaded, false if already loaded (Ruby behavior)
                Ok(Object::Bool(!was_already_loaded))
            }
            "print" => {
                // print outputs arguments without trailing newline
                for arg in &arguments {
                    let output = self.get_string_representation(arg, position)?;
                    print!("{}", output);
                }
                use std::io::Write;
                std::io::stdout().flush().ok();
                Ok(Object::Nil)
            }
            "p" => {
                // p prints the inspect representation of each argument
                for arg in &arguments {
                    println!("{:?}", arg);
                }
                if arguments.len() == 1 {
                    Ok(arguments.into_iter().next().unwrap())
                } else {
                    Ok(Object::Nil)
                }
            }
            "gets" => {
                // gets reads a line from stdin
                if !arguments.is_empty() {
                    return Err(MetorexError::runtime_error(
                        format!("gets() expects 0 arguments, got {}", arguments.len()),
                        crate::vm::utils::position_to_location(position),
                    ));
                }
                let mut input = String::new();
                std::io::stdin().read_line(&mut input).map_err(|e| {
                    MetorexError::runtime_error(
                        format!("Failed to read from stdin: {}", e),
                        crate::vm::utils::position_to_location(position),
                    )
                })?;
                // Remove trailing newline (like Ruby's gets)
                if input.ends_with('\n') {
                    input.pop();
                    if input.ends_with('\r') {
                        input.pop();
                    }
                }
                Ok(Object::string(input))
            }
            _ => Err(MetorexError::runtime_error(
                format!("Unknown native function: {}", name),
                crate::vm::utils::position_to_location(position),
            )),
        }
    }

    /// Get the string representation of an object by calling to_s or inspect if available.
    fn get_string_representation(
        &mut self,
        obj: &Object,
        position: Position,
    ) -> Result<String, MetorexError> {
        // First try to_s, then inspect, then fall back to Display
        match obj {
            Object::Instance(_) => {
                // Try to_s first
                if let Some((class, method)) = self.lookup_method(obj, "to_s") {
                    let result =
                        self.invoke_method(class, method, obj.clone(), vec![], position)?;
                    if let Object::String(s) = result {
                        return Ok(s.to_string());
                    }
                }
                // Try inspect as fallback
                if let Some((class, method)) = self.lookup_method(obj, "inspect") {
                    let result =
                        self.invoke_method(class, method, obj.clone(), vec![], position)?;
                    if let Object::String(s) = result {
                        return Ok(s.to_string());
                    }
                }
                // Fall back to default Display
                Ok(format!("{}", obj))
            }
            _ => Ok(format!("{}", obj)),
        }
    }
}

//! Native method implementations for the Array class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::cell::RefCell;
use std::rc::Rc;

fn compare_for_sort(a: &Object, b: &Object) -> std::cmp::Ordering {
    match (a, b) {
        (Object::Int(x), Object::Int(y)) => x.cmp(y),
        (Object::Float(x), Object::Float(y)) => {
            x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal)
        }
        (Object::Int(x), Object::Float(y)) => (*x as f64)
            .partial_cmp(y)
            .unwrap_or(std::cmp::Ordering::Equal),
        (Object::Float(x), Object::Int(y)) => x
            .partial_cmp(&(*y as f64))
            .unwrap_or(std::cmp::Ordering::Equal),
        (Object::String(x), Object::String(y)) => x.as_str().cmp(y.as_str()),
        _ => a.to_string().cmp(&b.to_string()),
    }
}

impl VirtualMachine {
    /// Execute native methods for the Array class.
    pub(crate) fn call_array_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "length" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    Ok(Some(Object::Int(array_rc.borrow().len() as i64)))
                } else {
                    Ok(None)
                }
            }
            "push" | "append" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    array_rc.borrow_mut().push(arguments[0].clone());
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            "pop" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    Ok(Some(array_rc.borrow_mut().pop().unwrap_or(Object::Nil)))
                } else {
                    Ok(None)
                }
            }
            "[]" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(self.evaluate_index_operation(
                    receiver.clone(),
                    arguments[0].clone(),
                    position,
                )?))
            }
            "each" => {
                // each takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "each requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();
                    for element in array.iter() {
                        let args = vec![element.clone()];
                        match self.execute_block_with_control_flow(&block, args)? {
                            super::super::ControlFlow::Next
                            | super::super::ControlFlow::Continue { .. } => {
                                continue;
                            }
                            super::super::ControlFlow::Break { .. } => break,
                            super::super::ControlFlow::Return { value: _, position } => {
                                return Err(super::super::errors::loop_control_error(
                                    "return", position,
                                ));
                            }
                            super::super::ControlFlow::Exception {
                                exception,
                                position,
                            } => {
                                return Err(MetorexError::runtime_error(
                                    format!(
                                        "Uncaught exception: {}",
                                        super::super::utils::format_exception(&exception)
                                    ),
                                    super::super::utils::position_to_location(position),
                                ));
                            }
                        }
                    }
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            "map" => {
                // map takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "map requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();
                    let mut results = Vec::new();
                    for element in array.iter() {
                        let args = vec![element.clone()];
                        let value = self.execute_block_body(&block, args)?;
                        results.push(value);
                    }
                    Ok(Some(Object::Array(Rc::new(RefCell::new(results)))))
                } else {
                    Ok(None)
                }
            }
            "select" | "filter" => {
                // select/filter takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "select requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();
                    let mut results = Vec::new();
                    for element in array.iter() {
                        let args = vec![element.clone()];
                        let value = self.execute_block_body(&block, args)?;
                        let is_truthy = !matches!(value, Object::Bool(false) | Object::Nil);
                        if is_truthy {
                            results.push(element.clone());
                        }
                    }
                    Ok(Some(Object::Array(Rc::new(RefCell::new(results)))))
                } else {
                    Ok(None)
                }
            }
            "reduce" => {
                // reduce takes a trailing block (via pending_block) and an optional initial value
                if arguments.len() > 1 {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "reduce requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();

                    // Optional initial value is the first positional argument
                    let (initial_value, start_index) = if arguments.len() == 1 {
                        (Some(arguments[0].clone()), 0)
                    } else {
                        (None, 1)
                    };

                    if array.is_empty() {
                        return Ok(Some(Object::Nil));
                    }

                    let mut accumulator = if let Some(init) = initial_value {
                        init
                    } else {
                        array[0].clone()
                    };

                    for element in array.iter().skip(start_index) {
                        let args = vec![accumulator.clone(), element.clone()];
                        accumulator = self.execute_block_body(&block, args)?;
                    }
                    Ok(Some(accumulator))
                } else {
                    Ok(None)
                }
            }
            "zip" => {
                // zip takes one or more arrays and returns an array of arrays
                if arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();

                    // Convert all arguments to arrays
                    let mut other_arrays = Vec::new();
                    for arg in arguments {
                        match arg {
                            Object::Array(arr_rc) => {
                                other_arrays.push(arr_rc.borrow().clone());
                            }
                            _ => {
                                return Err(method_argument_type_error(
                                    method_name,
                                    "Array",
                                    arg,
                                    position,
                                ));
                            }
                        }
                    }

                    // Create the zipped result
                    let mut results = Vec::new();
                    for (i, element) in array.iter().enumerate() {
                        let mut tuple = vec![element.clone()];
                        for other_array in &other_arrays {
                            if i < other_array.len() {
                                tuple.push(other_array[i].clone());
                            } else {
                                tuple.push(Object::Nil);
                            }
                        }
                        results.push(Object::Array(Rc::new(RefCell::new(tuple))));
                    }
                    Ok(Some(Object::Array(Rc::new(RefCell::new(results)))))
                } else {
                    Ok(None)
                }
            }
            "transpose" => {
                // transpose converts rows to columns and vice versa
                // expects an array of arrays (matrix)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let array = array_rc.borrow();

                    // Handle empty array
                    if array.is_empty() {
                        return Ok(Some(Object::Array(Rc::new(RefCell::new(Vec::new())))));
                    }

                    // Verify all elements are arrays
                    let mut row_arrays = Vec::new();
                    for element in array.iter() {
                        match element {
                            Object::Array(arr_rc) => {
                                row_arrays.push(arr_rc.borrow().clone());
                            }
                            _ => {
                                return Err(MetorexError::runtime_error(
                                    format!(
                                        "transpose requires all elements to be arrays, found {}",
                                        element.type_name()
                                    ),
                                    position_to_location(position),
                                ));
                            }
                        }
                    }

                    // Find the maximum row length
                    let max_cols = row_arrays.iter().map(|row| row.len()).max().unwrap_or(0);

                    // Build the transposed matrix
                    let mut transposed = Vec::new();
                    for col_idx in 0..max_cols {
                        let mut new_row = Vec::new();
                        for row in &row_arrays {
                            if col_idx < row.len() {
                                new_row.push(row[col_idx].clone());
                            } else {
                                new_row.push(Object::Nil);
                            }
                        }
                        transposed.push(Object::Array(Rc::new(RefCell::new(new_row))));
                    }

                    Ok(Some(Object::Array(Rc::new(RefCell::new(transposed)))))
                } else {
                    Ok(None)
                }
            }
            "size" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    Ok(Some(Object::Int(array_rc.borrow().len() as i64)))
                } else {
                    Ok(None)
                }
            }
            "shift" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let mut array = array_rc.borrow_mut();
                    if array.is_empty() {
                        Ok(Some(Object::Nil))
                    } else {
                        Ok(Some(array.remove(0)))
                    }
                } else {
                    Ok(None)
                }
            }
            "unshift" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    array_rc.borrow_mut().insert(0, arguments[0].clone());
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            "sort" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let mut sorted = array_rc.borrow().clone();
                    sorted.sort_by(compare_for_sort);
                    Ok(Some(Object::Array(Rc::new(RefCell::new(sorted)))))
                } else {
                    Ok(None)
                }
            }
            "reverse" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let mut reversed = array_rc.borrow().clone();
                    reversed.reverse();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(reversed)))))
                } else {
                    Ok(None)
                }
            }
            "join" => {
                if arguments.len() > 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Array(array_rc) = receiver {
                    let sep = if arguments.is_empty() {
                        String::new()
                    } else {
                        match &arguments[0] {
                            Object::String(s) => s.as_ref().clone(),
                            _ => {
                                return Err(method_argument_type_error(
                                    method_name,
                                    "String",
                                    &arguments[0],
                                    position,
                                ));
                            }
                        }
                    };
                    let parts: Vec<String> = array_rc
                        .borrow()
                        .iter()
                        .map(|obj| format!("{obj}"))
                        .collect();
                    Ok(Some(Object::string(parts.join(&sep))))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! AST node serialization for the AST Inspection API.
//!
//! Converts Metorex AST nodes (Statements and Expressions) into Object::Dict
//! representations that can be inspected at runtime.

use crate::ast::{BinaryOp, Expression, Statement, UnaryOp};
use crate::object::Object;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

fn make_dict(entries: Vec<(&str, Object)>) -> Object {
    let mut map = HashMap::new();
    for (k, v) in entries {
        map.insert(k.to_string(), v);
    }
    Object::Dict(Rc::new(RefCell::new(map)))
}

fn make_array(items: Vec<Object>) -> Object {
    Object::Array(Rc::new(RefCell::new(items)))
}

fn str_obj(s: impl Into<String>) -> Object {
    Object::string(s.into())
}

fn binary_op_str(op: &BinaryOp) -> &'static str {
    match op {
        BinaryOp::Add => "+",
        BinaryOp::Subtract => "-",
        BinaryOp::Multiply => "*",
        BinaryOp::Divide => "/",
        BinaryOp::Modulo => "%",
        BinaryOp::Equal => "==",
        BinaryOp::NotEqual => "!=",
        BinaryOp::Less => "<",
        BinaryOp::Greater => ">",
        BinaryOp::LessEqual => "<=",
        BinaryOp::GreaterEqual => ">=",
        BinaryOp::And => "&&",
        BinaryOp::Or => "||",
        BinaryOp::Assign => "=",
        BinaryOp::AddAssign => "+=",
        BinaryOp::SubtractAssign => "-=",
        BinaryOp::MultiplyAssign => "*=",
        BinaryOp::DivideAssign => "/=",
    }
}

fn unary_op_str(op: &UnaryOp) -> &'static str {
    match op {
        UnaryOp::Plus => "+",
        UnaryOp::Minus => "-",
        UnaryOp::Not => "!",
    }
}

/// Serialize an Expression to an Object::Dict.
pub fn serialize_expression(expr: &Expression) -> Object {
    match expr {
        Expression::IntLiteral { value, .. } => make_dict(vec![
            ("type", str_obj("IntLiteral")),
            ("value", Object::Int(*value)),
        ]),
        Expression::FloatLiteral { value, .. } => make_dict(vec![
            ("type", str_obj("FloatLiteral")),
            ("value", Object::Float(*value)),
        ]),
        Expression::StringLiteral { value, .. } => make_dict(vec![
            ("type", str_obj("StringLiteral")),
            ("value", str_obj(value.clone())),
        ]),
        Expression::BoolLiteral { value, .. } => make_dict(vec![
            ("type", str_obj("BoolLiteral")),
            ("value", Object::Bool(*value)),
        ]),
        Expression::NilLiteral { .. } => make_dict(vec![("type", str_obj("NilLiteral"))]),
        Expression::Symbol { value, .. } => make_dict(vec![
            ("type", str_obj("Symbol")),
            ("value", str_obj(value.clone())),
        ]),
        Expression::Identifier { name, .. } => make_dict(vec![
            ("type", str_obj("Identifier")),
            ("name", str_obj(name.clone())),
        ]),
        Expression::InstanceVariable { name, .. } => make_dict(vec![
            ("type", str_obj("InstanceVariable")),
            ("name", str_obj(name.clone())),
        ]),
        Expression::ClassVariable { name, .. } => make_dict(vec![
            ("type", str_obj("ClassVariable")),
            ("name", str_obj(name.clone())),
        ]),
        Expression::GlobalVariable { name, .. } => make_dict(vec![
            ("type", str_obj("GlobalVariable")),
            ("name", str_obj(name.clone())),
        ]),
        Expression::BinaryOp {
            op, left, right, ..
        } => make_dict(vec![
            ("type", str_obj("BinaryOp")),
            ("op", str_obj(binary_op_str(op))),
            ("left", serialize_expression(left)),
            ("right", serialize_expression(right)),
        ]),
        Expression::UnaryOp { op, operand, .. } => make_dict(vec![
            ("type", str_obj("UnaryOp")),
            ("op", str_obj(unary_op_str(op))),
            ("operand", serialize_expression(operand)),
        ]),
        Expression::Call {
            callee, arguments, ..
        } => make_dict(vec![
            ("type", str_obj("Call")),
            ("callee", serialize_expression(callee)),
            (
                "arguments",
                make_array(arguments.iter().map(serialize_expression).collect()),
            ),
        ]),
        Expression::MethodCall {
            receiver,
            method,
            arguments,
            ..
        } => make_dict(vec![
            ("type", str_obj("MethodCall")),
            ("receiver", serialize_expression(receiver)),
            ("method", str_obj(method.clone())),
            (
                "arguments",
                make_array(arguments.iter().map(serialize_expression).collect()),
            ),
        ]),
        Expression::Array { elements, .. } => make_dict(vec![
            ("type", str_obj("Array")),
            (
                "elements",
                make_array(elements.iter().map(serialize_expression).collect()),
            ),
        ]),
        Expression::Index { array, index, .. } => make_dict(vec![
            ("type", str_obj("Index")),
            ("array", serialize_expression(array)),
            ("index", serialize_expression(index)),
        ]),
        Expression::Dictionary { entries, .. } => {
            let pairs: Vec<Object> = entries
                .iter()
                .map(|(k, v)| {
                    make_dict(vec![
                        ("key", serialize_expression(k)),
                        ("value", serialize_expression(v)),
                    ])
                })
                .collect();
            make_dict(vec![
                ("type", str_obj("Dictionary")),
                ("entries", make_array(pairs)),
            ])
        }
        Expression::Lambda {
            parameters, body, ..
        } => make_dict(vec![
            ("type", str_obj("Lambda")),
            (
                "parameters",
                make_array(parameters.iter().map(|p| str_obj(p.clone())).collect()),
            ),
            (
                "body",
                make_array(body.iter().map(serialize_statement).collect()),
            ),
        ]),
        Expression::Grouped { expression, .. } => make_dict(vec![
            ("type", str_obj("Grouped")),
            ("expression", serialize_expression(expression)),
        ]),
        Expression::SelfExpr { .. } => make_dict(vec![("type", str_obj("Self"))]),
        Expression::ScopeResolution {
            namespace, name, ..
        } => make_dict(vec![
            ("type", str_obj("ScopeResolution")),
            ("namespace", serialize_expression(namespace)),
            ("name", str_obj(name.clone())),
        ]),
        Expression::InterpolatedString { .. } => {
            make_dict(vec![("type", str_obj("InterpolatedString"))])
        }
        _ => make_dict(vec![("type", str_obj("Unknown"))]),
    }
}

/// Serialize a Statement to an Object::Dict.
pub fn serialize_statement(stmt: &Statement) -> Object {
    match stmt {
        Statement::Expression { expression, .. } => serialize_expression(expression),
        Statement::Return { value, .. } => make_dict(vec![
            ("type", str_obj("Return")),
            (
                "value",
                value
                    .as_ref()
                    .map(serialize_expression)
                    .unwrap_or(Object::Nil),
            ),
        ]),
        Statement::Assignment { target, value, .. } => make_dict(vec![
            ("type", str_obj("Assignment")),
            ("target", serialize_expression(target)),
            ("value", serialize_expression(value)),
        ]),
        Statement::If {
            condition,
            then_branch,
            else_branch,
            ..
        } => make_dict(vec![
            ("type", str_obj("If")),
            ("condition", serialize_expression(condition)),
            (
                "then_branch",
                make_array(then_branch.iter().map(serialize_statement).collect()),
            ),
            (
                "else_branch",
                else_branch
                    .as_ref()
                    .map(|b| make_array(b.iter().map(serialize_statement).collect()))
                    .unwrap_or(Object::Nil),
            ),
        ]),
        Statement::While {
            condition, body, ..
        } => make_dict(vec![
            ("type", str_obj("While")),
            ("condition", serialize_expression(condition)),
            (
                "body",
                make_array(body.iter().map(serialize_statement).collect()),
            ),
        ]),
        Statement::For {
            variable,
            iterable,
            body,
            ..
        } => make_dict(vec![
            ("type", str_obj("For")),
            ("variable", str_obj(variable.clone())),
            ("iterable", serialize_expression(iterable)),
            (
                "body",
                make_array(body.iter().map(serialize_statement).collect()),
            ),
        ]),
        Statement::MethodDef {
            name, parameters, ..
        } => make_dict(vec![
            ("type", str_obj("MethodDef")),
            ("name", str_obj(name.clone())),
            (
                "parameters",
                make_array(parameters.iter().map(|p| str_obj(p.name.clone())).collect()),
            ),
        ]),
        Statement::Raise { exception, .. } => make_dict(vec![
            ("type", str_obj("Raise")),
            (
                "exception",
                exception
                    .as_ref()
                    .map(serialize_expression)
                    .unwrap_or(Object::Nil),
            ),
        ]),
        Statement::Break { .. } => make_dict(vec![("type", str_obj("Break"))]),
        Statement::Continue { .. } => make_dict(vec![("type", str_obj("Continue"))]),
        _ => make_dict(vec![("type", str_obj("Unknown"))]),
    }
}

/// Serialize a slice of Statements to an Object::Array of Dicts.
pub fn serialize_statements(stmts: &[Statement]) -> Object {
    make_array(stmts.iter().map(serialize_statement).collect())
}

//! Native method implementations for Exception objects

use super::super::VirtualMachine;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::utils::*;
use std::cell::RefCell;
use std::rc::Rc;

impl VirtualMachine {
    /// Call a native method on an Exception object
    pub(crate) fn call_exception_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        _arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        let exception = match receiver {
            Object::Exception(exc) => exc,
            _ => {
                return Err(MetorexError::runtime_error(
                    format!("Expected Exception, got {:?}", receiver),
                    position_to_location(position),
                ));
            }
        };

        match method_name {
            "message" => {
                // Return the exception message as a String
                let message = exception.borrow().message.clone();
                Ok(Some(Object::String(Rc::new(message))))
            }
            "type" | "exception_type" => {
                // Return the exception type as a String
                let exception_type = exception.borrow().exception_type.clone();
                Ok(Some(Object::String(Rc::new(exception_type))))
            }
            "backtrace" => {
                // Return the backtrace as an Array of Strings
                let backtrace = exception.borrow().backtrace.clone();
                match backtrace {
                    Some(trace) => {
                        let trace_objects: Vec<Object> = trace
                            .iter()
                            .map(|line| Object::String(Rc::new(line.clone())))
                            .collect();
                        Ok(Some(Object::Array(Rc::new(RefCell::new(trace_objects)))))
                    }
                    None => Ok(Some(Object::Array(Rc::new(RefCell::new(Vec::new()))))),
                }
            }
            "to_s" => {
                // Return a formatted error message with stack trace
                let exc = exception.borrow();
                let mut result = format!("{}: {}", exc.exception_type, exc.message);

                // Add location if available
                if let Some(ref location) = exc.location {
                    result = format!("{} (at {}:{})", result, location.file, location.line);
                }

                // Add backtrace if available
                if let Some(ref backtrace) = exc.backtrace
                    && !backtrace.is_empty()
                {
                    result.push_str("\nBacktrace:\n");
                    for line in backtrace {
                        result.push_str(line);
                        result.push('\n');
                    }
                }

                Ok(Some(Object::String(Rc::new(result))))
            }
            _ => Ok(None), // No native method found, let it fall through
        }
    }
}

//! Native method implementations for the Float class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;

impl VirtualMachine {
    /// Execute native methods for the Float class.
    pub(crate) fn call_float_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "round" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(float_value) = receiver {
                    let precision = match &arguments[0] {
                        Object::Int(p) => *p,
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Integer",
                                &arguments[0],
                                position,
                            ));
                        }
                    };

                    if precision < 0 {
                        return Err(MetorexError::runtime_error(
                            format!(
                                "Float.round precision must be non-negative, got {}",
                                precision
                            ),
                            position_to_location(position),
                        ));
                    }

                    // Round to the specified number of decimal places
                    let multiplier = 10_f64.powi(precision as i32);
                    let rounded = (float_value * multiplier).round() / multiplier;
                    Ok(Some(Object::Float(rounded)))
                } else {
                    Ok(None)
                }
            }
            "abs" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(f) = receiver {
                    Ok(Some(Object::Float(f.abs())))
                } else {
                    Ok(None)
                }
            }
            "ceil" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(f) = receiver {
                    Ok(Some(Object::Int(f.ceil() as i64)))
                } else {
                    Ok(None)
                }
            }
            "floor" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(f) = receiver {
                    Ok(Some(Object::Int(f.floor() as i64)))
                } else {
                    Ok(None)
                }
            }
            "to_i" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(f) = receiver {
                    Ok(Some(Object::Int(*f as i64)))
                } else {
                    Ok(None)
                }
            }
            "to_f" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(receiver.clone()))
            }
            "to_s" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Float(f) = receiver {
                    Ok(Some(Object::String(std::rc::Rc::new(f.to_string()))))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the Hash class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::cell::RefCell;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute native methods for the Hash class.
    pub(crate) fn call_hash_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "keys" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let dict = dict_rc.borrow();
                    let keys: Vec<Object> =
                        dict.keys().map(|k| Object::string(k.clone())).collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(keys)))))
                } else {
                    Ok(None)
                }
            }
            "values" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let dict = dict_rc.borrow();
                    let values: Vec<Object> = dict.values().cloned().collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(values)))))
                } else {
                    Ok(None)
                }
            }
            "has_key?" | "key?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let key_obj = &arguments[0];
                    // Convert key object to string representation (same as used for dict keys)
                    let key_str = match key_obj {
                        Object::String(s) => s.as_str().to_string(),
                        Object::Int(i) => i.to_string(),
                        Object::Float(f) => f.to_string(),
                        Object::Bool(b) => b.to_string(),
                        Object::Nil => "nil".to_string(),
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "String, Integer, Float, Bool, or Nil",
                                key_obj,
                                position,
                            ));
                        }
                    };
                    let dict = dict_rc.borrow();
                    Ok(Some(Object::Bool(dict.contains_key(&key_str))))
                } else {
                    Ok(None)
                }
            }
            "entries" | "to_a" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let dict = dict_rc.borrow();
                    let entries: Vec<Object> = dict
                        .iter()
                        .map(|(k, v)| {
                            Object::Array(Rc::new(RefCell::new(vec![
                                Object::string(k.clone()),
                                v.clone(),
                            ])))
                        })
                        .collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(entries)))))
                } else {
                    Ok(None)
                }
            }
            "length" | "size" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    Ok(Some(Object::Int(dict_rc.borrow().len() as i64)))
                } else {
                    Ok(None)
                }
            }
            "[]" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(self.evaluate_index_operation(
                    receiver.clone(),
                    arguments[0].clone(),
                    position,
                )?))
            }
            "get" | "fetch" => {
                if arguments.is_empty() || arguments.len() > 2 {
                    return Err(MetorexError::runtime_error(
                        format!(
                            "Method '{}' expected 1-2 argument(s) but received {}",
                            method_name,
                            arguments.len()
                        ),
                        position_to_location(position),
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let key_str =
                        crate::vm::utils::object_to_dict_key(&arguments[0]).ok_or_else(|| {
                            method_argument_type_error(
                                method_name,
                                "String, Integer, Float, Bool, or Nil",
                                &arguments[0],
                                position,
                            )
                        })?;
                    let dict = dict_rc.borrow();
                    match dict.get(&key_str) {
                        Some(value) => Ok(Some(value.clone())),
                        None => {
                            if arguments.len() == 2 {
                                // Return the default value
                                Ok(Some(arguments[1].clone()))
                            } else if method_name == "fetch" {
                                // fetch without default raises an error
                                Err(MetorexError::runtime_error(
                                    format!("Key '{}' not found in hash", key_str),
                                    position_to_location(position),
                                ))
                            } else {
                                // get without default returns nil
                                Ok(Some(Object::Nil))
                            }
                        }
                    }
                } else {
                    Ok(None)
                }
            }
            "merge" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Dict(dict_rc) = receiver {
                    let other = match &arguments[0] {
                        Object::Dict(other_rc) => other_rc,
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Hash",
                                &arguments[0],
                                position,
                            ));
                        }
                    };
                    let mut merged = dict_rc.borrow().clone();
                    for (k, v) in other.borrow().iter() {
                        merged.insert(k.clone(), v.clone());
                    }
                    Ok(Some(Object::Dict(Rc::new(RefCell::new(merged)))))
                } else {
                    Ok(None)
                }
            }
            "each" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "each requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Dict(dict_rc) = receiver {
                    let entries: Vec<(String, Object)> = dict_rc
                        .borrow()
                        .iter()
                        .map(|(k, v)| (k.clone(), v.clone()))
                        .collect();
                    for (key, value) in entries {
                        let args = vec![Object::string(key), value];
                        match self.execute_block_with_control_flow(&block, args)? {
                            super::super::ControlFlow::Next
                            | super::super::ControlFlow::Continue { .. } => {
                                continue;
                            }
                            super::super::ControlFlow::Break { .. } => break,
                            super::super::ControlFlow::Return { value: _, position } => {
                                return Err(super::super::errors::loop_control_error(
                                    "return", position,
                                ));
                            }
                            super::super::ControlFlow::Exception {
                                exception,
                                position,
                            } => {
                                return Err(MetorexError::runtime_error(
                                    format!(
                                        "Uncaught exception: {}",
                                        super::super::utils::format_exception(&exception)
                                    ),
                                    super::super::utils::position_to_location(position),
                                ));
                            }
                        }
                    }
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the Integer class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute native methods for the Integer class.
    pub(crate) fn call_int_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "abs" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Int(n) = receiver {
                    Ok(Some(Object::Int(n.abs())))
                } else {
                    Ok(None)
                }
            }
            "to_f" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Int(n) = receiver {
                    Ok(Some(Object::Float(*n as f64)))
                } else {
                    Ok(None)
                }
            }
            "to_i" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(receiver.clone()))
            }
            "to_s" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Int(n) = receiver {
                    Ok(Some(Object::String(Rc::new(n.to_string()))))
                } else {
                    Ok(None)
                }
            }
            "times" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "times requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Int(n) = receiver {
                    for i in 0..*n {
                        let args = vec![Object::Int(i)];
                        match self.execute_block_with_control_flow(&block, args)? {
                            super::super::ControlFlow::Next
                            | super::super::ControlFlow::Continue { .. } => {
                                continue;
                            }
                            super::super::ControlFlow::Break { .. } => break,
                            super::super::ControlFlow::Return { value: _, position } => {
                                return Err(super::super::errors::loop_control_error(
                                    "return", position,
                                ));
                            }
                            super::super::ControlFlow::Exception {
                                exception,
                                position,
                            } => {
                                return Err(MetorexError::runtime_error(
                                    format!(
                                        "Uncaught exception: {}",
                                        super::super::utils::format_exception(&exception)
                                    ),
                                    super::super::utils::position_to_location(position),
                                ));
                            }
                        }
                    }
                    Ok(Some(Object::Int(*n)))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native (built-in) method implementations for the virtual machine.
//!
//! This module contains the implementations of all built-in methods for
//! standard classes like Object, String, and Array.

mod array_methods;
mod ast_methods;
mod exception_methods;
mod float_methods;
mod hash_methods;
mod int_methods;
mod object_methods;
mod range_methods;
mod set_methods;
mod string_methods;

use super::VirtualMachine;
use crate::class::Class;
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::{Method, Object};
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::rc::Rc;

impl VirtualMachine {
    /// Attempt to execute a native (built-in) method implementation.
    ///
    /// Returns `Ok(Some(result))` if a native method was found and executed successfully,
    /// `Ok(None)` if no native method exists (allowing fallback to user-defined methods),
    /// or `Err` if the method call failed.
    pub(crate) fn call_native_method(
        &mut self,
        class: &Class,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        // Special handling for Block/Lambda objects
        if let Object::Block(block) = receiver {
            match method_name {
                "call" => {
                    return Ok(Some(block.call(self, arguments.to_vec(), position)?));
                }
                "binding" => {
                    use crate::object::Binding;
                    // Create a Binding object from the block's captured variables
                    let binding = Binding::new(block.captured_vars().clone());
                    return Ok(Some(Object::Binding(Rc::new(binding))));
                }
                _ => {}
            }
        }

        // Special handling for Class objects
        if let Object::Class(class_rc) = receiver {
            match method_name {
                "new" if class_rc.name() == "Set" => {
                    // Set.new creates a new set, optionally from an array
                    use crate::object::ObjectHash;
                    let mut set = std::collections::HashSet::new();
                    if arguments.len() == 1 {
                        if let Object::Array(arr_rc) = &arguments[0] {
                            for item in arr_rc.borrow().iter() {
                                if let Some(hash) = ObjectHash::from_object(item) {
                                    set.insert(hash);
                                } else {
                                    return Err(MetorexError::runtime_error(
                                        format!(
                                            "Cannot add {} to set (not hashable)",
                                            item.type_name()
                                        ),
                                        position_to_location(position),
                                    ));
                                }
                            }
                        } else {
                            return Err(method_argument_type_error(
                                "Set.new",
                                "Array",
                                &arguments[0],
                                position,
                            ));
                        }
                    } else if arguments.len() > 1 {
                        return Err(MetorexError::runtime_error(
                            format!("Set.new expects 0-1 arguments, got {}", arguments.len()),
                            position_to_location(position),
                        ));
                    }
                    return Ok(Some(Object::Set(Rc::new(std::cell::RefCell::new(set)))));
                }
                "new" => {
                    // Delegate to invoke_callable which handles instance creation and initialize
                    return self
                        .invoke_callable(
                            Object::Class(Rc::clone(class_rc)),
                            arguments.to_vec(),
                            position,
                        )
                        .map(Some);
                }
                "name" => {
                    return Ok(Some(Object::String(Rc::new(class_rc.name().to_string()))));
                }
                "superclass" => {
                    return match class_rc.superclass() {
                        Some(parent) => Ok(Some(Object::Class(parent))),
                        None => Ok(Some(Object::Nil)),
                    };
                }
                "ancestors" => {
                    let mut chain = vec![Object::Class(Rc::clone(class_rc))];
                    let mut current = class_rc.superclass();
                    while let Some(parent) = current {
                        chain.push(Object::Class(Rc::clone(&parent)));
                        current = parent.superclass();
                    }
                    return Ok(Some(Object::Array(Rc::new(std::cell::RefCell::new(chain)))));
                }
                // File class methods
                "read" if class_rc.name() == "File" => {
                    if arguments.len() != 1 {
                        return Err(method_argument_error("read", 1, arguments.len(), position));
                    }
                    let path = match &arguments[0] {
                        Object::String(s) => s.as_str().to_string(),
                        other => {
                            return Err(method_argument_type_error(
                                "read", "String", other, position,
                            ));
                        }
                    };
                    let contents = std::fs::read_to_string(&path).map_err(|e| {
                        MetorexError::runtime_error(
                            format!("Failed to read file '{}': {}", path, e),
                            position_to_location(position),
                        )
                    })?;
                    return Ok(Some(Object::string(contents)));
                }
                "write" if class_rc.name() == "File" => {
                    if arguments.len() != 2 {
                        return Err(method_argument_error("write", 2, arguments.len(), position));
                    }
                    let path = match &arguments[0] {
                        Object::String(s) => s.as_str().to_string(),
                        other => {
                            return Err(method_argument_type_error(
                                "write", "String", other, position,
                            ));
                        }
                    };
                    let content = match &arguments[1] {
                        Object::String(s) => s.as_str().to_string(),
                        other => format!("{}", other),
                    };
                    std::fs::write(&path, &content).map_err(|e| {
                        MetorexError::runtime_error(
                            format!("Failed to write file '{}': {}", path, e),
                            position_to_location(position),
                        )
                    })?;
                    return Ok(Some(Object::Int(content.len() as i64)));
                }
                "exist?" | "exists?" if class_rc.name() == "File" => {
                    if arguments.len() != 1 {
                        return Err(method_argument_error(
                            "exist?",
                            1,
                            arguments.len(),
                            position,
                        ));
                    }
                    let path = match &arguments[0] {
                        Object::String(s) => s.as_str().to_string(),
                        other => {
                            return Err(method_argument_type_error(
                                "exist?", "String", other, position,
                            ));
                        }
                    };
                    return Ok(Some(Object::Bool(std::path::Path::new(&path).exists())));
                }
                "define_method" => {
                    if arguments.is_empty() {
                        return Err(method_argument_error("define_method", 1, 0, position));
                    }
                    let method_name_str = match &arguments[0] {
                        Object::String(s) => s.as_ref().clone(),
                        Object::Symbol(s) => s.as_ref().clone(),
                        other => {
                            return Err(method_argument_type_error(
                                "define_method",
                                "String or Symbol",
                                other,
                                position,
                            ));
                        }
                    };
                    let block = self
                        .pending_block
                        .take()
                        .or_else(|| arguments.get(1).cloned());
                    let block = match block {
                        Some(Object::Block(b)) => b,
                        _ => {
                            return Err(MetorexError::runtime_error(
                                "define_method requires a block",
                                position_to_location(position),
                            ));
                        }
                    };
                    let mut method = Method::new(
                        method_name_str.clone(),
                        block.parameters.clone(),
                        block.body.clone(),
                    );
                    // Capture closure: prefer existing captured_vars, otherwise snap current scope
                    method.captured_vars = Some(if block.captured_vars.is_empty() {
                        self.environment().current_scope_var_refs()
                    } else {
                        block.captured_vars.clone()
                    });
                    class_rc.define_method(&method_name_str, Rc::new(method));
                    return Ok(Some(Object::Nil));
                }
                _ => {}
            }
        }

        // Special handling for Method objects
        if let Object::Method(method_obj) = receiver {
            match method_name {
                "name" => {
                    return Ok(Some(Object::String(Rc::new(method_obj.name.clone()))));
                }
                "owner" => {
                    let owner_name = method_obj.owner.as_deref().unwrap_or("main");
                    return Ok(Some(Object::String(Rc::new(owner_name.to_string()))));
                }
                "source_location" => {
                    if let Some(loc) = &method_obj.source_location {
                        return Ok(Some(Object::String(Rc::new(loc.to_string()))));
                    } else {
                        return Ok(Some(Object::String(Rc::new("unknown".to_string()))));
                    }
                }
                "parameters" => {
                    let params: Vec<Object> = method_obj
                        .parameters
                        .iter()
                        .map(|p| Object::String(Rc::new(p.clone())))
                        .collect();
                    return Ok(Some(Object::Array(Rc::new(std::cell::RefCell::new(
                        params,
                    )))));
                }
                "body" => {
                    return Ok(Some(ast_methods::serialize_statements(&method_obj.body)));
                }
                "arity" => {
                    return Ok(Some(Object::Int(method_obj.parameters.len() as i64)));
                }
                _ => {}
            }
        }

        // Special handling for Block objects (AST inspection)
        if let Object::Block(block_obj) = receiver {
            match method_name {
                "statements" => {
                    return Ok(Some(ast_methods::serialize_statements(&block_obj.body)));
                }
                "arity" => {
                    return Ok(Some(Object::Int(block_obj.parameters.len() as i64)));
                }
                _ => {}
            }
        }

        // Dispatch to the appropriate class-specific method implementation
        match class.name() {
            "Object" => self.call_object_method(receiver, method_name, arguments, position),
            "String" => self.call_string_method(receiver, method_name, arguments, position),
            "Integer" => self.call_int_method(receiver, method_name, arguments, position),
            "Array" => self.call_array_method(receiver, method_name, arguments, position),
            "Hash" => self.call_hash_method(receiver, method_name, arguments, position),
            "Float" => self.call_float_method(receiver, method_name, arguments, position),
            "Range" => self.call_range_method(receiver, method_name, arguments, position),
            "Set" => self.call_set_method(receiver, method_name, arguments, position),
            "Exception" => self.call_exception_method(receiver, method_name, arguments, position),
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the Object class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;

impl VirtualMachine {
    /// Execute native methods for the Object class.
    pub(crate) fn call_object_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "to_s" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(Object::string(receiver.to_string())))
            }
            "class" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(Object::Class(self.builtins().class_of(receiver))))
            }
            "respond_to?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                let method_query = match &arguments[0] {
                    Object::String(name) => name.as_str().to_string(),
                    other => {
                        return Err(method_argument_type_error(
                            method_name,
                            "String",
                            other,
                            position,
                        ));
                    }
                };
                Ok(Some(Object::Bool(
                    self.lookup_method(receiver, &method_query).is_some(),
                )))
            }
            "nil?" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                Ok(Some(Object::Bool(matches!(receiver, Object::Nil))))
            }
            "get_source" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                let query = match &arguments[0] {
                    Object::String(s) => s.as_str().to_string(),
                    Object::Symbol(s) => s.as_str().to_string(),
                    other => {
                        return Err(method_argument_type_error(
                            method_name,
                            "String or Symbol",
                            other,
                            position,
                        ));
                    }
                };
                match self.lookup_method(receiver, &query) {
                    Some((_class, method)) => Ok(Some(Object::Method(method))),
                    None => Ok(Some(Object::Nil)),
                }
            }
            "is_a?" | "kind_of?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                let target_class = match &arguments[0] {
                    Object::Class(c) => c,
                    other => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Class",
                            other,
                            position,
                        ));
                    }
                };
                Ok(Some(Object::Bool(
                    self.builtins().is_instance_of(receiver, target_class),
                )))
            }
            "instance_variables" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let vars = if let Object::Instance(inst_rc) = receiver {
                    let inst = inst_rc.borrow();
                    inst.instance_vars
                        .keys()
                        .map(|k| Object::string(format!("@{}", k)))
                        .collect()
                } else {
                    vec![]
                };
                Ok(Some(Object::Array(std::rc::Rc::new(
                    std::cell::RefCell::new(vars),
                ))))
            }
            "instance_variable_get" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                let var_name = match &arguments[0] {
                    Object::String(s) => s.as_str().to_string(),
                    Object::Symbol(s) => s.as_str().to_string(),
                    other => {
                        return Err(method_argument_type_error(
                            method_name,
                            "String or Symbol",
                            other,
                            position,
                        ));
                    }
                };
                // Strip leading @ if present
                let clean_name = var_name.strip_prefix('@').unwrap_or(&var_name);
                if let Object::Instance(inst_rc) = receiver {
                    let inst = inst_rc.borrow();
                    Ok(Some(
                        inst.instance_vars
                            .get(clean_name)
                            .cloned()
                            .unwrap_or(Object::Nil),
                    ))
                } else {
                    Ok(Some(Object::Nil))
                }
            }
            "dup" | "clone" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                match receiver {
                    Object::Instance(inst_rc) => {
                        let inst = inst_rc.borrow();
                        let mut new_inst =
                            crate::object::Instance::new(std::rc::Rc::clone(&inst.class));
                        for (k, v) in &inst.instance_vars {
                            new_inst.set_var(k.clone(), v.clone());
                        }
                        Ok(Some(Object::Instance(std::rc::Rc::new(
                            std::cell::RefCell::new(new_inst),
                        ))))
                    }
                    Object::Array(arr_rc) => {
                        let arr = arr_rc.borrow().clone();
                        Ok(Some(Object::Array(std::rc::Rc::new(
                            std::cell::RefCell::new(arr),
                        ))))
                    }
                    Object::Dict(dict_rc) => {
                        let dict = dict_rc.borrow().clone();
                        Ok(Some(Object::Dict(std::rc::Rc::new(
                            std::cell::RefCell::new(dict),
                        ))))
                    }
                    // Immutable types return themselves
                    _ => Ok(Some(receiver.clone())),
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the Range class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::cell::RefCell;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute native methods for the Range class.
    pub(crate) fn call_range_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "each" => {
                // each takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let pending = self.pending_block.take();
                if let Object::Range {
                    start,
                    end,
                    exclusive,
                } = receiver
                {
                    let block = match pending {
                        Some(Object::Block(b)) => b,
                        Some(other) => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Block",
                                &other,
                                position,
                            ));
                        }
                        None => {
                            return Err(MetorexError::runtime_error(
                                "each requires a block",
                                position_to_location(position),
                            ));
                        }
                    };

                    // Only support integer ranges for now
                    match (start.as_ref(), end.as_ref()) {
                        (Object::Int(start_val), Object::Int(end_val)) => {
                            let end_inclusive = if *exclusive { *end_val - 1 } else { *end_val };

                            for i in *start_val..=end_inclusive {
                                let args = vec![Object::Int(i)];
                                match self.execute_block_with_control_flow(&block, args)? {
                                    super::super::ControlFlow::Next
                                    | super::super::ControlFlow::Continue { .. } => continue,
                                    super::super::ControlFlow::Break { .. } => break,
                                    super::super::ControlFlow::Return { value: _, position } => {
                                        return Err(super::super::errors::loop_control_error(
                                            "return", position,
                                        ));
                                    }
                                    super::super::ControlFlow::Exception {
                                        exception,
                                        position,
                                    } => {
                                        return Err(MetorexError::runtime_error(
                                            format!(
                                                "Uncaught exception: {}",
                                                super::super::utils::format_exception(&exception)
                                            ),
                                            super::super::utils::position_to_location(position),
                                        ));
                                    }
                                }
                            }
                            Ok(Some(receiver.clone()))
                        }
                        _ => Err(MetorexError::runtime_error(
                            "Range.each only supports integer ranges".to_string(),
                            position_to_location(position),
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "to_a" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Range {
                    start,
                    end,
                    exclusive,
                } = receiver
                {
                    match (start.as_ref(), end.as_ref()) {
                        (Object::Int(start_val), Object::Int(end_val)) => {
                            let end_inclusive = if *exclusive { *end_val - 1 } else { *end_val };

                            let elements: Vec<Object> =
                                (*start_val..=end_inclusive).map(Object::Int).collect();
                            Ok(Some(Object::Array(Rc::new(RefCell::new(elements)))))
                        }
                        _ => Err(MetorexError::runtime_error(
                            "Range.to_a only supports integer ranges".to_string(),
                            position_to_location(position),
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "include?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Range {
                    start,
                    end,
                    exclusive,
                } = receiver
                {
                    match (start.as_ref(), end.as_ref(), &arguments[0]) {
                        (Object::Int(start_val), Object::Int(end_val), Object::Int(test_val)) => {
                            let in_range = if *exclusive {
                                *test_val >= *start_val && *test_val < *end_val
                            } else {
                                *test_val >= *start_val && *test_val <= *end_val
                            };
                            Ok(Some(Object::Bool(in_range)))
                        }
                        _ => Err(MetorexError::runtime_error(
                            "Range.include? only supports integer ranges".to_string(),
                            position_to_location(position),
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "map" => {
                // map takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let pending = self.pending_block.take();
                if let Object::Range {
                    start,
                    end,
                    exclusive,
                } = receiver
                {
                    let block = match pending {
                        Some(Object::Block(b)) => b,
                        Some(other) => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Block",
                                &other,
                                position,
                            ));
                        }
                        None => {
                            return Err(MetorexError::runtime_error(
                                "map requires a block",
                                position_to_location(position),
                            ));
                        }
                    };

                    // Only support integer ranges for now
                    match (start.as_ref(), end.as_ref()) {
                        (Object::Int(start_val), Object::Int(end_val)) => {
                            let end_inclusive = if *exclusive { *end_val - 1 } else { *end_val };

                            let mut results = Vec::new();
                            for i in *start_val..=end_inclusive {
                                let args = vec![Object::Int(i)];
                                let value = self.execute_block_body(&block, args)?;
                                results.push(value);
                            }
                            Ok(Some(Object::Array(Rc::new(RefCell::new(results)))))
                        }
                        _ => Err(MetorexError::runtime_error(
                            "Range.map only supports integer ranges".to_string(),
                            position_to_location(position),
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the Set class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::{Object, ObjectHash};
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use crate::vm::utils::position_to_location;
use std::cell::RefCell;
use std::collections::HashSet;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute native methods for the Set class.
    pub(crate) fn call_set_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "add" | "insert" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let hash = ObjectHash::from_object(&arguments[0]).ok_or_else(|| {
                        MetorexError::runtime_error(
                            format!(
                                "Cannot add {} to set (not hashable)",
                                arguments[0].type_name()
                            ),
                            position_to_location(position),
                        )
                    })?;
                    set_rc.borrow_mut().insert(hash);
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            "remove" | "delete" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let hash = ObjectHash::from_object(&arguments[0]).ok_or_else(|| {
                        MetorexError::runtime_error(
                            format!(
                                "Cannot remove {} from set (not hashable)",
                                arguments[0].type_name()
                            ),
                            position_to_location(position),
                        )
                    })?;
                    let removed = set_rc.borrow_mut().remove(&hash);
                    Ok(Some(Object::Bool(removed)))
                } else {
                    Ok(None)
                }
            }
            "contains?" | "include?" | "has?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let hash = match ObjectHash::from_object(&arguments[0]) {
                        Some(h) => h,
                        None => return Ok(Some(Object::Bool(false))),
                    };
                    Ok(Some(Object::Bool(set_rc.borrow().contains(&hash))))
                } else {
                    Ok(None)
                }
            }
            "size" | "length" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    Ok(Some(Object::Int(set_rc.borrow().len() as i64)))
                } else {
                    Ok(None)
                }
            }
            "empty?" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    Ok(Some(Object::Bool(set_rc.borrow().is_empty())))
                } else {
                    Ok(None)
                }
            }
            "to_a" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let elements: Vec<Object> = set_rc
                        .borrow()
                        .iter()
                        .map(|h| Object::string(h.hash_value.clone()))
                        .collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(elements)))))
                } else {
                    Ok(None)
                }
            }
            "union" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let other = match &arguments[0] {
                        Object::Set(other_rc) => other_rc,
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Set",
                                &arguments[0],
                                position,
                            ));
                        }
                    };
                    let result: HashSet<ObjectHash> =
                        set_rc.borrow().union(&other.borrow()).cloned().collect();
                    Ok(Some(Object::Set(Rc::new(RefCell::new(result)))))
                } else {
                    Ok(None)
                }
            }
            "intersection" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let other = match &arguments[0] {
                        Object::Set(other_rc) => other_rc,
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Set",
                                &arguments[0],
                                position,
                            ));
                        }
                    };
                    let result: HashSet<ObjectHash> = set_rc
                        .borrow()
                        .intersection(&other.borrow())
                        .cloned()
                        .collect();
                    Ok(Some(Object::Set(Rc::new(RefCell::new(result)))))
                } else {
                    Ok(None)
                }
            }
            "difference" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::Set(set_rc) = receiver {
                    let other = match &arguments[0] {
                        Object::Set(other_rc) => other_rc,
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Set",
                                &arguments[0],
                                position,
                            ));
                        }
                    };
                    let result: HashSet<ObjectHash> = set_rc
                        .borrow()
                        .difference(&other.borrow())
                        .cloned()
                        .collect();
                    Ok(Some(Object::Set(Rc::new(RefCell::new(result)))))
                } else {
                    Ok(None)
                }
            }
            "each" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "each requires a block",
                            position_to_location(position),
                        ));
                    }
                };
                if let Object::Set(set_rc) = receiver {
                    let elements: Vec<ObjectHash> = set_rc.borrow().iter().cloned().collect();
                    for elem in elements {
                        let args = vec![Object::string(elem.hash_value)];
                        match self.execute_block_with_control_flow(&block, args)? {
                            super::super::ControlFlow::Next
                            | super::super::ControlFlow::Continue { .. } => {
                                continue;
                            }
                            super::super::ControlFlow::Break { .. } => break,
                            super::super::ControlFlow::Return { value: _, position } => {
                                return Err(super::super::errors::loop_control_error(
                                    "return", position,
                                ));
                            }
                            super::super::ControlFlow::Exception {
                                exception,
                                position,
                            } => {
                                return Err(MetorexError::runtime_error(
                                    format!(
                                        "Uncaught exception: {}",
                                        super::super::utils::format_exception(&exception)
                                    ),
                                    super::super::utils::position_to_location(position),
                                ));
                            }
                        }
                    }
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Native method implementations for the String class.

use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use crate::vm::VirtualMachine;
use crate::vm::errors::*;
use std::cell::RefCell;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute native methods for the String class.
    pub(crate) fn call_string_method(
        &mut self,
        receiver: &Object,
        method_name: &str,
        arguments: &[Object],
        position: Position,
    ) -> Result<Option<Object>, MetorexError> {
        match method_name {
            "length" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::Int(string_value.chars().count() as i64)))
                } else {
                    Ok(None)
                }
            }
            "upcase" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::string(string_value.to_uppercase())))
                } else {
                    Ok(None)
                }
            }
            "downcase" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::string(string_value.to_lowercase())))
                } else {
                    Ok(None)
                }
            }
            "+" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let (Object::String(lhs), Object::String(rhs)) = (receiver, &arguments[0]) {
                    let mut combined = lhs.as_ref().clone();
                    combined.push_str(rhs);
                    Ok(Some(Object::string(combined)))
                } else {
                    Err(method_argument_type_error(
                        method_name,
                        "String",
                        &arguments[0],
                        position,
                    ))
                }
            }
            "trim" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::string(string_value.trim().to_string())))
                } else {
                    Ok(None)
                }
            }
            "reverse" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    let reversed: String = string_value.chars().rev().collect();
                    Ok(Some(Object::string(reversed)))
                } else {
                    Ok(None)
                }
            }
            "chars" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    let chars: Vec<Object> = string_value
                        .chars()
                        .map(|c| Object::string(c.to_string()))
                        .collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(chars)))))
                } else {
                    Ok(None)
                }
            }
            "bytes" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    let bytes: Vec<Object> = string_value
                        .bytes()
                        .map(|b| Object::Int(b as i64))
                        .collect();
                    Ok(Some(Object::Array(Rc::new(RefCell::new(bytes)))))
                } else {
                    Ok(None)
                }
            }
            "size" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::Int(string_value.chars().count() as i64)))
                } else {
                    Ok(None)
                }
            }
            "strip" => {
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    Ok(Some(Object::string(string_value.trim().to_string())))
                } else {
                    Ok(None)
                }
            }
            "split" => {
                if arguments.len() > 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    let parts: Vec<Object> = if arguments.is_empty() {
                        string_value
                            .split_whitespace()
                            .map(|s| Object::string(s.to_string()))
                            .collect()
                    } else {
                        match &arguments[0] {
                            Object::String(sep) => string_value
                                .split(sep.as_ref())
                                .map(|s| Object::string(s.to_string()))
                                .collect(),
                            _ => {
                                return Err(method_argument_type_error(
                                    method_name,
                                    "String",
                                    &arguments[0],
                                    position,
                                ));
                            }
                        }
                    };
                    Ok(Some(Object::Array(Rc::new(RefCell::new(parts)))))
                } else {
                    Ok(None)
                }
            }
            "slice" | "[]" => {
                if arguments.len() != 2 {
                    return Err(method_argument_error(
                        method_name,
                        2,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    let (start, len) = match (&arguments[0], &arguments[1]) {
                        (Object::Int(s), Object::Int(l)) => (*s, *l),
                        _ => {
                            return Err(method_argument_type_error(
                                method_name,
                                "Integer",
                                &arguments[0],
                                position,
                            ));
                        }
                    };
                    let chars: Vec<char> = string_value.chars().collect();
                    let char_count = chars.len() as i64;
                    let start_idx = if start < 0 {
                        (char_count + start).max(0) as usize
                    } else {
                        start.min(char_count) as usize
                    };
                    let end_idx = (start_idx as i64 + len).min(char_count).max(0) as usize;
                    if start_idx > chars.len() {
                        Ok(Some(Object::Nil))
                    } else {
                        let sliced: String =
                            chars[start_idx..end_idx.min(chars.len())].iter().collect();
                        Ok(Some(Object::string(sliced)))
                    }
                } else {
                    Ok(None)
                }
            }
            "include?" | "contains?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    match &arguments[0] {
                        Object::String(substr) => {
                            Ok(Some(Object::Bool(string_value.contains(substr.as_ref()))))
                        }
                        _ => Err(method_argument_type_error(
                            method_name,
                            "String",
                            &arguments[0],
                            position,
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "starts_with?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    match &arguments[0] {
                        Object::String(prefix) => Ok(Some(Object::Bool(
                            string_value.starts_with(prefix.as_ref()),
                        ))),
                        _ => Err(method_argument_type_error(
                            method_name,
                            "String",
                            &arguments[0],
                            position,
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "ends_with?" => {
                if arguments.len() != 1 {
                    return Err(method_argument_error(
                        method_name,
                        1,
                        arguments.len(),
                        position,
                    ));
                }
                if let Object::String(string_value) = receiver {
                    match &arguments[0] {
                        Object::String(suffix) => {
                            Ok(Some(Object::Bool(string_value.ends_with(suffix.as_ref()))))
                        }
                        _ => Err(method_argument_type_error(
                            method_name,
                            "String",
                            &arguments[0],
                            position,
                        )),
                    }
                } else {
                    Ok(None)
                }
            }
            "each_char" => {
                // each_char takes a trailing block (via pending_block)
                if !arguments.is_empty() {
                    return Err(method_argument_error(
                        method_name,
                        0,
                        arguments.len(),
                        position,
                    ));
                }
                let block = match self.pending_block.take() {
                    Some(Object::Block(b)) => b,
                    Some(other) => {
                        return Err(method_argument_type_error(
                            method_name,
                            "Block",
                            &other,
                            position,
                        ));
                    }
                    None => {
                        return Err(MetorexError::runtime_error(
                            "each_char requires a block",
                            crate::vm::utils::position_to_location(position),
                        ));
                    }
                };
                if let Object::String(string_value) = receiver {
                    for ch in string_value.chars() {
                        let char_str = Object::string(ch.to_string());
                        let args = vec![char_str];
                        self.execute_block_body(&block, args)?;
                    }
                    Ok(Some(receiver.clone()))
                } else {
                    Ok(None)
                }
            }
            _ => Ok(None),
        }
    }
}

//! Operator evaluation functions for the Metorex VM.
//!
//! This module contains the logic for evaluating unary and binary operators including:
//! - Unary operations (+, -)
//! - Binary operations (+, -, *, /, %)
//! - Comparison operations (<, >, <=, >=, ==, !=)

use crate::ast::{BinaryOp, UnaryOp};
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use std::rc::Rc;

use super::core::VirtualMachine;
use super::errors::{binary_type_error, divide_by_zero_error, unary_type_error};

impl VirtualMachine {
    /// Evaluate a unary operation (`+` or `-`).
    pub(crate) fn evaluate_unary_operation(
        &self,
        op: &UnaryOp,
        value: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match op {
            UnaryOp::Plus => match value {
                Object::Int(_) | Object::Float(_) => Ok(value),
                _ => Err(unary_type_error(op, &value, position)),
            },
            UnaryOp::Minus => match value {
                Object::Int(v) => Ok(Object::Int(-v)),
                Object::Float(v) => Ok(Object::Float(-v)),
                _ => Err(unary_type_error(op, &value, position)),
            },
            UnaryOp::Not => Ok(Object::Bool(matches!(
                value,
                Object::Bool(false) | Object::Nil
            ))),
        }
    }

    /// Evaluate a binary operation across runtime values.
    pub(crate) fn evaluate_binary_operation(
        &self,
        op: &BinaryOp,
        left: Object,
        right: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        use BinaryOp::*;

        match op {
            Add => self.evaluate_addition(left, right, position),
            Subtract | Multiply | Divide | Modulo => {
                self.evaluate_numeric_binary(op, left, right, position)
            }
            Equal => Ok(Object::Bool(left.equals(&right))),
            NotEqual => Ok(Object::Bool(!left.equals(&right))),
            Less | Greater | LessEqual | GreaterEqual => {
                self.evaluate_comparison(op, left, right, position)
            }
            And | Or => Err(MetorexError::internal_error(format!(
                "Logical operation '{:?}' should be handled by short-circuit evaluation",
                op
            ))),
            Assign | AddAssign | SubtractAssign | MultiplyAssign | DivideAssign => {
                Err(MetorexError::internal_error(format!(
                    "Assignment operation '{:?}' should be handled by statement execution",
                    op
                )))
            }
        }
    }

    /// Handle addition across supported operand types.
    pub(crate) fn evaluate_addition(
        &self,
        left: Object,
        right: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match (left, right) {
            (Object::Int(a), Object::Int(b)) => Ok(Object::Int(a + b)),
            (Object::Float(a), Object::Float(b)) => Ok(Object::Float(a + b)),
            (Object::Int(a), Object::Float(b)) => Ok(Object::Float((a as f64) + b)),
            (Object::Float(a), Object::Int(b)) => Ok(Object::Float(a + (b as f64))),
            (Object::String(a), Object::String(b)) => {
                let mut combined = a.as_ref().clone();
                combined.push_str(b.as_ref());
                Ok(Object::String(Rc::new(combined)))
            }
            (lhs, rhs) => Err(binary_type_error(BinaryOp::Add, &lhs, &rhs, position)),
        }
    }

    /// Evaluate numeric binary operations (`-`, `*`, `/`, `%`).
    pub(crate) fn evaluate_numeric_binary(
        &self,
        op: &BinaryOp,
        left: Object,
        right: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        match (left, right) {
            (Object::Int(a), Object::Int(b)) => match op {
                BinaryOp::Subtract => Ok(Object::Int(a - b)),
                BinaryOp::Multiply => Ok(Object::Int(a * b)),
                BinaryOp::Divide => {
                    if b == 0 {
                        Err(divide_by_zero_error(position))
                    } else if a % b == 0 {
                        Ok(Object::Int(a / b))
                    } else {
                        Ok(Object::Float((a as f64) / (b as f64)))
                    }
                }
                BinaryOp::Modulo => {
                    if b == 0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Int(a % b))
                    }
                }
                _ => unreachable!(),
            },
            (Object::Float(a), Object::Float(b)) => match op {
                BinaryOp::Subtract => Ok(Object::Float(a - b)),
                BinaryOp::Multiply => Ok(Object::Float(a * b)),
                BinaryOp::Divide => {
                    if b == 0.0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float(a / b))
                    }
                }
                BinaryOp::Modulo => {
                    if b == 0.0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float(a % b))
                    }
                }
                _ => unreachable!(),
            },
            (Object::Int(a), Object::Float(b)) => match op {
                BinaryOp::Subtract => Ok(Object::Float((a as f64) - b)),
                BinaryOp::Multiply => Ok(Object::Float((a as f64) * b)),
                BinaryOp::Divide => {
                    if b == 0.0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float((a as f64) / b))
                    }
                }
                BinaryOp::Modulo => {
                    if b == 0.0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float((a as f64) % b))
                    }
                }
                _ => unreachable!(),
            },
            (Object::Float(a), Object::Int(b)) => match op {
                BinaryOp::Subtract => Ok(Object::Float(a - (b as f64))),
                BinaryOp::Multiply => Ok(Object::Float(a * (b as f64))),
                BinaryOp::Divide => {
                    if b == 0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float(a / (b as f64)))
                    }
                }
                BinaryOp::Modulo => {
                    if b == 0 {
                        Err(divide_by_zero_error(position))
                    } else {
                        Ok(Object::Float(a % (b as f64)))
                    }
                }
                _ => unreachable!(),
            },
            (lhs, rhs) => Err(binary_type_error(op.clone(), &lhs, &rhs, position)),
        }
    }

    /// Evaluate comparison operations on numeric operands.
    pub(crate) fn evaluate_comparison(
        &self,
        op: &BinaryOp,
        left: Object,
        right: Object,
        position: Position,
    ) -> Result<Object, MetorexError> {
        let (lhs, rhs) = match (&left, &right) {
            (Object::Int(a), Object::Int(b)) => (*a as f64, *b as f64),
            (Object::Float(a), Object::Float(b)) => (*a, *b),
            (Object::Int(a), Object::Float(b)) => (*a as f64, *b),
            (Object::Float(a), Object::Int(b)) => (*a, *b as f64),
            (lhs, rhs) => {
                return Err(binary_type_error(op.clone(), lhs, rhs, position));
            }
        };

        let result = match op {
            BinaryOp::Less => lhs < rhs,
            BinaryOp::Greater => lhs > rhs,
            BinaryOp::LessEqual => lhs <= rhs,
            BinaryOp::GreaterEqual => lhs >= rhs,
            _ => unreachable!(),
        };

        Ok(Object::Bool(result))
    }
}

// Pattern matching execution for the Metorex VM.
// This module handles match statements and pattern matching logic.

use super::ControlFlow;
use super::core::VirtualMachine;
use super::utils::*;

use crate::ast::node::ExprMatchCase;
use crate::ast::{Expression, Statement};
use crate::error::MetorexError;
use crate::lexer::Position;
use crate::object::Object;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

impl VirtualMachine {
    /// Execute a match statement for pattern matching.
    pub(crate) fn execute_match(
        &mut self,
        expression: &Expression,
        cases: &[crate::ast::MatchCase],
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        // Evaluate the value to match against
        let match_value = self.evaluate_expression(expression)?;

        // Try each case in order
        for case in cases {
            // Try to match the pattern
            let mut bindings: HashMap<String, Object> = HashMap::new();
            if self.match_pattern(&case.pattern, &match_value, &mut bindings, position)? {
                // Pattern matched! Now check guard if present
                if !self.evaluate_guard_with_bindings(case.guard.as_ref(), &bindings)? {
                    continue;
                }

                // Pattern and guard matched! Execute the body with bindings
                self.environment_mut().push_scope();
                self.apply_pattern_bindings(&bindings);

                // Execute the body and track the last expression value
                let mut last_value = Object::Nil;
                for statement in &case.body {
                    // If it's an expression statement, track its value
                    if let Statement::Expression { expression, .. } = statement {
                        last_value = self.evaluate_expression(expression)?;
                        continue;
                    }

                    // Execute other statements
                    match self.execute_statement(statement)? {
                        ControlFlow::Next => {}
                        flow => {
                            self.environment_mut().pop_scope();
                            return Ok(flow);
                        }
                    }
                }

                self.environment_mut().pop_scope();

                // Return the last expression value using Return control flow
                // (but this is not a true return statement, just a value)
                return Ok(ControlFlow::Return {
                    value: last_value,
                    position,
                });
            }
        }

        // No pattern matched
        Err(MetorexError::runtime_error(
            format!("No pattern matched value: {}", match_value),
            position_to_location(position),
        ))
    }

    /// Execute a `case/in` statement (Ruby 2.7+ pattern matching).
    /// Raises `NoMatchingPatternError` if no arm matches and no else clause is present.
    pub(crate) fn execute_case_in(
        &mut self,
        expression: &Expression,
        cases: &[crate::ast::MatchCase],
        position: Position,
    ) -> Result<ControlFlow, MetorexError> {
        let match_value = self.evaluate_expression(expression)?;

        for case in cases {
            let mut bindings: HashMap<String, Object> = HashMap::new();
            if self.match_pattern(&case.pattern, &match_value, &mut bindings, position)? {
                if !self.evaluate_guard_with_bindings(case.guard.as_ref(), &bindings)? {
                    continue;
                }

                self.environment_mut().push_scope();
                self.apply_pattern_bindings(&bindings);

                let mut last_value = Object::Nil;
                for statement in &case.body {
                    if let Statement::Expression { expression, .. } = statement {
                        last_value = self.evaluate_expression(expression)?;
                        continue;
                    }
                    match self.execute_statement(statement)? {
                        ControlFlow::Next => {}
                        flow => {
                            self.environment_mut().pop_scope();
                            return Ok(flow);
                        }
                    }
                }

                self.environment_mut().pop_scope();
                return Ok(ControlFlow::Return {
                    value: last_value,
                    position,
                });
            }
        }

        Err(MetorexError::runtime_error(
            format!(
                "NoMatchingPatternError: {} (NoMatchingPatternError)",
                match_value
            ),
            position_to_location(position),
        ))
    }

    /// Match a pattern against a value and collect variable bindings.
    /// Returns true if the pattern matches, false otherwise.
    pub(crate) fn match_pattern(
        &self,
        pattern: &crate::ast::MatchPattern,
        value: &Object,
        bindings: &mut HashMap<String, Object>,
        position: Position,
    ) -> Result<bool, MetorexError> {
        use crate::ast::MatchPattern;

        match pattern {
            // Literal patterns - exact equality match
            MatchPattern::IntLiteral(pattern_int) => match value {
                Object::Int(value_int) => Ok(pattern_int == value_int),
                _ => Ok(false),
            },
            MatchPattern::FloatLiteral(pattern_float) => match value {
                Object::Float(value_float) => {
                    // Use approximate equality for floats
                    Ok((pattern_float - value_float).abs() < f64::EPSILON)
                }
                _ => Ok(false),
            },
            MatchPattern::StringLiteral(pattern_string) => match value {
                Object::String(value_string) => Ok(pattern_string == value_string.as_ref()),
                _ => Ok(false),
            },
            MatchPattern::BoolLiteral(pattern_bool) => match value {
                Object::Bool(value_bool) => Ok(pattern_bool == value_bool),
                _ => Ok(false),
            },
            MatchPattern::NilLiteral => Ok(matches!(value, Object::Nil)),

            // Identifier pattern - binds the value to a variable
            MatchPattern::Identifier(name) => {
                bindings.insert(name.clone(), value.clone());
                Ok(true)
            }

            // Wildcard pattern - matches anything without binding
            MatchPattern::Wildcard => Ok(true),

            // Array pattern - destructure arrays
            MatchPattern::Array(patterns) => match value {
                Object::Array(array_rc) => {
                    let array = array_rc.borrow();
                    self.match_array_pattern(patterns, &array, bindings, position)
                }
                _ => Ok(false),
            },

            // Rest pattern - should only appear inside array patterns
            MatchPattern::Rest(_) => Err(MetorexError::runtime_error(
                "Rest pattern (...) can only be used inside array patterns".to_string(),
                position_to_location(position),
            )),

            // Object pattern - destructure dictionaries
            MatchPattern::Object(key_patterns) => match value {
                Object::Dict(dict_rc) => {
                    let dict = dict_rc.borrow();
                    self.match_object_pattern(key_patterns, &dict, bindings, position)
                }
                _ => Ok(false),
            },

            // Type pattern - match based on object type
            MatchPattern::Type(type_name) => {
                let actual_type = value.type_name();

                // Support both Ruby-style names (Integer, Hash) and internal names (Int, Dict)
                let matches = match type_name.as_str() {
                    // Direct type name matches
                    name if name == actual_type => true,

                    // Ruby-style aliases
                    "Integer" => matches!(value, Object::Int(_)),
                    "Float" => matches!(value, Object::Float(_)),
                    "String" => matches!(value, Object::String(_)),
                    "Array" => matches!(value, Object::Array(_)),
                    "Hash" | "Dict" => matches!(value, Object::Dict(_)),
                    "TrueClass" | "FalseClass" | "Boolean" => matches!(value, Object::Bool(_)),
                    "NilClass" => matches!(value, Object::Nil),
                    "Class" => matches!(value, Object::Class(_)),
                    "Method" => matches!(value, Object::Method(_)),
                    "Exception" => matches!(value, Object::Exception(_)),
                    "Set" => matches!(value, Object::Set(_)),
                    "Range" => matches!(value, Object::Range { .. }),

                    // Check for class instances
                    _ => {
                        if let Object::Instance(instance_rc) = value {
                            let instance = instance_rc.borrow();
                            instance.class_name() == *type_name
                        } else {
                            false
                        }
                    }
                };

                Ok(matches)
            }

            // Multiple pattern - OR matching (matches if any sub-pattern matches)
            // Used for: when 1, 2, 3 then "small"
            MatchPattern::Multiple(patterns) => {
                for pattern in patterns {
                    // Try each pattern - if any matches, the whole Multiple pattern matches
                    // Important: we need to preserve bindings only from the matching pattern
                    let mut temp_bindings = HashMap::new();
                    if self.match_pattern(pattern, value, &mut temp_bindings, position)? {
                        // This pattern matched - merge bindings and return true
                        bindings.extend(temp_bindings);
                        return Ok(true);
                    }
                }
                // None of the patterns matched
                Ok(false)
            }

            // Bind pattern: match inner pattern and bind the whole value to a name
            // Used in case/in: `in Integer => n`
            MatchPattern::Bind { pattern, name } => {
                if self.match_pattern(pattern, value, bindings, position)? {
                    bindings.insert(name.clone(), value.clone());
                    Ok(true)
                } else {
                    Ok(false)
                }
            }

            // Range pattern: matches if value falls within start..end or start...end
            MatchPattern::Range {
                start,
                end,
                exclusive,
            } => {
                // Extract numeric value for comparison
                let val_num = match value {
                    Object::Int(n) => *n as f64,
                    Object::Float(f) => *f,
                    _ => return Ok(false),
                };

                // Extract start bound
                let start_num = match start.as_ref() {
                    MatchPattern::IntLiteral(n) => *n as f64,
                    MatchPattern::FloatLiteral(f) => *f,
                    _ => return Ok(false),
                };

                // Extract end bound
                let end_num = match end.as_ref() {
                    MatchPattern::IntLiteral(n) => *n as f64,
                    MatchPattern::FloatLiteral(f) => *f,
                    _ => return Ok(false),
                };

                let in_range = if *exclusive {
                    val_num >= start_num && val_num < end_num
                } else {
                    val_num >= start_num && val_num <= end_num
                };

                Ok(in_range)
            }
        }
    }

    /// Match an array pattern against an array value.
    pub(crate) fn match_array_pattern(
        &self,
        patterns: &[crate::ast::MatchPattern],
        array: &[Object],
        bindings: &mut HashMap<String, Object>,
        position: Position,
    ) -> Result<bool, MetorexError> {
        use crate::ast::MatchPattern;

        // Find if there's a rest pattern and where
        let mut rest_index = None;
        for (i, pattern) in patterns.iter().enumerate() {
            if matches!(pattern, MatchPattern::Rest(_)) {
                if rest_index.is_some() {
                    return Err(MetorexError::runtime_error(
                        "Only one rest pattern (...) is allowed per array pattern".to_string(),
                        position_to_location(position),
                    ));
                }
                rest_index = Some(i);
            }
        }

        if let Some(rest_idx) = rest_index {
            // Array pattern with rest
            let patterns_before = &patterns[..rest_idx];
            let patterns_after = &patterns[rest_idx + 1..];
            let min_length = patterns_before.len() + patterns_after.len();

            // Array must have at least min_length elements
            if array.len() < min_length {
                return Ok(false);
            }

            // Match patterns before rest
            for (i, pattern) in patterns_before.iter().enumerate() {
                if !self.match_pattern(pattern, &array[i], bindings, position)? {
                    return Ok(false);
                }
            }

            // Match patterns after rest
            let rest_start = rest_idx;
            let rest_end = array.len() - patterns_after.len();
            for (i, pattern) in patterns_after.iter().enumerate() {
                if !self.match_pattern(pattern, &array[rest_end + i], bindings, position)? {
                    return Ok(false);
                }
            }

            // Bind rest elements
            if let MatchPattern::Rest(rest_name) = &patterns[rest_idx] {
                let rest_elements: Vec<Object> = array[rest_start..rest_end].to_vec();
                bindings.insert(
                    rest_name.clone(),
                    Object::Array(Rc::new(RefCell::new(rest_elements))),
                );
            }

            Ok(true)
        } else {
            // Array pattern without rest - exact length match required
            if patterns.len() != array.len() {
                return Ok(false);
            }

            // Match each pattern against corresponding element
            for (pattern, element) in patterns.iter().zip(array.iter()) {
                if !self.match_pattern(pattern, element, bindings, position)? {
                    return Ok(false);
                }
            }

            Ok(true)
        }
    }

    /// Match an object/dictionary pattern against a dictionary value.
    pub(crate) fn match_object_pattern(
        &self,
        key_patterns: &[(String, crate::ast::MatchPattern)],
        dict: &HashMap<String, Object>,
        bindings: &mut HashMap<String, Object>,
        position: Position,
    ) -> Result<bool, MetorexError> {
        // Each key must exist in the dictionary and match its pattern
        for (key, pattern) in key_patterns {
            match dict.get(key) {
                Some(value) => {
                    if !self.match_pattern(pattern, value, bindings, position)? {
                        return Ok(false);
                    }
                }
                None => return Ok(false), // Key not found in dictionary
            }
        }

        Ok(true)
    }

    /// Apply variable bindings from pattern matching to the current scope.
    /// Helper method to reduce code duplication between match statement and case expression.
    fn apply_pattern_bindings(&mut self, bindings: &HashMap<String, Object>) {
        for (name, value) in bindings {
            self.environment_mut().define(name.clone(), value.clone());
        }
    }

    /// Evaluate a guard expression with pattern bindings in a new scope.
    /// Returns true if the guard passes (is truthy) or if there's no guard.
    /// Returns false if the guard fails (is not truthy).
    /// Helper method to reduce code duplication between match statement and case expression.
    fn evaluate_guard_with_bindings(
        &mut self,
        guard_expr: Option<&Expression>,
        bindings: &HashMap<String, Object>,
    ) -> Result<bool, MetorexError> {
        if let Some(guard) = guard_expr {
            // Push a new scope for guard evaluation with bindings
            self.environment_mut().push_scope();
            self.apply_pattern_bindings(bindings);

            let guard_result = self.evaluate_expression(guard)?;
            self.environment_mut().pop_scope();

            // Return whether the guard is truthy
            Ok(is_truthy(&guard_result))
        } else {
            // No guard means it always passes
            Ok(true)
        }
    }

    /// Evaluate a case expression (pattern matching in expression context).
    /// Returns the value of the first matching case's body expression.
    pub(crate) fn evaluate_case_expression(
        &mut self,
        expression: &Expression,
        cases: &[ExprMatchCase],
        else_case: Option<&Expression>,
        _position: Position,
    ) -> Result<Object, MetorexError> {
        // Evaluate the value to match against
        let match_value = self.evaluate_expression(expression)?;

        // Try each case in order
        for case in cases {
            // Try to match the pattern
            let mut bindings: HashMap<String, Object> = HashMap::new();
            if self.match_pattern(&case.pattern, &match_value, &mut bindings, case.position)? {
                // Pattern matched! Now check guard if present
                if !self.evaluate_guard_with_bindings(case.guard.as_ref(), &bindings)? {
                    continue;
                }

                // Pattern and guard matched! Evaluate the body expression with bindings
                self.environment_mut().push_scope();
                self.apply_pattern_bindings(&bindings);

                let result = self.evaluate_expression(&case.body)?;
                self.environment_mut().pop_scope();

                return Ok(result);
            }
        }

        // No pattern matched - evaluate else case if present, otherwise return nil
        if let Some(else_expr) = else_case {
            self.evaluate_expression(else_expr)
        } else {
            Ok(Object::Nil)
        }
    }
}

// Core statement execution logic for the Metorex VM.
// This module handles the dispatcher and basic statement execution.

use super::ControlFlow;
use super::core::VirtualMachine;
use super::errors::*;
use super::utils::*;

use crate::ast::{Expression, Statement};
use crate::error::MetorexError;
use crate::object::Object;
use std::rc::Rc;

impl VirtualMachine {
    /// Evaluate a statement and produce control-flow information for the caller.
    pub(crate) fn execute_statement(
        &mut self,
        statement: &Statement,
    ) -> Result<ControlFlow, MetorexError> {
        match statement {
            Statement::Expression {
                expression,
                position,
            } => {
                let result = self.evaluate_expression(expression)?;

                // Ruby-style auto-call: if expression statement evaluates to a Method
                // and the expression is a bare identifier, auto-call it with zero args
                if matches!(expression, Expression::Identifier { .. })
                    && matches!(result, Object::Method(_))
                {
                    self.invoke_callable(result, vec![], *position)?;
                    return Ok(ControlFlow::Next);
                }

                Ok(ControlFlow::Next)
            }
            Statement::Assignment {
                target,
                value,
                position: _,
            } => {
                let evaluated = self.evaluate_expression(value)?;
                self.assign_value(target, evaluated)?;
                Ok(ControlFlow::Next)
            }
            Statement::Return { value, position } => {
                let result = match value {
                    Some(expr) => self.evaluate_expression(expr)?,
                    None => Object::Nil,
                };
                Ok(ControlFlow::Return {
                    value: result,
                    position: *position,
                })
            }
            Statement::Break { position } => Ok(ControlFlow::Break {
                position: *position,
            }),
            Statement::Continue { position } => Ok(ControlFlow::Continue {
                position: *position,
            }),
            Statement::Block {
                statements,
                position: _,
            } => self.execute_block(statements),
            Statement::If {
                condition,
                then_branch,
                elsif_branches,
                else_branch,
                position: _,
            } => self.execute_if(condition, then_branch, elsif_branches, else_branch),
            Statement::Unless {
                condition,
                then_branch,
                else_branch,
                position: _,
            } => self.execute_unless(condition, then_branch, else_branch),
            Statement::While {
                condition,
                body,
                position: _,
            } => self.execute_while(condition, body),
            Statement::For {
                variable,
                iterable,
                body,
                position,
            } => self.execute_for(variable, iterable, body, *position),
            Statement::ClassDef {
                name,
                superclass,
                body,
                position,
            } => self.execute_class_def(name, superclass.as_deref(), body, *position),
            Statement::MethodDef { .. } => {
                // MethodDef should only appear inside ClassDef bodies, not at top level
                Err(unimplemented_statement_error(statement))
            }
            Statement::Begin {
                body,
                rescue_clauses,
                else_clause,
                ensure_block,
                position,
            } => self.execute_begin(body, rescue_clauses, else_clause, ensure_block, *position),
            Statement::Raise {
                exception,
                position,
            } => self.execute_raise(exception, *position),
            Statement::Match {
                expression,
                cases,
                position,
            } => self.execute_match(expression, cases, *position),
            Statement::CaseIn {
                expression,
                cases,
                position,
            } => self.execute_case_in(expression, cases, *position),
            Statement::FunctionDef {
                name,
                parameters,
                body,
                position,
            } => self.execute_function_def(name, parameters, body, *position),
            Statement::AttrReader { position, .. }
            | Statement::AttrWriter { position, .. }
            | Statement::AttrAccessor { position, .. } => {
                // These are only processed during class definition, not as standalone statements
                Err(MetorexError::runtime_error(
                    "attr_reader, attr_writer, and attr_accessor can only be used inside a class definition",
                    position_to_location(*position),
                ))
            }
            Statement::ModuleDef {
                name,
                body,
                position,
            } => self.execute_module_def(name, body, *position),
            Statement::Include {
                module_name,
                position,
            } => self.execute_include(module_name, *position),
            Statement::Extend {
                module_name,
                position,
            } => self.execute_extend(module_name, *position),
        }
    }

    /// Execute statements within a new lexical scope.
    pub(crate) fn execute_block(
        &mut self,
        statements: &[Statement],
    ) -> Result<ControlFlow, MetorexError> {
        self.environment_mut().push_scope();
        let result = self.execute_statements_internal(statements);
        self.environment_mut().pop_scope();
        result
    }

    /// Core statement execution loop used by program and block execution.
    pub(crate) fn execute_statements_internal(
        &mut self,
        statements: &[Statement],
    ) -> Result<ControlFlow, MetorexError> {
        for statement in statements {
            match self.execute_statement(statement)? {
                ControlFlow::Next => continue,
                flow => return Ok(flow),
            }
        }
        Ok(ControlFlow::Next)
    }

    /// Assign a value to the given target expression.
    pub(crate) fn assign_value(
        &mut self,
        target: &Expression,
        value: Object,
    ) -> Result<(), MetorexError> {
        match target {
            Expression::Identifier { name, .. } => {
                if !self.environment_mut().set(name, value.clone()) {
                    self.environment_mut().define(name.clone(), value);
                }
                Ok(())
            }
            Expression::InstanceVariable { name, position } => {
                // Instance variables can only be set within a method (where 'self' is defined)
                match self.environment().get("self") {
                    Some(Object::Instance(instance_rc)) => {
                        let mut instance = instance_rc.borrow_mut();
                        instance.set_var(name.clone(), value);
                        Ok(())
                    }
                    Some(_) => Err(MetorexError::runtime_error(
                        format!("Cannot set instance variable @{} on non-instance", name),
                        position_to_location(*position),
                    )),
                    None => Err(MetorexError::runtime_error(
                        format!(
                            "Instance variable @{} can only be used within a method",
                            name
                        ),
                        position_to_location(*position),
                    )),
                }
            }
            Expression::ClassVariable { name, position } => {
                // Class variables can only be set within a method or class context
                // For now, we'll look for 'self' to get the class
                match self.environment().get("self") {
                    Some(Object::Instance(instance_rc)) => {
                        let instance = instance_rc.borrow();
                        instance.class.set_class_var(name.clone(), value);
                        Ok(())
                    }
                    Some(Object::Class(class)) => {
                        class.set_class_var(name.clone(), value);
                        Ok(())
                    }
                    Some(_) => Err(MetorexError::runtime_error(
                        format!("Cannot set class variable @@{} in this context", name),
                        position_to_location(*position),
                    )),
                    None => Err(MetorexError::runtime_error(
                        format!(
                            "Class variable @@{} can only be used within a class or method",
                            name
                        ),
                        position_to_location(*position),
                    )),
                }
            }
            Expression::Index {
                array,
                index,
                position,
            } => {
                // Evaluate the array/object and index
                let obj = self.evaluate_expression(array)?;
                let idx = self.evaluate_expression(index)?;

                match obj {
                    Object::Array(array_rc) => {
                        // Array index assignment
                        if let Object::Int(i) = idx {
                            let mut array = array_rc.borrow_mut();
                            let len = array.len() as i64;
                            let actual_index = if i < 0 { len + i } else { i };

                            if actual_index < 0 || actual_index >= len {
                                return Err(MetorexError::runtime_error(
                                    format!("Array index out of bounds: {}", i),
                                    position_to_location(*position),
                                ));
                            }
                            array[actual_index as usize] = value;
                            Ok(())
                        } else {
                            Err(MetorexError::runtime_error(
                                "Array index must be an integer",
                                position_to_location(*position),
                            ))
                        }
                    }
                    Object::Dict(dict_rc) => {
                        // Hash/Dict index assignment
                        let key_str = match idx {
                            Object::String(s) => s.as_str().to_string(),
                            Object::Int(i) => i.to_string(),
                            Object::Float(f) => f.to_string(),
                            Object::Bool(b) => b.to_string(),
                            Object::Nil => "nil".to_string(),
                            _ => {
                                return Err(MetorexError::runtime_error(
                                    "Hash key must be a String, Integer, Float, Bool, or Nil",
                                    position_to_location(*position),
                                ));
                            }
                        };
                        let mut dict = dict_rc.borrow_mut();
                        dict.insert(key_str, value);
                        Ok(())
                    }
                    Object::Instance(instance_rc) => {
                        // Dispatch to user-defined []= method
                        let class = Rc::clone(&instance_rc.borrow().class);
                        if let Some(method) = class.find_method("[]=") {
                            self.invoke_method(
                                class,
                                method,
                                Object::Instance(instance_rc),
                                vec![idx, value],
                                *position,
                            )?;
                            Ok(())
                        } else {
                            Err(MetorexError::runtime_error(
                                "No []= method defined on instance",
                                position_to_location(*position),
                            ))
                        }
                    }
                    _ => Err(MetorexError::runtime_error(
                        "Cannot index assign on this type",
                        position_to_location(*position),
                    )),
                }
            }
            Expression::MethodCall {
                receiver,
                method,
                arguments,
                position,
                ..
            } => {
                // Handle setter method calls (e.g., obj.name = value becomes obj.name=(value))
                if arguments.is_empty() {
                    // This is a setter method call: obj.method = value -> obj.method=(value)
                    let setter_method = format!("{}=", method);
                    let receiver_obj = self.evaluate_expression(receiver)?;

                    // Look up the setter method and invoke it
                    match receiver_obj {
                        Object::Instance(instance_rc) => {
                            let (class, method_obj) = {
                                let instance = instance_rc.borrow();
                                let class = instance.class.clone();
                                let method_obj = instance.class.find_method(&setter_method);
                                (class, method_obj)
                            }; // Borrow is dropped here

                            if let Some(method) = method_obj {
                                self.invoke_method(
                                    class,
                                    method,
                                    Object::Instance(Rc::clone(&instance_rc)),
                                    vec![value],
                                    *position,
                                )?;
                                Ok(())
                            } else {
                                Err(MetorexError::runtime_error(
                                    format!("Undefined setter method '{}'", setter_method),
                                    position_to_location(*position),
                                ))
                            }
                        }
                        _ => Err(MetorexError::runtime_error(
                            format!(
                                "Cannot call setter method '{}' on {}",
                                setter_method,
                                receiver_obj.type_name()
                            ),
                            position_to_location(*position),
                        )),
                    }
                } else {
                    Err(MetorexError::runtime_error(
                        "Cannot assign to method call with arguments",
                        position_to_location(*position),
                    ))
                }
            }
            Expression::GlobalVariable { name, .. } => {
                self.globals_mut().set(name.clone(), value);
                Ok(())
            }
            _ => Err(invalid_assignment_target_error(target)),
        }
    }
}

//! Utility functions for the Metorex virtual machine.
//!
//! This module provides common helper functions used throughout the VM implementation.

use crate::error::SourceLocation;
use crate::lexer::Position;
use crate::object::Object;

/// Convert a lexer position into a runtime source location.
pub(super) fn position_to_location(position: Position) -> SourceLocation {
    SourceLocation::new(position.line, position.column, position.offset)
}

/// Format an exception object for display.
pub(super) fn format_exception(exception: &Object) -> String {
    match exception {
        Object::Exception(ex) => {
            let exc = ex.borrow();
            format!("{}: {}", exc.exception_type, exc.message)
        }
        _ => format!("{:?}", exception),
    }
}

/// Convert an object into a dictionary key string representation.
pub(super) fn object_to_dict_key(value: &Object) -> Option<String> {
    match value {
        Object::String(s) => Some((**s).clone()),
        Object::Symbol(s) => Some(format!(":{}", s)),
        Object::Int(i) => Some(i.to_string()),
        Object::Float(f) => Some(f.to_string()),
        Object::Bool(b) => Some(b.to_string()),
        Object::Nil => Some("nil".to_string()),
        _ => None,
    }
}

/// Determine if a value is truthy for conditional statements.
/// In Metorex, only `false` and `nil` are falsy; everything else is truthy.
pub(super) fn is_truthy(value: &Object) -> bool {
    !matches!(value, Object::Bool(false) | Object::Nil)
}
